//! Integration tests for the succinctly jq CLI command
//!
//! These tests verify jq-compatible behavior and options.
//! Run with: cargo test --features cli --test jq_cli_tests
#![cfg(feature = "cli")]

use std::io::Write;
use std::process::{Command, Stdio};

use anyhow::Result;
use proptest::prelude::*;
use tempfile::NamedTempFile;

#[path = "common/cargo_run_exit.rs"]
mod cargo_run_exit;
use cargo_run_exit::{
    classify_cargo_run_exit, signal_death_error, spawn_with_signal_retry, succinctly_bin,
    write_stdin_then_wait, MAX_CARGO_RETRIES,
};

/// #1516: a signal-killed child used to render as an inscrutable
/// `left: -1, right: 0` panic -- exercises `classify_cargo_run_exit`
/// directly against constructed `ExitStatus` values (via
/// `ExitStatusExt::from_raw`) rather than by actually killing a `cargo run`
/// child, which would make the test itself exactly as flaky as the bug it
/// pins.
#[cfg(unix)]
#[test]
fn test_classify_cargo_run_exit_reports_signal_death_1516() {
    use std::os::unix::process::ExitStatusExt;
    use std::process::ExitStatus;

    // Raw wait-status encoding (see `man 2 wait`): a signal death stores the
    // signal number in the low 7 bits with no exit-code shift; SIGKILL is 9.
    let killed = ExitStatus::from_raw(9);
    assert_eq!(
        killed.code(),
        None,
        "sanity: from_raw(9) must look signal-killed"
    );

    // On the last allowed attempt, a signal death must be a real error --
    // naming the signal and the captured stderr -- not `Ok(Some(-1))`.
    let err = classify_cargo_run_exit(
        killed,
        "some stderr output",
        MAX_CARGO_RETRIES - 1,
        MAX_CARGO_RETRIES,
    )
    .expect_err("a signal death on the last attempt must error, not return a fake exit code");
    let msg = err.to_string();
    assert!(
        msg.contains("signal 9"),
        "expected the signal number in the message: {msg}"
    );
    assert!(
        msg.contains("some stderr output"),
        "expected captured stderr in the message: {msg}"
    );

    // Within the retry budget, the same signal death asks the caller to
    // retry instead of erroring immediately -- at both the first attempt
    // and an interior one (`MAX_CARGO_RETRIES` is 3, so attempt 1 is the
    // only non-boundary value).
    assert_eq!(
        classify_cargo_run_exit(killed, "", 0, MAX_CARGO_RETRIES).unwrap(),
        None,
        "a signal death within retry budget should ask for a retry"
    );
    assert_eq!(
        classify_cargo_run_exit(killed, "", 1, MAX_CARGO_RETRIES).unwrap(),
        None,
        "a signal death on an interior attempt should still ask for a retry"
    );

    // Exit code 101 (lock contention) keeps its pre-existing retry
    // behavior unchanged.
    let contention = ExitStatus::from_raw(101 << 8);
    assert_eq!(
        contention.code(),
        Some(101),
        "sanity: from_raw encodes exit code 101"
    );
    assert_eq!(
        classify_cargo_run_exit(contention, "", 0, MAX_CARGO_RETRIES).unwrap(),
        None,
        "101 within retry budget should still retry"
    );
    assert_eq!(
        classify_cargo_run_exit(contention, "", 1, MAX_CARGO_RETRIES).unwrap(),
        None,
        "101 on an interior attempt should still retry"
    );
    assert_eq!(
        classify_cargo_run_exit(contention, "", MAX_CARGO_RETRIES - 1, MAX_CARGO_RETRIES).unwrap(),
        Some(101),
        "101 with no retries left surfaces as-is, same as before this change"
    );

    // A genuine, non-101 exit code passes through unchanged regardless of
    // attempt number.
    assert_eq!(
        classify_cargo_run_exit(ExitStatus::from_raw(0), "", 0, MAX_CARGO_RETRIES).unwrap(),
        Some(0)
    );
    assert_eq!(
        classify_cargo_run_exit(ExitStatus::from_raw(1 << 8), "", 0, MAX_CARGO_RETRIES).unwrap(),
        Some(1)
    );
}

/// Helper to run jq command with input from stdin
fn run_jq_stdin(filter: &str, input: &str, extra_args: &[&str]) -> Result<(String, i32)> {
    let (stdout, _, code) = run_jq_stdin_streams(filter, input, extra_args)?;
    Ok((stdout, code))
}

/// Helper to run jq command with input from stdin, keeping stderr.
///
/// Most tests only care about stdout and the exit code; use this when the
/// absence of a diagnostic is itself the thing under test. Delegates to
/// `run_jq_full`, which execs the pre-built binary directly (#1859), so
/// stderr here is exactly the binary's own -- no cargo output to filter.
fn run_jq_stdin_streams(
    filter: &str,
    input: &str,
    extra_args: &[&str],
) -> Result<(String, String, i32)> {
    let mut args: Vec<&str> = extra_args.to_vec();
    args.push(filter);
    run_jq_full(&args, Some(input))
}

/// Run jq with an arbitrary argument list, returning stdout, stderr and the
/// exit code.
///
/// `run_jq_stdin` discards stderr and cannot take file arguments, which makes
/// it unusable for the diagnostics in #355 — those live entirely on stderr and
/// in the exit code, and their `(at <file>:<line>)` marker needs a real file.
///
/// Invokes the built binary directly rather than through `cargo run` (#1859):
/// cargo writes its own `Finished`/`Running` progress lines to stderr, which
/// would be indistinguishable from the diagnostics under test, and that also
/// makes the lock-contention retry unnecessary. Delegates to the shared
/// `spawn_jq` (in turn `spawn_with_signal_retry`, #1884 code review) rather
/// than a file-local reimplementation, so this file's ~190
/// `run_jq_stdin`/`run_jq_null`-routed call sites get the same
/// spawn/signal-death retry the four files #1847 migrated already share --
/// a file-local copy here would have been a fifth, independently-drifting
/// one for the exact problem that helper's own doc comment says sharing one
/// copy was meant to stop.
fn run_jq_full(args: &[&str], input: Option<&str>) -> Result<(String, String, i32)> {
    let (output, exit_code) = spawn_jq(args, input.map(str::as_bytes))?;
    let stdout = String::from_utf8(output.stdout)?;
    let stderr = String::from_utf8(output.stderr)?;
    Ok((stdout, stderr, exit_code))
}

/// Spawns `succinctly jq <args>`, writing `stdin_input` when `Some` -- the
/// one place every direct-binary jq invocation in this file builds its
/// `Command`, so a future change to how the subcommand is invoked (a new
/// common flag, a different `succinctly_bin()` argv shape) is a single
/// edit rather than the six near-identical copies code review found here
/// before this consolidation (#1884).
fn spawn_jq(args: &[&str], stdin_input: Option<&[u8]>) -> Result<(std::process::Output, i32)> {
    spawn_with_signal_retry(
        || {
            let mut command = Command::new(succinctly_bin());
            command.arg("jq").args(args);
            command
        },
        stdin_input,
    )
}

/// Runs the binary with stdout and stderr pointed at the *same* file, so the
/// two streams' real interleaving survives (#1653).
///
/// `run_jq_full`'s separate pipes cannot express ordering at all: they record
/// what each stream contained, never which write happened first -- and
/// ordering is the entire property under test here. A temp file, rather than
/// one pipe shared by two `Stdio`s, because a `File` can simply be duplicated
/// into both slots.
///
/// Cannot route through `spawn_jq`/`spawn_with_signal_retry` (#1884) the way
/// every other helper here does: those hardcode piped stdout/stderr, which is
/// exactly the wiring this one has to replace. It reuses their primitives
/// (`succinctly_bin`, `signal_death_error`, `MAX_CARGO_RETRIES`) and repeats
/// their retry -- ENOENT while a sibling test rebuilds the binary, and a
/// signal-killed child (#1516/#1691) -- rather than reimplementing the retry
/// policy with different numbers.
fn run_jq_interleaved(args: &[&str], input: Option<&str>) -> Result<(String, i32)> {
    // #2016 (code review): `TempDir`, not a hand-rolled unique path plus a
    // bespoke `Drop`-guard -- `tempfile` is already a dependency, already
    // used this same way by sibling test files, and already provides
    // exactly this "unique scratch dir, deleted on drop" guarantee.
    let dir = tempfile::TempDir::new()?;
    let path = dir.path().join("combined.txt");

    for attempt in 0..MAX_CARGO_RETRIES {
        // Truncate per attempt: a retry must not read a previous attempt's
        // bytes back as if this run had produced them.
        std::fs::File::create(&path)?;
        let out_handle = std::fs::File::options().append(true).open(&path)?;
        let err_handle = out_handle.try_clone()?;
        let spawned = Command::new(succinctly_bin())
            .arg("jq")
            .args(args)
            .stdin(Stdio::piped())
            .stdout(Stdio::from(out_handle))
            .stderr(Stdio::from(err_handle))
            .spawn();
        let child = match spawned {
            Ok(child) => child,
            Err(e)
                if e.kind() == std::io::ErrorKind::NotFound && attempt + 1 < MAX_CARGO_RETRIES =>
            {
                std::thread::sleep(std::time::Duration::from_millis(100 * (attempt as u64 + 1)));
                continue;
            }
            Err(e) => return Err(e.into()),
        };
        // #2016 (code review): `write_stdin_then_wait` -- can't use
        // `spawn_with_signal_retry`'s own whole spawn+retry wrapper here
        // (it hardcodes piped stdout/stderr, which would break this
        // function's own same-file interleaving, #1653), but shares its
        // write/wait/reap sequencing rather than re-deriving a second copy.
        let output = write_stdin_then_wait(child, input.map(str::as_bytes))?;
        let combined = std::fs::read_to_string(&path)?;
        if let Some(code) = output.status.code() {
            return Ok((combined, code));
        }
        if attempt + 1 >= MAX_CARGO_RETRIES {
            return Err(signal_death_error(output.status, &combined));
        }
        std::thread::sleep(std::time::Duration::from_millis(100 * (attempt as u64 + 1)));
    }
    unreachable!()
}

/// `spawn_jq`'s counterpart for the environment-variable test cluster
/// (#1889 code review): the 8 tests covering `NO_COLOR`/`JQ_COLORS`/
/// `JQ_LIBRARY_PATH`/`HOME` each independently hand-rolled the same
/// `Command::new(succinctly_bin()); cmd.arg("jq").args(args).env(...)`
/// closure since `spawn_jq` itself has no way to set an environment
/// variable -- sharing one copy here instead of 8 near-identical ones is
/// the same fix `spawn_jq`'s own doc comment already describes for the
/// six-copies-of-one-`Command` problem (#1884).
fn spawn_jq_with_env(
    args: &[&str],
    env_key: &str,
    env_value: impl AsRef<std::ffi::OsStr>,
    stdin_input: Option<&[u8]>,
) -> Result<(std::process::Output, i32)> {
    spawn_with_signal_retry(
        || {
            let mut command = Command::new(succinctly_bin());
            command
                .arg("jq")
                .args(args)
                .env(env_key, env_value.as_ref());
            command
        },
        stdin_input,
    )
}

/// Helper to run jq with null input (-n)
fn run_jq_null(filter: &str, extra_args: &[&str]) -> Result<(String, i32)> {
    let mut args: Vec<&str> = vec!["-n"];
    args.extend_from_slice(extra_args);
    args.push(filter);
    let (stdout, _stderr, exit_code) = run_jq_full(&args, None)?;
    Ok((stdout, exit_code))
}

// =============================================================================
// Basic Functionality Tests
// =============================================================================

#[test]
fn test_identity_filter() -> Result<()> {
    let (output, code) = run_jq_stdin(".", r#"{"a":1,"b":2}"#, &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(output.trim(), r#"{"a":1,"b":2}"#);
    Ok(())
}

#[test]
fn test_field_access() -> Result<()> {
    let (output, code) = run_jq_stdin(".name", r#"{"name":"Alice","age":30}"#, &[])?;
    assert_eq!(code, 0);
    assert_eq!(output.trim(), r#""Alice""#);
    Ok(())
}

#[test]
fn test_nested_field_access() -> Result<()> {
    let (output, code) = run_jq_stdin(".user.name", r#"{"user":{"name":"Bob"}}"#, &[])?;
    assert_eq!(code, 0);
    assert_eq!(output.trim(), r#""Bob""#);
    Ok(())
}

#[test]
fn test_array_index() -> Result<()> {
    let (output, code) = run_jq_stdin(".[1]", r"[10,20,30]", &[])?;
    assert_eq!(code, 0);
    assert_eq!(output.trim(), "20");
    Ok(())
}

#[test]
fn test_array_iteration() -> Result<()> {
    let (output, code) = run_jq_stdin(".[]", r"[1,2,3]", &[])?;
    assert_eq!(code, 0);
    assert_eq!(output, "1\n2\n3\n");
    Ok(())
}

// Array slicing yields a single sub-array, not a stream of elements (issue #154).

#[test]
fn test_array_slice_returns_single_array() -> Result<()> {
    let (output, code) = run_jq_stdin(".[2:4]", r"[0,1,2,3,4]", &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(output, "[2,3]\n");
    Ok(())
}

#[test]
fn test_array_slice_construction_nests() -> Result<()> {
    let (output, code) = run_jq_stdin("[.[2:4]]", r"[0,1,2,3,4]", &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(output, "[[2,3]]\n");
    Ok(())
}

#[test]
fn test_array_slice_then_iterate_streams() -> Result<()> {
    let (output, code) = run_jq_stdin(".[2:4][]", r"[0,1,2,3,4]", &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(output, "2\n3\n");
    Ok(())
}

#[test]
fn test_array_slice_piped_to_length() -> Result<()> {
    let (output, code) = run_jq_stdin(".[2:4] | length", r"[0,1,2,3,4]", &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(output, "2\n");
    Ok(())
}

#[test]
fn test_array_slice_out_of_range_is_empty_array() -> Result<()> {
    let (output, code) = run_jq_stdin(".[5:10]", r"[0,1,2,3,4]", &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(output, "[]\n");
    Ok(())
}

#[test]
fn test_full_array_slice_returns_whole_array() -> Result<()> {
    let (output, code) = run_jq_stdin(".[:]", r"[0,1,2,3,4]", &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(output, "[0,1,2,3,4]\n");
    Ok(())
}

#[test]
fn test_string_slice_unchanged() -> Result<()> {
    let (output, code) = run_jq_stdin(".[1:3]", r#""hello""#, &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(output, "\"el\"\n");
    Ok(())
}

#[test]
fn test_arithmetic() -> Result<()> {
    let (output, code) = run_jq_null("1 + 2 * 3", &[])?;
    assert_eq!(code, 0);
    assert_eq!(output.trim(), "7");
    Ok(())
}

#[test]
fn test_unary_minus() -> Result<()> {
    // Negate input value - use -- to prevent option parsing of -. filter
    let (output, code) = spawn_jq(&["--", "-."], Some(b"5"))?;
    let stdout = String::from_utf8(output.stdout)?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "-5");
    Ok(())
}

#[test]
fn test_unary_minus_expression() -> Result<()> {
    // Negate a complex expression
    let (output, code) = spawn_jq(&["--", "-(.a + .b)"], Some(br#"{"a":3,"b":2}"#))?;
    let stdout = String::from_utf8(output.stdout)?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "-5");
    Ok(())
}

#[test]
fn test_double_negation() -> Result<()> {
    // Double negation should return original value
    let (output, code) = spawn_jq(&["--", "--."], Some(b"5"))?;
    let stdout = String::from_utf8(output.stdout)?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "5");
    Ok(())
}

