// =============================================================================
// Stream operators: `//`, `and`, `or` (#160)
// =============================================================================

#[test]
fn test_stream_operators_emit_every_output() -> Result<()> {
    // Exact stdout including trailing newlines — the output *count* is the
    // point, so `.trim()` would hide the bug (#160).
    for (filter, expected) in [
        (r#"(false,1,null,2) // "backup""#, "1\n2\n"),
        ("false // (null,7)", "null\n7\n"),
        ("(true,false) and (true,false)", "true\nfalse\nfalse\n"),
        ("(true,false) or (true,false)", "true\ntrue\nfalse\n"),
    ] {
        let (stdout, code) = run_jq_stdin(filter, "null", &["-c"])?;
        assert_eq!(code, 0, "`{filter}` should succeed");
        assert_eq!(stdout, expected, "wrong output stream for `{filter}`");
    }
    Ok(())
}

#[test]
fn test_stream_operator_truthy_retain_collapses_borrowed_many_to_every_arity_1038() -> Result<()> {
    // `//`'s truthy-retain over a *borrowed* multi-output stream (`.[]`, not
    // a constructed/owned one) collapses through `borrowed_vec_to_result`
    // (#1038) -- pin all three arities its match covers: zero truthy values
    // left, exactly one, and more than one.
    for (filter, input, expected) in [
        (r#".[] // "backup""#, "[false,null]", "\"backup\"\n"),
        (r#".[] // "backup""#, "[false,1,null]", "1\n"),
        (r#".[] // "backup""#, "[false,1,null,2]", "1\n2\n"),
    ] {
        let (stdout, code) = run_jq_stdin(filter, input, &["-c"])?;
        assert_eq!(code, 0, "`{filter}` on {input} should succeed");
        assert_eq!(stdout, expected, "wrong output for `{filter}` on {input}");
    }
    Ok(())
}

#[test]
fn test_limit_collapses_borrowed_many_to_every_arity_1038() -> Result<()> {
    // `limit`'s `Many` arm collapses its taken prefix through
    // `borrowed_vec_to_result` (#1038) -- pin both reachable arities (one
    // taken, more than one) from a *borrowed* multi-output stream (`.[]`).
    // `limit(0; ...)` takes its own dedicated early return before `expr` is
    // even evaluated, so it never reaches the `Many` arm at all; included
    // anyway as ordinary black-box coverage of `limit`'s zero-output case.
    for (filter, expected) in [
        ("[limit(0; .[])]", "[]\n"),
        ("[limit(1; .[])]", "[1]\n"),
        ("[limit(2; .[])]", "[1,2]\n"),
    ] {
        let (stdout, code) = run_jq_stdin(filter, "[1,2,3]", &["-c"])?;
        assert_eq!(code, 0, "`{filter}` should succeed");
        assert_eq!(stdout, expected, "wrong output for `{filter}`");
    }
    Ok(())
}

#[test]
fn test_boolean_with_empty_operand_is_silent() -> Result<()> {
    // An empty operand used to reach `result_to_owned`, which reported it as
    // `Error("no value")` and printed a diagnostic. jq emits nothing at all,
    // quietly. The goldens compare stdout only, so stderr is asserted here.
    let (stdout, stderr, code) = run_jq_stdin_streams("empty and true", "null", &["-c"])?;
    assert_eq!(stdout, "", "expected no output");
    assert_eq!(stderr, "", "expected no diagnostic on stderr");
    assert_eq!(code, 0, "expected success");
    Ok(())
}

// =============================================================================
// JSON Sequence Format (RFC 7464) Tests
// =============================================================================

/// Helper to run jq command with binary input (for testing --seq with RS characters)
fn run_jq_binary_stdin(filter: &str, input: &[u8], extra_args: &[&str]) -> Result<(Vec<u8>, i32)> {
    let mut args: Vec<&str> = extra_args.to_vec();
    args.push(filter);
    let (output, exit_code) = spawn_jq(&args, Some(input))?;
    Ok((output.stdout, exit_code))
}

#[test]
fn test_seq_output_format() -> Result<()> {
    // --seq should prepend RS (0x1E) before each output value. Input must
    // itself be RS-framed for --seq to read it at all -- RFC 7464 requires
    // every record to start with one, and real jq's own reader treats
    // unprefixed input as "abandoned text" and reads nothing, even when
    // it's otherwise well-formed JSON and --slurp isn't in play (#1542
    // found and fixed the same rule for --seq --slurp's own trailing-record
    // case; oracle-verified live against jq 1.7.1 that it holds here too:
    // `printf '{"a":1}' | jq --seq -c '.'` prints nothing at all).
    let (output, code) = run_jq_binary_stdin(".", b"\x1e{\"a\":1}\n", &["--seq", "-c"])?;
    assert_eq!(code, 0);

    // Output should start with RS (0x1E)
    assert!(
        output.starts_with(&[0x1E]),
        "Output should start with RS (0x1E), got: {:?}",
        &output[..output.len().min(10)]
    );

    // Rest should be the JSON value
    let rest = String::from_utf8(output[1..].to_vec())?;
    assert_eq!(rest.trim(), r#"{"a":1}"#);
    Ok(())
}

/// #1913: real jq's `--seq` writes the RS separator before each *JSON*
/// output, but not before a genuinely raw (`-r`/`-j`) string output --
/// confirmed live against jq 1.7.1. `succinctly jq` used to write it
/// unconditionally, corrupting every `--seq -r`/`--seq -j` record with a
/// leading `\x1e` byte jq does not emit.
#[test]
fn test_seq_omits_rs_before_raw_output_1913() -> Result<()> {
    // `-r`: no leading RS at all.
    let (output, code) = run_jq_binary_stdin(".", b"\x1e\"a\"\n\x1e\"b\"\n", &["--seq", "-r"])?;
    assert_eq!(code, 0);
    assert_eq!(output, b"a\nb\n");

    // `-j`: same, and no trailing newline either.
    let (output, code) = run_jq_binary_stdin(".", b"\x1e\"a\"\n\x1e\"b\"\n", &["--seq", "-j"])?;
    assert_eq!(code, 0);
    assert_eq!(output, b"ab");

    // Control: plain `--seq` (no `-r`/`-j`) still gets the separator.
    let (output, code) = run_jq_binary_stdin(".", b"\x1e\"a\"\n", &["--seq", "-c"])?;
    assert_eq!(code, 0);
    assert_eq!(output, b"\x1e\"a\"\n");

    // `-r` falling back to JSON output for a non-string value still gets
    // the separator -- real jq's own behavior, confirmed live.
    let (output, code) = run_jq_binary_stdin(".", b"\x1e42\n", &["--seq", "-r"])?;
    assert_eq!(code, 0);
    assert_eq!(output, b"\x1e42\n");

    // The `-n`/`inputs` materializing path (a separate writer function)
    // gets the same fix.
    let (output, code) =
        run_jq_binary_stdin("inputs", b"\x1e\"a\"\n\x1e\"b\"\n", &["--seq", "-n", "-r"])?;
    assert_eq!(code, 0);
    assert_eq!(output, b"a\nb\n");

    Ok(())
}

#[test]
fn test_seq_input_parsing() -> Result<()> {
    // --seq should parse RS-separated input values
    let mut input = Vec::new();
    input.push(0x1E); // RS
    input.extend_from_slice(br#"{"x":1}"#);
    input.push(b'\n');
    input.push(0x1E); // RS
    input.extend_from_slice(br#"{"x":2}"#);
    input.push(b'\n');

    let (output, code) = run_jq_binary_stdin(".x", &input, &["--seq"])?;
    assert_eq!(code, 0);

    // Should have two RS-prefixed outputs
    let output_str = String::from_utf8(output)?;
    let lines: Vec<_> = output_str.lines().collect();

    // Each line should start with RS followed by the value
    assert!(lines.len() >= 2, "Should have at least 2 output lines");
    Ok(())
}

#[test]
fn test_seq_ignores_parse_errors() -> Result<()> {
    // RFC 7464 recommends silently ignoring parse errors
    let mut input = Vec::new();
    input.push(0x1E);
    input.extend_from_slice(br#"{"valid":1}"#);
    input.push(b'\n');
    input.push(0x1E);
    input.extend_from_slice(b"not valid json");
    input.push(b'\n');
    input.push(0x1E);
    input.extend_from_slice(br#"{"valid":2}"#);
    input.push(b'\n');

    let (output, code) = run_jq_binary_stdin(".valid", &input, &["--seq"])?;
    assert_eq!(code, 0);

    // Should only see outputs from valid JSON (1 and 2), not the invalid segment
    let output_str = String::from_utf8(output)?;
    assert!(
        output_str.contains('1'),
        "Should have output from first valid value"
    );
    assert!(
        output_str.contains('2'),
        "Should have output from second valid value"
    );
    Ok(())
}

/// #1525: real jq warns on stderr ("ignoring parse error: Unfinished
/// abandoned text at EOF at line L, column C") when `--seq` input has no
/// RS byte anywhere at all -- RFC 7464 requires every record to start
/// with one, so jq's reader never resyncs onto unprefixed content and
/// reports the abandonment unconditionally at EOF, regardless of what the
/// content actually is (even fully valid JSON, per the last case below).
/// Every expected value was live-verified against the pinned jq 1.7.1
/// binary.
#[test]
fn test_seq_no_rs_byte_warns_1525() -> Result<()> {
    for (input, expected_line, expected_column) in [
        ("1 2", 1, 3),
        ("true false", 1, 10),
        ("null", 1, 4),
        ("ab\ncd", 2, 2),
        ("ab\ncd\n", 3, 0),
        ("", 1, 0),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["--seq", "-c", "."], Some(input))
            .unwrap_or_else(|e| panic!("input {input:?}: failed to run: {e}"));
        assert_eq!(code, 0, "input {input:?}: stdout: {stdout}");
        assert_eq!(
            stderr.trim(),
            format!(
                "jq: ignoring parse error: Unfinished abandoned text at EOF at line {expected_line}, column {expected_column}"
            ),
            "input {input:?}"
        );
        assert_eq!(stdout, "", "input {input:?}: no value should be output");
    }
    Ok(())
}

/// #1525/#1723: a malformed record that *does* start with an RS byte gets
/// jq's mid-stream templates, never the "no RS byte" one above (#1525
/// deliberately left this silent; #1723 implemented it).
///
/// Three warnings for one record, not one, and that is the point: jq
/// resets to the top level and resumes at the very next byte rather than
/// skipping to the next RS, so `not`, `valid` and `json` are each rejected
/// in turn. The `(need RS to resync)` the message promises never happens
/// -- see [`super`]'s `jq_seq_reader` for why. Captured from
/// `/usr/bin/jq` 1.7.1.
#[test]
fn test_seq_malformed_record_with_rs_byte_warns_1723() -> Result<()> {
    let (stdout, stderr, code) =
        run_jq_full(&["--seq", "-c", "."], Some("\u{1e}not valid json\n")).unwrap();
    assert_eq!(code, 0);
    assert_eq!(
        stderr,
        "jq: ignoring parse error: Invalid numeric literal at line 1, column 5 (need RS to resync)\n\
         jq: ignoring parse error: Invalid numeric literal at line 1, column 11 (need RS to resync)\n\
         jq: ignoring parse error: Invalid numeric literal at line 2, column 0 (need RS to resync)\n"
    );
    assert_eq!(stdout, "");
    Ok(())
}

/// #1723: the mid-stream templates end to end, through the CLI rather
/// than the reader in isolation -- these are the shapes the issue was
/// filed for. Captured from `/usr/bin/jq` 1.7.1.
#[test]
fn test_seq_midstream_warning_templates_1723() -> Result<()> {
    let cases: &[(&str, &str)] = &[
        (
            "\u{1e}\"unterminated\n",
            "Unfinished string at EOF at line 2, column 0",
        ),
        (
            "\u{1e}[1,2\n",
            "Unfinished JSON term at EOF at line 2, column 0",
        ),
        (
            "\u{1e}xyz\n",
            "Invalid numeric literal at line 2, column 0 (need RS to resync)",
        ),
        (
            "\u{1e}{invalid\n",
            "Invalid numeric literal at line 2, column 0 (need RS to resync)",
        ),
        ("\u{1e}tru", "Invalid literal at EOF at line 1, column 4"),
        (
            "\u{1e}1.",
            "Potentially truncated top-level numeric value at EOF at line 1, column 3",
        ),
        (
            "\u{1e}[1,]",
            "Expected another array element at line 1, column 5 (need RS to resync)",
        ),
        (
            "\u{1e}}",
            "Unmatched '}' at line 1, column 2 (need RS to resync)",
        ),
        (
            "\u{1e}\"unterminated\u{1e}\"ok\"\n",
            "Truncated value at line 1, column 15",
        ),
    ];
    for (input, expected) in cases {
        let (_stdout, stderr, code) = run_jq_full(&["--seq", "-c", "."], Some(input)).unwrap();
        assert_eq!(code, 0, "input {input:?} stderr: {stderr}");
        assert_eq!(
            stderr,
            format!("jq: ignoring parse error: {expected}\n"),
            "input {input:?}"
        );
    }
    Ok(())
}

/// #1723: `--slurp` reaches the same warning site, and a malformed record
/// between two good ones neither stops the slurp nor loses them.
#[test]
fn test_seq_warns_under_slurp_1723() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(
        &["--seq", "-s", "-c", "."],
        Some("\u{1e}1\n\u{1e}}\n\u{1e}2\n"),
    )
    .unwrap();
    assert_eq!(code, 0, "stderr: {stderr}");
    assert_eq!(
        stderr,
        "jq: ignoring parse error: Unmatched '}' at line 2, column 2 (need RS to resync)\n"
    );
    assert_eq!(stdout.trim(), "\u{1e}[1,2]");
    Ok(())
}

/// #1723: the modes #1525 deliberately kept silent stay silent -- `-R`
/// takes over raw-text handling, DSV content holds no RFC 7464 records,
/// and `-n` turns this into a fatal error in real jq that succinctly does
/// not implement (see `test_seq_null_input_with_inputs_does_not_warn_1525`).
#[test]
fn test_seq_warning_guards_still_suppress_1723() -> Result<()> {
    for args in [
        &["-R", "--seq", "-c", "."][..],
        &["-n", "--seq", "-c", "[inputs]"][..],
    ] {
        let (_stdout, stderr, code) = run_jq_full(args, Some("\u{1e}not valid json\n")).unwrap();
        assert_eq!(code, 0, "args {args:?} stderr: {stderr}");
        assert_eq!(stderr, "", "args {args:?}");
    }
    Ok(())
}

/// #1723: columns count raw bytes, so a byte that is not valid UTF-8 --
/// substituted with U+FFFD before the value path ever sees it -- still
/// advances the column by exactly one.
#[test]
fn test_seq_warning_columns_count_raw_bytes_1723() -> Result<()> {
    // A non-UTF-8 byte is an ordinary token character to jq's scanner, so
    // `]` ends a token that fails to parse rather than being unmatched --
    // the column is the point of the comparison either way.
    for (input, expected) in [
        (
            &b"\x1e\xff]"[..],
            "Invalid numeric literal at line 1, column 3 (need RS to resync)",
        ),
        (
            &b"\x1e\xc3\xa9]"[..],
            "Invalid numeric literal at line 1, column 4 (need RS to resync)",
        ),
        (
            &b"\x1e]"[..],
            "Unmatched ']' at line 1, column 2 (need RS to resync)",
        ),
    ] {
        let (output, code) = spawn_jq(&["--seq", "-c", "."], Some(input))?;
        assert_eq!(code, 0);
        assert_eq!(
            String::from_utf8_lossy(&output.stderr),
            format!("jq: ignoring parse error: {expected}\n"),
            "input {input:?}"
        );
    }
    Ok(())
}

/// #1723: a malformed BOM (a prefix that starts one and then contradicts
/// it) costs jq a `parser_reset` that leaves it reading rather than
/// waiting for an RS -- so even a stream with *no* RS byte anywhere gets
/// one of this issue's mid-stream templates through `get_inputs`'s
/// `bom_malformed` filter, never #1525's "no RS byte" one. Exercised only
/// by `scripts/jq-seq-oracle-sweep.py`'s `HAND` corpus until now; pinned
/// here so a regression in that filter fails CI rather than only a manual
/// sweep. Captured from `/usr/bin/jq` 1.7.1.
#[test]
fn test_seq_malformed_bom_with_no_rs_byte_warns_1723() -> Result<()> {
    for input in [&b"\xef\xbb1 2"[..], b"\xef1 2"] {
        let (output, code) = spawn_jq(&["--seq", "-c", "."], Some(input))?;
        assert_eq!(code, 0);
        assert_eq!(
            String::from_utf8_lossy(&output.stderr),
            "jq: ignoring parse error: Potentially truncated top-level numeric value at EOF at line 1, column 3\n",
            "input {input:?}"
        );
        assert_eq!(output.stdout, b"", "input {input:?}");
    }
    Ok(())
}

/// #1525: an RS-less file combined with an RS-containing one triggers no
/// warning at all when the RS-less file is *empty* -- real jq treats the
/// whole `--seq` input as one continuous stream, and the RS-containing
/// file satisfies the "every record starts with an RS byte" requirement
/// for the stream as a whole. (A *non-empty* RS-less file paired with an
/// RS-containing one still warns on real jq, with one of the other
/// message templates #1723 tracks -- not this one; not exercised here.)
///
/// Spawns via `spawn_jq` (not a bare `Command::new(...).output()`) for its
/// retry protection against a transient `ENOENT` or a signal-killed child
/// under concurrent load (#550, #1884).
#[test]
fn test_seq_no_rs_warning_suppressed_by_another_source_with_rs_1525() -> Result<()> {
    let mut valid_file = NamedTempFile::new()?;
    writeln!(valid_file, "\u{1e}1")?;
    let empty_file = NamedTempFile::new()?;

    let valid_path = valid_file.path().to_str().unwrap();
    let empty_path = empty_file.path().to_str().unwrap();
    let (output, _) = spawn_jq(&["--seq", "-c", ".", valid_path, empty_path], None)?;

    assert!(output.status.success());
    assert_eq!(String::from_utf8(output.stderr)?, "");
    // `--seq` RS-prefixes output too (RFC 7464), same as real jq.
    assert_eq!(String::from_utf8(output.stdout)?.trim(), "\u{1e}1");
    Ok(())
}

/// #1525: two RS-less files report a line/column computed from their
/// *concatenation*, not either file's own content alone -- oracle-verified
/// against the pinned jq 1.7.1 binary. Spawns via `spawn_jq` for its retry
/// protection, same reason as the test above.
#[test]
fn test_seq_no_rs_warning_across_multiple_files_1525() -> Result<()> {
    let mut file_a = NamedTempFile::new()?;
    write!(file_a, "ab")?;
    let mut file_b = NamedTempFile::new()?;
    write!(file_b, "cd")?;

    let path_a = file_a.path().to_str().unwrap();
    let path_b = file_b.path().to_str().unwrap();
    let (output, _) = spawn_jq(&["--seq", "-c", ".", path_a, path_b], None)?;

    assert!(output.status.success());
    assert_eq!(
        String::from_utf8(output.stderr)?.trim(),
        "jq: ignoring parse error: Unfinished abandoned text at EOF at line 1, column 4"
    );
    Ok(())
}

/// #1525: the reported column counts *raw* bytes, before invalid UTF-8 is
/// lossily substituted (#1617) -- each substituted byte becomes a 3-byte
/// U+FFFD, which would overcount the column by 2 per substitution if the
/// count ran on the substituted string instead. Oracle-verified.
#[test]
fn test_seq_no_rs_warning_column_counts_raw_bytes_not_substituted_1525() -> Result<()> {
    let mut input = Vec::new();
    input.extend_from_slice(b"ab");
    input.push(0xFF); // invalid UTF-8 lead byte -> substituted to 3-byte U+FFFD
    input.extend_from_slice(b"cd");

    let (output, _) = spawn_jq(&["--seq", "-c", "."], Some(&input))?;

    assert!(output.status.success());
    assert_eq!(
        String::from_utf8(output.stderr)?.trim(),
        "jq: ignoring parse error: Unfinished abandoned text at EOF at line 1, column 5"
    );
    Ok(())
}

/// #1525: `--seq --input-dsv` combined must never fire the RS-byte
/// warning -- DSV is a succinctly-only extension with no RFC 7464 records
/// at all. The non-slurp streaming DSV path bypasses `get_inputs`
/// entirely and was never at risk; `-s` routes through `get_inputs`
/// instead, which is what the fix's `args.input_dsv.is_none()` guard
/// covers.
#[test]
fn test_seq_dsv_combo_does_not_warn_1525() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(
        &["--seq", "--input-dsv", ",", "-s", "-c", "."],
        Some("a,b\n1,2\n"),
    )
    .unwrap();
    assert_eq!(code, 0, "stderr: {stderr}");
    assert_eq!(stderr, "");
    // `--seq` RS-prefixes output too (RFC 7464), same as real jq.
    assert_eq!(stdout.trim(), "\u{1e}[[\"a\",\"b\"],[\"1\",\"2\"]]");
    Ok(())
}

/// #1525: `-n --seq` combined with a filter that forces a real read
/// (`inputs`) must not print the "ignoring parse error" warning -- real
/// jq treats this same no-RS-byte condition as a *fatal* error there
/// (exit 5), not a warning, and succinctly doesn't implement that fatal
/// path yet (a separate, larger gap than this issue's own scope).
/// Printing the warning's exact wording in this mode would misrepresent
/// succinctly's still-unfixed non-fatal behavior as though it matched jq.
#[test]
fn test_seq_null_input_with_inputs_does_not_warn_1525() -> Result<()> {
    let (stdout, stderr, code) =
        run_jq_full(&["-n", "--seq", "-c", "[inputs]"], Some("1 2")).unwrap();
    assert_eq!(code, 0, "stderr: {stderr}");
    assert_eq!(stderr, "");
    // `--seq` RS-prefixes output too (RFC 7464), same as real jq.
    assert_eq!(stdout.trim(), "\u{1e}[]");
    Ok(())
}

/// #1525: a leading UTF-8 BOM on the very first source is stripped before
/// line/column counting, matching real jq. Oracle-verified.
#[test]
fn test_seq_no_rs_warning_strips_leading_bom_1525() -> Result<()> {
    let mut input = Vec::new();
    input.extend_from_slice(b"\xEF\xBB\xBF");
    input.extend_from_slice(b"1 2");

    let (output, _) = spawn_jq(&["--seq", "-c", "."], Some(&input))?;

    assert!(output.status.success());
    assert_eq!(
        String::from_utf8(output.stderr)?.trim(),
        "jq: ignoring parse error: Unfinished abandoned text at EOF at line 1, column 3"
    );
    Ok(())
}

/// #1525: `-R --seq` combined lets `-R` take over raw-text handling
/// entirely (matching this codebase's existing `slurp_eof_line` priority
/// for the same combination) -- no RS-byte warning, since RFC 7464
/// record-splitting never applies in raw-input mode.
#[test]
fn test_seq_raw_input_combo_does_not_warn_1525() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["-R", "--seq", "-c", "."], Some("xyz")).unwrap();
    assert_eq!(code, 0);
    assert_eq!(stderr, "");
    // `--seq` RS-prefixes output too (RFC 7464), same as real jq.
    assert_eq!(stdout.trim(), "\u{1e}\"xyz\"");
    Ok(())
}

/// #1213: `--seq`'s error-location reporting stays correct once its
/// per-value line lookup is incremental (`LineCounter`) instead of a
/// from-scratch rescan per value -- the erroring record here is deep enough
/// into the stream (record 50 of 100) that an off-by-one in the incremental
/// bookkeeping would show up as a wrong line number, not just a wrong
/// answer.
#[test]
fn test_seq_error_location_correct_with_many_preceding_records_1213() -> Result<()> {
    let mut input = String::new();
    for i in 0..100 {
        input.push('\u{1e}');
        input.push_str(&format!("{{\"n\":{i}}}\n"));
    }
    let (_, stderr, code) = run_jq_full(
        &["--seq", r#"if .n==50 then error("boom") else . end"#],
        Some(&input),
    )?;
    assert_eq!(code, 5, "stderr: {stderr}");
    // Record 50 (0-indexed) is the 51st RS-delimited record, ending on the
    // 51st line of the input.
    assert!(stderr.contains("(at <stdin>:51): boom"), "stderr: {stderr}");
    Ok(())
}

#[test]
fn test_seq_multiple_outputs() -> Result<()> {
    // Each output from iterator should get RS prefix. Input must be
    // RS-framed for --seq to read it at all -- see test_seq_output_format's
    // comment for why.
    let (output, code) = run_jq_binary_stdin(".[]", b"\x1e[1,2,3]\n", &["--seq"])?;
    assert_eq!(code, 0);

    // Count RS characters - should be 3 (one per output)
    let rs_count = output.iter().filter(|&&b| b == 0x1E).count();
    assert_eq!(rs_count, 3, "Should have 3 RS characters for 3 outputs");
    Ok(())
}

#[test]
fn test_seq_with_slurp() -> Result<()> {
    // --seq with -s should slurp all seq inputs into an array
    let mut input = Vec::new();
    input.push(0x1E);
    input.extend_from_slice(b"1");
    input.push(b'\n');
    input.push(0x1E);
    input.extend_from_slice(b"2");
    input.push(b'\n');
    input.push(0x1E);
    input.extend_from_slice(b"3");
    input.push(b'\n');

    let (output, code) = run_jq_binary_stdin("add", &input, &["--seq", "-s"])?;
    assert_eq!(code, 0);

    // Output should be RS + "6" (1+2+3)
    assert!(output.starts_with(&[0x1E]), "Output should start with RS");
    let rest = String::from_utf8(output[1..].to_vec())?;
    assert_eq!(rest.trim(), "6");
    Ok(())
}

