    assert_eq!(out.trim(), "true");

    let (out, err, code) = run_jq_full(
        &[
            "-c",
            r#"label $out | (endswith(("c", break $out)), "after")"#,
        ],
        Some(r#""abcabc""#),
    )?;
    assert_eq!(code, 0, "err={err}");
    assert_eq!(out.trim(), "true");

    let (out, err, code) = run_jq_full(
        &["-c", r#"label $out | (split((",", break $out)), "after")"#],
        Some(r#""abcabc""#),
    )?;
    assert_eq!(code, 0, "err={err}");
    assert_eq!(out.trim(), r#"["abcabc"]"#);
    Ok(())
