// `builtin_envvar`'s own fix (below) has no CLI-level test: `Builtin::EnvVar`
// has no parser construction site anywhere in this codebase (confirmed by
// that function's own pre-existing Halt/Break regression tests in
// src/jq/eval.rs) -- `env.VAR`/`$ENV.VAR`/`$ENV["VAR"]` all resolve through
// ordinary field/index access on a materialized object instead, never
// through this function. Its #1164 fix is covered by a direct unit test in
// src/jq/eval.rs instead, mirroring those same pre-existing tests' own
// "exercise it directly, since the CLI can't reach it" convention.

/// Control: `error(msg)`'s own "success" path already collapses into
/// producing an error, matching what the trailing break would have done
/// anyway -- deliberately left unfixed by #1164 (verified live: real jq's
/// `try error(("a", break $out)) catch (.)` still prints `"after"` too, the
/// break is never re-observed once the error is caught, so there is no
/// separate escape to propagate here). Confirms this fix didn't
/// accidentally change `error`'s own behavior.
#[test]
fn test_error_message_arg_break_semantics_unaffected_by_1164() -> Result<()> {
    let (_out, err, code) =
        run_jq_full(&["-cn", r#"label $out | error(("a", break $out))"#], None)?;
    assert_ne!(code, 0);
    assert!(err.contains('a'), "err={err}");
    Ok(())
}

/// #2727: `error(...)`'s message sub-expression used to be cloned rather
/// than recursed into by all three tree rewriters (`substitute_func_param_impl`,
/// `substitute_var_impl`, `install_def_calls`), so a `def` parameter, a bound
/// variable, or a recursive call referenced inside it was never substituted
/// -- surfacing as a confusing "undefined function"/wrong-message error
/// instead of the program's own. All four shapes below are live jq 1.7.1
/// captures.
#[test]
fn test_error_message_substitution_reaches_bound_names_2727() -> Result<()> {
    // A `def` parameter referenced inside `error(...)`'s message.
    let (out, _err, code) =
        run_jq_full(&["-cn", r#"def f(a): try error(a) catch .; f("x")"#], None)?;
    assert_eq!(code, 0, "out={out:?}");
    assert_eq!(out, "\"x\"\n", "out={out:?}");

    // An `as`-bound variable referenced inside `error(...)`'s message --
    // not parameter-specific, per the issue's own "why this is separate"
    // note.
    let (out, _err, code) = run_jq_full(&["-cn", r#""x" as $a | try error($a) catch ."#], None)?;
    assert_eq!(code, 0, "out={out:?}");
    assert_eq!(out, "\"x\"\n", "out={out:?}");

    // A `$`-style def parameter referenced inside `error(...)`'s message --
    // the other substitution namespace `substitute_func_param_impl` handles.
    let (out, _err, code) = run_jq_full(
        &["-cn", r#"def f($a): try error($a) catch .; f("x")"#],
        None,
    )?;
    assert_eq!(code, 0, "out={out:?}");
    assert_eq!(out, "\"x\"\n", "out={out:?}");

    // A recursive def call inside error(...)'s own message string --
    // exercises `install_def_calls`'s copy of the same arm, which binds
    // `Expr::FuncCall` to `Expr::DefCall` before evaluation ever runs.
    let (out, _err, code) = run_jq_full(
        &[
            "-cn",
            r#"def f(n): if n == 0 then "done" else error("depth \(f(n-1))") end; try f(2) catch ."#,
        ],
        None,
    )?;
    assert_eq!(code, 0, "out={out:?}");
    assert_eq!(out, "\"depth done\"\n", "out={out:?}");

    Ok(())
}

/// #2739: a label name and a variable name live in different namespaces in
/// jq -- `label $x | ...` binds a break target, not a variable -- but
/// `substitute_var_impl`'s `Expr::Label` arm treated a matching label as
/// shadowing the variable, blocking substitution from reaching an in-scope
/// `$x` read inside the label's body. Covers the bare case, a nested
/// same-named label, an unrelated rebinding inside the label body (already
/// correct, unaffected by this fix), `break` still escaping to the right
/// label afterward, and the `$`-style def-parameter sibling case
/// (`substitute_func_param_impl` has no such arm and stays correct). All
/// rows are live jq 1.7.1 captures.
#[test]
fn test_label_does_not_shadow_same_named_variable_2739() -> Result<()> {
    for (filter, expected) in [
        ("1 as $x | label $x | $x", "1\n"),
        ("1 as $x | label $x | (label $x | $x)", "1\n"),
        ("label $x | (2 as $x | $x)", "2\n"),
        ("1 as $x | label $x | (2, break $x, 3)", "2\n"),
        (r"def f: label $x | (1, break $x, 2); [f]", "[1]\n"),
        ("def f($x): label $x | $x; f(1)", "1\n"),
    ] {
        let (out, err, code) = run_jq_full(&["-cn", filter], None)?;
        assert_eq!(code, 0, "`{filter}` -- out={out:?} err={err:?}");
        assert_eq!(out, expected, "`{filter}`");
    }
    Ok(())
}

/// #2728: a leading underscore is a valid identifier-start character
/// throughout jq (`def _walk: ...` is a common real-jq library convention),
/// but the bare-name/call dispatch gate in `parse_primary` only checked
/// `c.is_alphabetic()`, so a leading `_` never even reached `parse_ident`
/// (which already accepted it) -- surfacing as a raw "unexpected character
/// '_', expected expression" parse error instead. Covers the def name, a
/// bare parameter, a mid-name underscore, and a double-underscore prefix,
/// each cross-checked live against jq 1.7.1.
#[test]
fn test_leading_underscore_identifier_parses_2728() -> Result<()> {
    for (filter, expected) in [
        ("def _g: 42; _g", "42\n"),
        ("def f(_x): _x; f(1)", "1\n"),
        ("def __double: 7; __double", "7\n"),
        ("def foo_bar: 5; foo_bar", "5\n"),
    ] {
        let (out, err, code) = run_jq_full(&["-cn", filter], None)?;
        assert_eq!(code, 0, "`{filter}` -- out={out:?} err={err:?}");
        assert_eq!(out, expected, "`{filter}`");
    }
    Ok(())
}

/// #1164 coverage: the `optional` (`?`) arm of a wrong-typed argument is a
/// separate branch from the non-optional error arm every other test above
/// already exercises -- `?` suppresses the type mismatch to no output
/// (`QueryResult::None`) for each of these builtins' argument-evaluation
/// gate, independent of whether the trailing-control fix applies at all.
#[test]
fn test_argument_type_mismatch_optional_arms_produce_no_output_1164() -> Result<()> {
    for (expr, input) in [
        ("getpath(\"notarray\")?", r#"{"a":1}"#),
        ("gmtime | strftime(5)?", "0"),
        ("strptime(5)?", r#""x""#),
        ("tz(5)?", "0"),
    ] {
        let (out, err, code) = run_jq_full(&["-c", expr], Some(input))?;
        assert_eq!(code, 0, "expr={expr}: err={err}");
        assert_eq!(out, "", "expr={expr}: out={out:?}");
    }

    let (out, err, code) = run_jq_full(&["-cn", "load(5)?"], None)?;
    assert_eq!(code, 0, "err={err}");
    assert_eq!(out, "");
    Ok(())
}

/// #1801: `load()`'s YAML path (`yaml_value_to_owned_checked`) raises on an
/// undecodable string scalar instead of silently substituting `null`,
/// mirroring the `StandardJson` family's own `to_owned` (#1746/
/// #1755/#1620). Not suppressed by `?` -- a decode failure is never
/// catchable, same convention as every other `decode_failure`-constructed
/// error in this codebase.
#[test]
fn test_load_yaml_raises_on_undecodable_string_1801() -> Result<()> {
    let mut file = NamedTempFile::new()?;
    file.write_all(b"a: \"b\xe1\x41c\"\n")?;
    file.flush()?;
    let path = file.path().to_str().unwrap();

    let expr = format!("load({path:?})");
    let (out, err, code) = run_jq_full(&["-cn", &expr], None)?;
    assert_eq!(code, 5, "out={out:?}");
    assert!(err.contains("invalid UTF-8"), "err={err}");

    // Not suppressed by `?`.
    let expr_optional = format!("load({path:?})?");
    let (out, err, code) = run_jq_full(&["-cn", &expr_optional], None)?;
    assert_eq!(code, 5, "out={out:?} err={err}");
    assert!(err.contains("invalid UTF-8"), "err={err}");

    Ok(())
}

/// #1801 (review): a `Mapping` field whose *key* fails to decode keeps
/// both the key (under #1642's own display fallback, `""`) and its value,
/// rather than silently dropping the whole field -- matches
/// `yaml_to_owned_value`'s identical handling (`yq_runner.rs`) for this
/// same YamlCursor-native shape. An earlier draft of this fix left the
/// field dropped, incorrectly citing the `StandardJson` family's own
/// #1194 structural carve-out as precedent for what is actually #1642's
/// decode-failure-preservation territory.
#[test]
fn test_load_yaml_key_decode_failure_preserves_field_under_fallback_key_1801() -> Result<()> {
    let mut file = NamedTempFile::new()?;
    file.write_all(b"\"b\xe1\x41c\": 1\nokkey: 2\n")?;
    file.flush()?;
    let path = file.path().to_str().unwrap();

    let expr = format!("load({path:?})");
    let (out, err, code) = run_jq_full(&["-cn", &expr], None)?;
    assert_eq!(code, 0, "err={err}");
    assert_eq!(out.trim(), r#"{"":1,"okkey":2}"#);

    Ok(())
}

/// #1801 (review): two distinct undecodable keys both collapse to the same
/// `""` display fallback -- `DisplayKeyGuard` refuses to silently let the
/// second overwrite the first, raising `colliding_display_key_error`
/// instead (#1642), same as the `StandardJson` family's own collision
/// guard.
#[test]
fn test_load_yaml_two_undecodable_keys_collide_1801() -> Result<()> {
    let mut file = NamedTempFile::new()?;
    file.write_all(b"\"b\xe1\x41c\": 1\n\"d\xe1\x41e\": 2\n")?;
    file.flush()?;
    let path = file.path().to_str().unwrap();

    let expr = format!("load({path:?})");
    let (out, err, code) = run_jq_full(&["-cn", &expr], None)?;
    assert_eq!(code, 5, "out={out:?}");
    assert!(err.contains("is ambiguous"), "err={err}");

    Ok(())
}

/// #1813 review: the sibling test above only checks the raw, uncaught
/// route -- `yaml_value_to_owned_checked` (`load()`'s YAML path,
/// `eval.rs`) is a third call site for `EvalError::colliding_display_key`
/// besides the two already covered directly by #1813's own tests, and
/// nothing pinned that `try`/`catch` around `load()` itself still can't
/// suppress it.
#[test]
fn test_load_yaml_colliding_keys_not_caught_by_try_catch_1813() -> Result<()> {
    let mut file = NamedTempFile::new()?;
    file.write_all(b"\"b\xe1\x41c\": 1\n\"d\xe1\x41e\": 2\n")?;
    file.flush()?;
    let path = file.path().to_str().unwrap();

    let expr = format!("try load({path:?}) catch .");
    let (out, err, code) = run_jq_full(&["-cn", &expr], None)?;
    assert_ne!(
        code, 0,
        "try/catch must not catch a colliding-key error from load(), out: {out:?}"
    );
    assert!(err.contains("is ambiguous"), "err={err}");

    Ok(())
}

/// #1801: a multi-document YAML file raises as soon as any one document
/// contains an undecodable string, not just the last/first.
#[test]
fn test_load_yaml_multi_document_raises_on_any_bad_document_1801() -> Result<()> {
    let mut file = NamedTempFile::new()?;
    file.write_all(b"a: 1\n---\nb: \"c\xe1\x41d\"\n")?;
    file.flush()?;
    let path = file.path().to_str().unwrap();

    let expr = format!("load({path:?})");
    let (out, err, code) = run_jq_full(&["-cn", &expr], None)?;
    assert_eq!(code, 5, "out={out:?}");
    assert!(err.contains("invalid UTF-8"), "err={err}");

    Ok(())
}

/// #2747: jq defines `flatten` as `if $x < 0 then error("flatten depth must
/// not be negative") else _flatten($x) end`, where `$x < 0` is jq's own
/// total ordering, not a plain integer sign check -- so `null`/`false`/
/// `true`/a negative float/`nan` all raise the identical message a negative
/// integer does, since each ranks (or, for `nan`, orders) below every
/// number in that ordering. All values below are live jq 1.7.1 captures.
#[test]
fn test_flatten_negative_depth_message_matches_jq_across_ordering_2747() -> Result<()> {
    for depth in ["-1", "-1.5", "null", "false", "true", "nan"] {
        let filter = format!("flatten({depth})");
        let (stdout, stderr, code) = run_jq_full(&["-c", &filter], Some("[[1]]"))?;
        assert_eq!(
            code, 5,
            "`{filter}` -- stdout: {stdout:?} stderr: {stderr:?}"
        );
        assert!(
            stderr.contains("flatten depth must not be negative"),
            "`{filter}` -- stderr: {stderr:?}"
        );
    }
    Ok(())
}

/// #1164 coverage: a negative `flatten` depth still errors even when the
/// argument generator that produced it also has a trailing break -- the
/// error arm wins outright (own-error-supersedes-argument's-escape, same
/// rule as `has`'s control test above), independent of the guard on the
/// success arm every other `flatten` test above already exercises.
#[test]
fn test_flatten_negative_depth_errors_even_with_trailing_break_1164() -> Result<()> {
    let (_out, err, code) = run_jq_full(
        &["-c", r"label $out | flatten((-1, break $out))"],
        Some("[[1]]"),
    )?;
    assert_ne!(code, 0);
    assert!(
        err.contains("flatten depth must not be negative"),
        "err={err}"
    );
    Ok(())
}

/// #2755: `flatten`'s success path used to eagerly require a literal
/// non-negative integer depth, rejecting everything else outright with a
/// generic "expected number, got non-number" -- but jq's own reference
/// definition (`_flatten($x): reduce .[] as $i ([]; if ($i|type) ==
/// "array" and $x != 0 then . + ($i | _flatten($x - 1)) else . + [$i]
/// end)`) never converts `$x` up front. It only ever compares `$x != 0`
/// and computes `$x - 1`, both lazily, once per recursion level, only when
/// a genuinely nested array item is actually reached. All values below
/// are live jq 1.7.1 captures.
#[test]
fn test_flatten_depth_argument_is_not_eagerly_converted_2755() -> Result<()> {
    for (filter, input, expected) in [
        // An integral float depth decrements to exactly `0.0`, which
        // compares equal to `0` -- succeeds exactly like the same
        // integer depth would.
        ("flatten(2.0)", "[[1,[2]],3]", "[1,2,3]"),
        // A non-numeric depth with no nesting deep enough to ever reach
        // `$x - 1` never errors at all.
        (r#"flatten("a")"#, "[1,2,3]", "[1,2,3]"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(
            code, 0,
            "`{filter}` on {input}: stdout {stdout:?} stderr {stderr:?}"
        );
        assert_eq!(stdout.trim_end(), expected, "`{filter}` on {input}");
    }
    Ok(())
}

/// #2755: the flip side of the test above -- a non-numeric depth errors
/// only once the recursion actually reaches a nested array and attempts a
/// real `$x - 1`, with the exact type-error wording real subtraction
/// raises (not a generic "expected number" message), and that error is
/// suppressible by `?` like any other evaluation error, matching jq.
#[test]
fn test_flatten_depth_argument_errors_lazily_on_real_nesting_2755() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["-c", r#"flatten("a")"#], Some("[[1,[2]],3]"))?;
    assert_eq!(code, 5, "stdout: {stdout:?} stderr: {stderr:?}");
    assert!(
        stderr.contains(r#"string ("a") and number (1) cannot be subtracted"#),
        "stderr: {stderr:?}"
    );

    let (stdout, stderr, code) = run_jq_full(&["-c", r#"flatten("a")?"#], Some("[[1,[2]],3]"))?;
    assert_eq!(code, 0, "stderr: {stderr:?}");
    assert_eq!(stdout.trim_end(), "");
    Ok(())
}

/// `combinations(n)` uses `n` inside a nested `range(n)` that an array
/// construction then collects, so its escape semantics differ from every
/// other builtin in this block: a trailing break in `n`'s own generator
/// aborts that whole array construction, producing *no* output at all --
/// not "the first n's worth of combinations, then stop".
///
/// This test used to pin the opposite, because `combinations` resolved `n`
/// to a single value and never saw the break. #1279 gave it jq's real model
/// (`def combinations(n): . as $dot | [range(n)] | map($dot) | combinations;`),
/// which fires the escape before the arity is ever used -- deliberately
/// unlike `fanout_arg`'s "run the loop, then escape", and the reason
/// `combinations` is the one builtin in this family that must NOT fan out.
#[test]
fn test_combinations_n_break_aborts_the_whole_construction_1279() -> Result<()> {
    let (out, err, code) = run_jq_full(
        &[
            "-c",
            r#"label $out | (combinations((2, break $out)), "after")"#,
        ],
        Some("[1,2]"),
    )?;
    assert_eq!(code, 0, "err={err}");
    assert_eq!(out, "");
    Ok(())
}

// =============================================================================
// #1045: a generator argument that produces zero outputs (e.g. `empty`, or a
// `select`/`if` that filters everything out) now makes the whole builtin
// call produce zero outputs too, instead of erroring "no value" -- matching
// real jq's `x as $b | ...` desugaring, whose `as` binding runs its body
// zero times when `x` produces nothing. Verified live against real jq for
// every builtin below except `tz`/`load` (succinctly-only extensions with no
// jq equivalent), which get the same fix on the strength of the same
// language-level `as`-desugaring argument, not a per-builtin oracle check.
// =============================================================================

#[test]
fn test_has_empty_argument_produces_no_output_not_error_1045() -> Result<()> {
    let (out, err, code) = run_jq_full(&["-cn", "{\"a\":1} | has(empty)"], None)?;
    assert_eq!(code, 0, "err={err}");
    assert_eq!(out, "");
    Ok(())
}

#[test]
fn test_ltrimstr_rtrimstr_empty_argument_produce_no_output_1045() -> Result<()> {
    let (out, err, code) = run_jq_full(&["-cn", "\"abc\" | ltrimstr(empty)"], None)?;
    assert_eq!(code, 0, "err={err}");
    assert_eq!(out, "");

    let (out, err, code) = run_jq_full(&["-cn", "\"abc\" | rtrimstr(empty)"], None)?;
    assert_eq!(code, 0, "err={err}");
    assert_eq!(out, "");
    Ok(())
}

#[test]
fn test_startswith_endswith_empty_argument_produce_no_output_1045() -> Result<()> {
    let (out, err, code) = run_jq_full(&["-cn", "\"abc\" | startswith(empty)"], None)?;
    assert_eq!(code, 0, "err={err}");
    assert_eq!(out, "");

    let (out, err, code) = run_jq_full(&["-cn", "\"abc\" | endswith(empty)"], None)?;
    assert_eq!(code, 0, "err={err}");
    assert_eq!(out, "");
    Ok(())
}

#[test]
fn test_split_join_empty_argument_produce_no_output_1045() -> Result<()> {
    let (out, err, code) = run_jq_full(&["-cn", "\"a,b\" | split(empty)"], None)?;
    assert_eq!(code, 0, "err={err}");
    assert_eq!(out, "");

    let (out, err, code) = run_jq_full(&["-cn", "[\"a\",\"b\"] | join(empty)"], None)?;
    assert_eq!(code, 0, "err={err}");
    assert_eq!(out, "");
    Ok(())
}

#[test]
fn test_contains_inside_empty_argument_produce_no_output_1045() -> Result<()> {
    // The issue's own repro.
    let (out, err, code) = run_jq_full(&["-cn", "[1,2,3] | contains(empty)"], None)?;
    assert_eq!(code, 0, "err={err}");
    assert_eq!(out, "");

    let (out, err, code) = run_jq_full(&["-cn", "[1,2] | inside(empty)"], None)?;
    assert_eq!(code, 0, "err={err}");
    assert_eq!(out, "");
    Ok(())
}

