/// #1702 fixed `del(.)`/`del(.?)` to emit nothing / no-op in yq mode; confirm
/// `succinctly jq` still follows real jq's own model unchanged — both
/// produce `null` on any target.
#[test]
fn test_jq_mode_root_del_still_null_after_1702() -> Result<()> {
    for expr in ["del(.)", "del(.?)"] {
        let (stdout, stderr, code) = run_jq_full(&["-c", expr], Some(r#"{"a":1}"#))?;
        assert_eq!(stdout.trim(), "null", "expr={expr} stderr: {stderr:?}");
        assert_eq!(code, 0, "expr={expr} stderr: {stderr:?}");
    }
    Ok(())
}

// =============================================================================
// #1428: autovivification must not outlive a write that never happens
// =============================================================================

/// Walking to a write target autovivifies every missing step on the way, but
/// an `Iterate` over the `Null` that creates has no elements to assign to, so
/// the write never happens and the fabricated chain was left behind. jq treats
/// path collection as read-only until a write is confirmed.
///
/// Every expectation here is the pinned jq 1.7.1's own output.
#[test]
fn test_suppressed_write_leaves_no_autovivified_chain_1428() -> Result<()> {
    for (input, filter, expected) in [
        // The issue's own repros.
        ("null", ".a[]? = 9", "null\n"),
        ("[1,2,3]", ".[5][]?[0] = 9", "[1,2,3]\n"),
        ("null", ".a.b[]?[0] = 9", "null\n"),
        // An *existing* object must not gain the key either.
        ("{}", ".a[]? = 9", "{}\n"),
        // Depth is not special: nothing at any level survives.
        ("null", ".a.b.c[]? = 9", "null\n"),
        // A tail after the iterate behaves the same.
        ("null", ".a[]?.b = 9", "null\n"),
        ("null", ".a[]?.b[]? = 9", "null\n"),
        // `|=` shares the walker and the bug.
        ("null", ".a[]? |= .+1", "null\n"),
        ("{}", ".a[]? |= .+1", "{}\n"),
        ("null", ".a[]?.b |= 9", "null\n"),
        // ...and so do the compound operators built on it.
        ("null", ".a[]? += 1", "null\n"),
        // The probe's out-of-range *index* branch: the array exists, so the
        // walk gets that far, but the index is past its end -- which is a slot
        // `write_index` would pad into existence, i.e. "would create". Padding
        // it and then discovering the iterate writes nothing is exactly the
        // stranding this fix removes, here as trailing `null`s rather than a
        // fabricated key.
        ("{\"a\":[1]}", ".a[5][]? = 9", "{\"a\":[1]}\n"),
        ("{\"a\":[1]}", ".a[5][]? |= 9", "{\"a\":[1]}\n"),
        ("{\"a\":[1]}", ".a[5].b[]? = 9", "{\"a\":[1]}\n"),
        ("[1]", ".[5][]? = 9", "[1]\n"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 0, "{input} | {filter} -- stderr={stderr}");
        assert_eq!(stdout, expected, "{input} | {filter}");
    }
    Ok(())
}

/// The other half of #1428, and the reason a naive "never autovivify" fix is
/// wrong: a `?`-suppressed write that *does* happen still creates its chain.
#[test]
fn test_confirmed_write_still_autovivifies_1428() -> Result<()> {
    for (input, filter, expected) in [
        // `?` on a step that resolves: the write lands, so the chain stays.
        ("null", ".a[0]? = 9", "{\"a\":[9]}\n"),
        ("null", ".a?.b = 9", "{\"a\":{\"b\":9}}\n"),
        // No `?` at all -- ordinary autovivification, untouched.
        ("null", ".a = 9", "{\"a\":9}\n"),
        ("null", ".a.b = 9", "{\"a\":{\"b\":9}}\n"),
        ("null", ".a[2] |= 9", "{\"a\":[null,null,9]}\n"),
        // A real iterate target writes to every element.
        ("{\"a\":[1,2]}", ".a[]? = 9", "{\"a\":[9,9]}\n"),
        ("{\"a\":{\"k\":1}}", ".a[]? = 9", "{\"a\":{\"k\":9}}\n"),
        // An empty container is a legitimate zero-element write, and the key
        // already exists, so the document is unchanged either way.
        ("{\"a\":[]}", ".a[]? = 9", "{\"a\":[]}\n"),
        // A slice write on a missing parent genuinely writes -- it must not be
        // skipped along with the iterate cases.
        ("null", ".a[0:1]? = [9]", "{\"a\":[9]}\n"),
        // One path writing and another not, in a single assignment.
        ("null", "(.a[]?, .b) = 9", "{\"b\":9}\n"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 0, "{input} | {filter} -- stderr={stderr}");
        assert_eq!(stdout, expected, "{input} | {filter}");
    }
    Ok(())
}

/// #1428 must not turn a genuine error into a silent no-op. The first version
/// of the fix did exactly that -- reporting "absent" for a wrong-type
/// container let the walker skip errors jq still raises, 59 of them across a
/// differential sweep.
///
/// The distinction that matters: a `?` binds to the component it is written
/// on. In `[] | .a[]? = 9` it is on the *iterate*, so the `.a`-on-an-array
/// type error is still raised.
#[test]
fn test_suppressed_write_still_raises_real_type_errors_1428() -> Result<()> {
    for (input, filter, needle) in [
        ("[]", ".a[]? = 9", "Cannot index array with string"),
        ("5", ".a[]? = 9", "Cannot index number with string"),
        ("\"s\"", ".a.b[]? = 9", "Cannot index string with string"),
        ("true", ".a[]?[0] = 9", "Cannot index boolean with string"),
        (
            "{\"a\":1}",
            ".a.b[]? = 9",
            "Cannot index number with string",
        ),
        ("{}", ".[5][]?[0] = 9", "Cannot index object with number"),
        // No `?` anywhere: iterating a null still raises, and the document is
        // never emitted, so nothing can be left fabricated in it.
        ("null", ".a[] = 9", "Cannot iterate over null"),
    ] {
        let (_, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_ne!(code, 0, "{input} | {filter} must fail");
        assert!(
            stderr.contains(needle),
            "{input} | {filter} -- want {needle:?}, got {stderr}"
        );
    }

    // A `?` on an *earlier* component cancels the whole write, and must not be
    // mistaken for "the parent is missing, go probe the tail" -- doing so
    // manufactured a `Cannot iterate over null` that jq never raises (this is
    // #1298's own case, which caught the second wrong version of this fix).
    let (stdout, stderr, code) = run_jq_full(&["-c", ".a?.b[].c = 9"], Some("5"))?;
    assert_eq!(code, 0, "stderr={stderr}");
    assert_eq!(stdout, "5\n");
    Ok(())
}

/// #1428 review follow-up: a write whose *value* is `null` is still a write.
///
/// The first two versions of this fix inferred "nothing was written" from "the
/// target is still `Null`", which is indistinguishable from a legitimate `null`
/// write. `null | (.a|.) = null` dropped to `null` where jq (and yq) keep
/// `{"a":null}` -- 56 distinct filter shapes regressed this way, none of them
/// covered by the suite, because they all need an explicit `|` inside the path
/// to produce an `Identity`-shaped tail.
///
/// The guard is now structural: it applies only where the deciding component
/// is an `Iterate`, which over a freshly-created `Null` writes nothing *by
/// construction* -- no inspection of the resulting value required.
#[test]
fn test_null_valued_write_is_still_a_write_1428() -> Result<()> {
    for (input, filter, expected) in [
        ("null", "(.a|.) = null", "{\"a\":null}\n"),
        ("null", "(.a|.) = .x", "{\"a\":null}\n"),
        ("null", "(.a|.b) = null", "{\"a\":{\"b\":null}}\n"),
        ("null", "(.a|.) |= null", "{\"a\":null}\n"),
        ("null", "(.a|.) |= .", "{\"a\":null}\n"),
        ("null", "(.a|.) //= null", "{\"a\":null}\n"),
        ("null", "(.a|.) += null", "{\"a\":null}\n"),
        ("null", "(.a[0]|.) |= null", "{\"a\":[null]}\n"),
        (
            "null",
            "(.[5]|.) = null",
            "[null,null,null,null,null,null]\n",
        ),
        // A plain terminal write of `null` was never at risk, but pins the
        // pair: the paren form above and this one must agree.
        ("null", ".a = null", "{\"a\":null}\n"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 0, "{input} | {filter} -- stderr={stderr}");
        assert_eq!(stdout, expected, "{input} | {filter}");
    }
    Ok(())
}

/// #1428 review follow-up: the `|=` walker recurses one component at a time, so
/// a frame two or more levels above the iterate has to undo its own slot too.
///
/// Checking only the head of the remaining path left `null | .a.b[]? |= 9` as
/// `{"a":{}}` -- the inner frame correctly removed `.b`, but `.a` was then an
/// empty object rather than the `Null` it started as, so the outer frame could
/// not tell. 40 (input, filter) pairs were still wrong at that point.
#[test]
fn test_nested_suppressed_update_unwinds_every_level_1428() -> Result<()> {
    for (input, filter) in [
        ("null", ".a.b[]? |= 9"),
        ("null", ".a.b[]? |= null"),
        ("null", ".a.b[]? += 1"),
        ("null", ".a.b.c[]? |= 9"),
        ("null", ".a.b.c.d[]? |= 9"),
        ("null", ".a.b.c[]? //= null"),
        ("{}", ".a.b[]? |= 9"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 0, "{input} | {filter} -- stderr={stderr}");
        assert_eq!(stdout, format!("{input}\n"), "{input} | {filter}");
    }
    Ok(())
}

/// #1428 review follow-up: a slice can be a *read-through* step whose own tail
/// declines to write, and then the chain built to reach it is stranded exactly
/// like the plain iterate case.
///
/// This class was reached only after the guard started making tails legitimately
/// write nothing: `through_slice`'s `Null` arm then saw an unwritten `Null` and
/// raised its write-time "A slice of an array can only be assigned another
/// array", turning a document jq leaves alone into a hard exit-5 failure. The
/// arm now distinguishes the two using `terminal_write`, which exists for
/// exactly that question -- when the edit *is* the write, a `Null` result means
/// the RHS was `null`, and `null | .[0:1] = null` does still raise.
#[test]
fn test_read_through_slice_that_writes_nothing_is_a_noop_1428() -> Result<()> {
    for (input, filter, expected) in [
        ("null", ".[0:1][0][]? = 9", "null\n"),
        ("null", ".[0:1][0][]? |= 9", "null\n"),
        ("null", ".[0:1][0][]? += 1", "null\n"),
        ("null", ".a[0:1][0][]? = 9", "null\n"),
        // The slice immediately followed by an iterate -- filed as #1873 while
        // it was still failing, and closed by this same fix.
        ("null", ".a[0:1][]? = 9", "null\n"),
        ("{}", ".a[0:1][]? = 9", "{}\n"),
        ("null", ".[0:1][]? = 9", "null\n"),
        // An existing `null` parent is untouched either way.
        ("{\"a\":null}", ".a[0:1][]? = 9", "{\"a\":null}\n"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 0, "{input} | {filter} -- stderr={stderr}");
        assert_eq!(stdout, expected, "{input} | {filter}");
    }

    // A slice write that *does* write still builds its chain...
    for (input, filter, expected) in [
        ("null", ".a[0:1] = [9]", "{\"a\":[9]}\n"),
        ("null", ".[0:1] = [9]", "[9]\n"),
        ("null", ".a[0:1][0] = 9", "{\"a\":[9]}\n"),
        ("null", ".a[0:1]? = [9]", "{\"a\":[9]}\n"),
        ("[1,2,3]", ".[0:2] = [9]", "[9,3]\n"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 0, "{input} | {filter} -- stderr={stderr}");
        assert_eq!(stdout, expected, "{input} | {filter}");
    }

    // ...and a terminal slice assignment of a non-array still raises, which is
    // what keeps the `terminal_write` distinction honest.
    for filter in [".[0:1] = null", ".[0:1] = 9"] {
        let (_, stderr, code) = run_jq_full(&["-c", filter], Some("null"))?;
        assert_ne!(code, 0, "{filter} must raise");
        assert!(
            stderr.contains("slice of an array"),
            "{filter} -- got {stderr}"
        );
    }
    Ok(())
}

/// #1428 review follow-up: `update_path`'s slice arm must compute
/// `terminal_write`, not hardcode `false`.
///
/// `set_path`'s slice arm has always derived it from its tail. `update_path`'s
/// hardcoded `false` was harmless while `through_slice`'s `Null` arm treated
/// every unwritten `Null` as an error -- but once that arm learned to no-op for
/// a genuine read-through, the wrong flag made it swallow the real error for a
/// filter that writes `null` directly to the slice.
#[test]
fn test_slice_update_with_identity_tail_still_raises_1428() -> Result<()> {
    for (input, filter) in [
        ("null", "(.a[0:1]|.) |= null"),
        ("{\"a\":null}", "(.a[0:1]|.) |= null"),
        ("null", "(.[0:1]|.) |= null"),
        ("null", "(.a[0:1]|.) |= 9"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_ne!(code, 0, "{input} | {filter} must raise, got {stdout:?}");
        assert!(
            stderr.contains("slice of an array"),
            "{input} | {filter} -- got {stderr}"
        );
    }

    // The read-through spelling of the same shape still no-ops, which is the
    // distinction `terminal_write` draws.
    for (input, filter, expected) in [
        ("null", ".a[0:1][]? |= 9", "null\n"),
        ("null", ".a[0:1][0][]? |= 9", "null\n"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 0, "{input} | {filter} -- stderr={stderr}");
        assert_eq!(stdout, expected, "{input} | {filter}");
    }
    Ok(())
}

/// #2241: a *mid-chain* bare `.` in a write path (`|=`/`del()`) is a
/// transparent pass-through, not a delete/update target in its own right --
/// `update_path_steps`/`delete_path_steps` both fell to a catch-all that
/// routed it into `update_path`/`delete_at_path`'s own *terminal*
/// `Expr::Identity` arm instead, silently discarding everything after it in
/// the chain. Verified against jq 1.7.1 for every assertion below.
#[test]
fn test_mid_chain_identity_does_not_discard_rest_of_write_path_2241() -> Result<()> {
    // `|=`: the issue's own repro.
    let (stdout, _, code) = run_jq_full(&["-c", "(.a | . | .b) |= 99"], Some(r#"{"a":{"b":1}}"#))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), r#"{"a":{"b":99}}"#);

    // `del()`: the same shape.
    let (stdout, _, code) = run_jq_full(&["-c", "del(.a | . | .b)"], Some(r#"{"a":{"b":1}}"#))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), r#"{"a":{}}"#);

    // A compound operator (`+=`) routes through the identical `update_path`
    // machinery as `|=`.
    let (stdout, _, code) = run_jq_full(&["-c", "(.a | . | .b) += 10"], Some(r#"{"a":{"b":1}}"#))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), r#"{"a":{"b":11}}"#);

    // Two identities in a row, and an identity immediately followed by
    // `.[]` -- each exercises a different next-step shape after the
    // pass-through.
    let (stdout, _, code) =
        run_jq_full(&["-c", "(.a | . | . | .b) |= 99"], Some(r#"{"a":{"b":1}}"#))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), r#"{"a":{"b":99}}"#);

    let (stdout, _, code) = run_jq_full(&["-c", "(.a | . | .[]) |= 99"], Some(r#"{"a":[1,2,3]}"#))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), r#"{"a":[99,99,99]}"#);

    let (stdout, _, code) = run_jq_full(&["-c", "del(.a | . | .[1])"], Some(r#"{"a":[1,2,3]}"#))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), r#"{"a":[1,3]}"#);

    Ok(())
}

/// #1876/#1883: `through_slice`'s `OwnedValue::String` *terminal-write* arm
/// used to refuse with the generic `Cannot update string slices` message
/// immediately, without ever running the update filter -- unlike its
/// `!terminal_write` sibling just above it (and every other arm in this
/// function), which always runs `edit` first. This discarded the filter's
/// own side effects (`debug`/`stderr`) and swallowed its own genuine errors
/// (an explicit `error(...)` call, or an arithmetic type error from `+=`/
/// `-=`) behind the generic refusal instead of letting them propagate --
/// confirmed live against jq 1.7.1 for all three repros below.
#[test]
fn test_string_slice_terminal_write_runs_edit_before_refusing_1876_1883() -> Result<()> {
    // `debug`'s stderr side effect still fires even though the write is
    // ultimately refused -- both jq and succinctly print the debug line
    // (with the *sliced* substring "he", proving `edit` really ran against
    // the throwaway substring rather than the whole original string), then
    // refuse with the same generic message.
    let (stdout, stderr, code) = run_jq_full(&["-c", ".[0:2] |= (debug|9)"], Some("\"hello\""))?;
    assert_ne!(code, 0);
    assert!(
        stderr.starts_with("[\"DEBUG:\",\"he\"]\n"),
        "stderr: {stderr}"
    );
    assert!(
        stderr.contains("Cannot update string slices"),
        "stderr: {stderr}"
    );
    assert_eq!(stdout, "");

    // An explicit `error(...)` inside the update filter propagates as
    // itself, not as the generic string-slice refusal.
    let (stdout, stderr, code) =
        run_jq_full(&["-c", ".[0:2] |= error(\"boom\")"], Some("\"hello\""))?;
    assert_ne!(code, 0);
    assert!(stderr.contains("boom"), "stderr: {stderr}");
    assert!(
        !stderr.contains("Cannot update string slices"),
        "stderr: {stderr}"
    );
    assert_eq!(stdout, "");

    // `+=`/`-=`'s own arithmetic type error surfaces instead of the generic
    // refusal (#1883's own repro).
    let (stdout, stderr, code) = run_jq_full(&["-c", ".[0:1] += 1"], Some("\"s\""))?;
    assert_ne!(code, 0);
    assert!(stderr.contains("cannot be added"), "stderr: {stderr}");
    assert!(
        !stderr.contains("Cannot update string slices"),
        "stderr: {stderr}"
    );
    assert_eq!(stdout, "");

    let (stdout, stderr, code) = run_jq_full(&["-c", ".[0:1] -= 1"], Some("\"s\""))?;
    assert_ne!(code, 0);
    assert!(stderr.contains("cannot be subtracted"), "stderr: {stderr}");
    assert!(
        !stderr.contains("Cannot update string slices"),
        "stderr: {stderr}"
    );
    assert_eq!(stdout, "");

    // Control: when the update filter succeeds with an ordinary value, the
    // write is still refused with the generic message (the refusal itself
    // is correct jq behavior -- only the *ordering* relative to `edit`
    // changed).
    let (stdout, stderr, code) = run_jq_full(&["-c", ".[0:1] = \"X\""], Some("\"hello\""))?;
    assert_ne!(code, 0);
    assert!(
        stderr.contains("Cannot update string slices"),
        "stderr: {stderr}"
    );
    assert_eq!(stdout, "");

    Ok(())
}

/// #1894: `through_slice`'s `OwnedValue::Array`/`OwnedValue::String`
/// terminal-write arms didn't special-case an update filter that produced
/// no output at all (`|= empty`). Real jq's `_modify` falls back to
/// `delpaths` when the update filter yields nothing, and deleting a
/// slice-shaped path removes that whole range -- for an array that's
/// exactly "splice in nothing"; for a string, jq raises a different
/// sentence than a non-empty write does. Every case confirmed live against
/// jq 1.7.1.
#[test]
fn test_slice_delete_on_empty_update_filter_1894() -> Result<()> {
    // Array: the sliced range is spliced out, shrinking the array.
    let (stdout, _stderr, code) = run_jq_full(&["-c", ".[0:2] |= empty"], Some("[1,2,3]"))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "[3]");

    // String: a different message than a non-empty string-slice write.
    let (stdout, stderr, code) = run_jq_full(&["-c", ".[0:2] |= empty"], Some("\"hello\""))?;
    assert_ne!(code, 0);
    assert!(
        stderr.contains("Cannot delete fields from string"),
        "stderr: {stderr}"
    );
    assert!(
        !stderr.contains("Cannot update string slices"),
        "stderr: {stderr}"
    );
    assert_eq!(stdout, "");

    // `?` does not suppress this -- it's a write-time application error,
    // not a navigation failure, confirmed live.
    let (stdout, stderr, code) = run_jq_full(&["-c", ".[0:2]? |= empty"], Some("\"hello\""))?;
    assert_ne!(code, 0);
    assert!(
        stderr.contains("Cannot delete fields from string"),
        "stderr: {stderr}"
    );
    assert_eq!(stdout, "");

    // Control: a literal `null` write (not an empty filter) still raises
    // the pre-existing, unaffected error -- the fix distinguishes "no
    // output" from "output is null".
    let (stdout, stderr, code) = run_jq_full(&["-c", ".[0:2] |= null"], Some("[1,2,3]"))?;
    assert_ne!(code, 0);
    assert!(
        stderr.contains("A slice of an array can only be assigned another array"),
        "stderr: {stderr}"
    );
    assert_eq!(stdout, "");

    Ok(())
}

/// #1877: a *nested* terminal slice (reached through another slice, or
/// through an inline `?`) with `|= empty` used to raise "A slice of an
/// array can only be assigned another array" on a `null`/absent target,
/// where real jq leaves the whole document untouched -- confirmed live
/// against jq 1.7.1. This is the same `|= empty` delete/no-op mechanism as
/// #1894, just for the case where nothing exists yet to delete from.
#[test]
fn test_nested_slice_delete_on_empty_update_filter_noops_on_null_1877() -> Result<()> {
    let (stdout, _stderr, code) = run_jq_full(&["-c", ".a[0:1][0:2]? |= empty"], Some("null"))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "null");

    // Two slices chained directly (no `?`, no absent field) on an existing
    // array -- the inner slice's own delete-and-splice composes correctly
    // with the outer one's.
    let (stdout, _stderr, code) =
        run_jq_full(&["-c", "(.[0:3] | .[0:1]) |= empty"], Some("[1,2,3,4,5]"))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "[2,3,4,5]");

    // A slice followed by a plain `Index` (not another slice) -- #1916
    // closed the general "`.a |= empty` should delete the key/element, not
    // write `null`" gap for `Field`/`Index`, so this now deletes the
    // element too, matching jq's own answer, rather than the `[null,2,3,4]`
    // this assertion recorded before that fix landed.
    let (stdout, _stderr, code) = run_jq_full(&["-c", ".[0:2][0] |= empty"], Some("[1,2,3,4]"))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "[2,3,4]");

    Ok(())
}

/// #1916: an update filter that produces no output at all deletes the
/// key/element it targets, rather than leaving it `null` -- jq's `_modify`
/// falls back to `delpaths` here (the same mechanism #1877/#1894 already
/// gave `through_slice`'s slice arms). Every expected value below is real
/// jq 1.7.1's own output, captured live.
#[test]
fn test_field_index_iterate_delete_on_empty_update_filter_1916() -> Result<()> {
    // Field: the key disappears entirely, not `"a":null`.
    let (stdout, _stderr, code) = run_jq_full(&["-c", ".a |= empty"], Some(r#"{"a":1,"b":2}"#))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), r#"{"b":2}"#);

    // Index: the element is removed, the array shrinks.
    let (stdout, _stderr, code) = run_jq_full(&["-c", ".[0] |= empty"], Some("[1,2,3]"))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "[2,3]");

    // Iterate over an array: every element that updates to nothing is
    // dropped.
    let (stdout, _stderr, code) = run_jq_full(&["-c", ".[] |= empty"], Some("[1,2,3]"))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "[]");

    // Iterate over an object: same, keyed by name.
    let (stdout, _stderr, code) = run_jq_full(&["-c", ".[] |= empty"], Some(r#"{"a":1,"b":2}"#))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "{}");

    // Out-of-range positive/negative indices stay a true no-op: nothing
    // was ever really there to delete, so nothing is padded in either.
    let (stdout, _stderr, code) = run_jq_full(&["-c", ".[5] |= empty"], Some("[1,2,3]"))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "[1,2,3]");
    let (stdout, _stderr, code) = run_jq_full(&["-c", ".[-5] |= empty"], Some("[1,2,3]"))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "[1,2,3]");

    // The bounds check on a *real* write still fires -- it lives on the
    // write path, not the delete path an empty filter takes instead.
    let (stdout, stderr, code) = run_jq_full(&["-c", ".[-5] |= 99"], Some("[1,2,3]"))?;
    assert_ne!(code, 0);
    assert!(
        stderr.contains("Out of bounds negative array index"),
        "stderr: {stderr}"
    );
    assert_eq!(stdout, "");

    // An autovivified container that ends up with nothing written into it
    // reverts to `null` rather than surfacing as an artifact of the
    // attempt (`{}`/`[]`).
    let (stdout, _stderr, code) = run_jq_full(&["-c", ".a |= empty"], Some("null"))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "null");
    let (stdout, _stderr, code) = run_jq_full(&["-c", ".[0] |= empty"], Some("null"))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), "null");

    // Nested: only the reached leaf is deleted, ancestors that already
    // existed are left in place.
    let (stdout, _stderr, code) = run_jq_full(&["-c", ".a.b |= empty"], Some(r#"{"a":{"b":1}}"#))?;
    assert_eq!(code, 0);
    assert_eq!(stdout.trim(), r#"{"a":{}}"#);

    Ok(())
}

/// #1653: `--unbuffered` must actually interleave stdout and stderr in real
/// time, not merely flush a batch that was already fully evaluated.
///
/// Every expected string here is jq 1.7.1's own combined output, captured
/// live. The property is *ordering*, so these assert on one merged stream
/// (`run_jq_interleaved`) -- separately-captured pipes would pass even with
/// the batching bug, since each stream's own contents were always correct.
///
/// The `-n` and `--slurp` forms were the first routes to stream (PR #1892).
/// The M2 rows -- a document read from stdin, the CLI's default -- were added
/// once that route was gated on a cursor-transparency predicate and streamed
/// too: `.[]|debug` is the shape the issue was filed about, and the `stderr`,
/// `error` and `halt_error` rows check that a side effect mid-generator lands
/// between the outputs either side of it rather than ahead of all of them.
///
/// #2103 removed that gate: **every** M2 filter streams now, including the
/// root-forwarding shapes the gate used to keep on the eager route, which
/// therefore used to batch. The last three rows are exactly those shapes,
/// and each one visibly reordered under the old route -- verified at the
/// time by running them against the (now-deleted) `SUCCINCTLY_JQ_M2_EVAL=eager`
/// hook, which produced `["DEBUG:",1]` *before* the first `1`, `[1,2][1,2]`
/// before the first `[1,2]`, and `["DEBUG:",1]` before `2` respectively. So
/// they discriminate the fix rather than merely passing alongside it.
#[test]
fn test_unbuffered_interleaves_stdout_and_stderr_1653() -> Result<()> {
    // (args, stdin, combined stdout+stderr, exit code) -- all four captured
    // live from jq 1.7.1, byte for byte.
    for (args, input, expected, expected_code) in [
        // The issue's own repro: `1` is written before `debug` is evaluated.
        (
            vec!["--unbuffered", "-cn", "1, debug, 2"],
            None,
            "1\n[\"DEBUG:\",null]\nnull\n2\n",
            0,
        ),
        // An uncaught error is a side effect with the same ordering rule:
        // the outputs that preceded it are already on stdout.
        (
            vec!["--unbuffered", "-cn", "1, error(\"x\"), 3"],
            None,
            "1\njq: error (at <unknown>): x\n",
            5,
        ),
        // `halt_error` writes its payload after the earlier output. A
        // *number* payload is written as JSON with a trailing newline (a
        // string payload is the raw, newline-less case) -- captured from
        // jq, not assumed.
        (
            vec!["--unbuffered", "-cn", "1, (2|halt_error), 3"],
            None,
            "1\n2\n",
            5,
        ),
        // `stderr` echoes its input without a trailing newline, so the
        // interleaving is visible as `null` butting against the next line.
        (
            vec!["--unbuffered", "-cn", "1, stderr, 2"],
            None,
            "1\nnullnull\n2\n",
            0,
        ),
        // Per-element, through a pipe: each element's stdout write lands
        // before the next element is evaluated at all.
        (
            vec!["--unbuffered", "-cn", "range(3) | (., debug)"],
            None,
            "0\n[\"DEBUG:\",0]\n0\n1\n[\"DEBUG:\",1]\n1\n2\n[\"DEBUG:\",2]\n2\n",
            0,
        ),
        // `--slurp` reaches the same streaming path.
        (
            vec!["--unbuffered", "-c", "--slurp", "1, debug, 2"],
            Some("{}"),
            "1\n[\"DEBUG:\",[{}]]\n[{}]\n2\n",
            0,
        ),
        // So does the input-queue bridge (`inputs`), which streams through
        // `eval_each_owned` rather than collecting first.
        (
            vec!["--unbuffered", "-cn", "inputs, debug"],
            Some("1\n2\n"),
            "1\n2\n[\"DEBUG:\",null]\nnull\n",
            0,
        ),
        // `-S` forces materialization and so routes here too -- one of four
        // flags (`-S`, `-a`, `-R`, `--seq`) this fix reaches that the first
        // draft of the compliance note failed to list.
        (
            vec!["--unbuffered", "-c", "-S", "1, debug, 2"],
            Some("{}"),
            "1\n[\"DEBUG:\",{}]\n{}\n2\n",
            0,
        ),
        // The M2 lazy path: a document read from stdin. `.[]|debug` is
        // #1653's own repro -- every one of these was captured from jq
        // 1.7.1 byte for byte, same as the rows above.
        (
            vec!["--unbuffered", "-c", ".[]|debug"],
            Some("[1,2]"),
            "[\"DEBUG:\",1]\n1\n[\"DEBUG:\",2]\n2\n",
            0,
        ),
        // `stderr` writes its input and passes it through, so each element
        // appears twice, adjacent -- not all the stderr copies first.
        (
            vec!["--unbuffered", "-c", ".[] | (., stderr)"],
            Some("[1,2]"),
            "1\n11\n2\n22\n",
            0,
        ),
        // An error mid-document: the element before it is already written.
        (
            vec![
                "--unbuffered",
                "-c",
                ".[] | if .==2 then error(\"x\") else . end",
            ],
            Some("[1,2,3]"),
            "1\njq: error (at <stdin>:0): x\n",
            5,
        ),
        // `halt_error` stops the process, so only what preceded it survives
        // -- the `1` on stdout, then its own `2` on stderr. Exit 5, jq's
        // default for a bare `halt_error`, not the halted value.
        (
            vec!["--unbuffered", "-c", ".[] | (., (2|halt_error))"],
            Some("[1,2]"),
            "1\n2\n",
            5,
        ),
        // #2103's newly-admitted shapes, all at the *root*: before the gate
        // came off, each of these fell to the eager route and batched.
        //
        // A root-forwarding comma with `debug` in the middle. Eager order
        // was `["DEBUG:",1]` first, ahead of both stdout `1`s.
        (
            vec!["--unbuffered", "-c", ". , debug, ."],
            Some("1"),
            "1\n[\"DEBUG:\",1]\n1\n1\n",
            0,
        ),
        // The same shape with `stderr`, whose newline-less write makes the
        // interleaving unmistakable: eager put `[1,2][1,2]` first.
        (
            vec!["--unbuffered", "-c", "(., stderr)"],
            Some("[1,2]"),
            "[1,2]\n[1,2][1,2]\n",
            0,
        ),
        // A filter whose first branch reads nothing at all -- the class
        // #2103's validity divergence is about. Eager order was
        // `["DEBUG:",1]`, `2`, `1`.
        (
            vec!["--unbuffered", "-c", "1+1, debug"],
            Some("1"),
            "2\n[\"DEBUG:\",1]\n1\n",
            0,
        ),
    ] {
        let (combined, code) = run_jq_interleaved(&args, input)?;
        assert_eq!(combined, expected, "args {args:?} input {input:?}");
        // The exit code is pinned alongside the bytes rather than derived
        // from them: it is part of the captured behaviour for the
        // `error(...)`/`halt_error` rows.
        assert_eq!(code, expected_code, "exit code for {args:?}");
    }
    Ok(())
}

/// #1653: the streaming path's own `--input-dsv` row loop, including the
/// `-e` branch that materializes each row's last output.
///
/// `--input-dsv` was a fifth `evaluate_input` call site the first pass at
/// #1653 missed, so it kept batching after every other route streamed; these
/// pin both that it streams and that `-e` still reports row truthiness.
#[test]
fn test_dsv_rows_stream_and_track_exit_status_1653() -> Result<()> {
    let dir = std::env::temp_dir().join(format!("sjq-dsv-1653-{}", std::process::id()));
    std::fs::create_dir_all(&dir)?;
    let csv = dir.join("rows.csv");
    std::fs::write(&csv, "a,b\n1,2\n")?;
    let path = csv.to_str().expect("temp path is utf-8");

    // Each row's output is written before the next row is evaluated, so the
    // per-row `debug` lands *after* that row's own `1`, not before both rows.
    let (combined, code) = run_jq_interleaved(
        &[
            "--unbuffered",
            "-c",
            "--input-dsv",
            ",",
            "1, debug, 2",
            path,
        ],
        None,
    )?;
    assert_eq!(
        combined,
        "1\n[\"DEBUG:\",[\"a\",\"b\"]]\n[\"a\",\"b\"]\n2\n\
         1\n[\"DEBUG:\",[\"1\",\"2\"]]\n[\"1\",\"2\"]\n2\n"
    );
    assert_eq!(code, 0);

    // `-e` on the same path: the last output drives the exit code.
    let (out, _err, code) = run_jq_full(&["-c", "-e", "--input-dsv", ",", ".[0]", path], None)?;
    assert_eq!(out, "\"a\"\n\"1\"\n");
    assert_eq!(code, 0);
    let (_out, _err, code) = run_jq_full(&["-c", "-e", "--input-dsv", ",", "null", path], None)?;
    assert_eq!(code, 1, "a null last output is jq's falsy exit");

    let _ = std::fs::remove_dir_all(&dir);
    Ok(())
}

/// #1653: a `LazySeq` item that fails while being materialized on the
/// streaming path still reports through `sink`, for each control it can
/// raise.
///
/// `map(f)` stays lazy until this boundary forces it, so `f`'s own
/// error/halt surfaces here rather than during evaluation -- the one arm of
/// `materialize_stream_item` that handles a control at all (every other
/// control is the `Flow`'s outcome, reported by the caller).
#[test]
fn test_streamed_lazy_seq_materialization_control_1653() -> Result<()> {
    for (filter, expected_out, expected_code, expected_err) in [
        ("[1,2]|map(.+1)", "[2,3]\n", 0, ""),
        (
            "[1,0]|map(1/.)",
            "",
            5,
            "number (1) and number (0) cannot be divided because the divisor is zero",
        ),
        (
            "[1,2]|map(if .==2 then halt_error(3) else . end)",
            "",
            3,
            "2",
        ),
    ] {
        let (out, err, code) = run_jq_full(&["--slurp", "-c", filter], Some("{}"))?;
        assert_eq!(out, expected_out, "stdout for {filter}");
        assert_eq!(code, expected_code, "exit for {filter} -- stderr={err}");
        if expected_err.is_empty() {
            assert_eq!(err, "", "stderr for {filter}");
        } else {
            assert!(
                err.contains(expected_err),
                "stderr for {filter}: got {err:?}"
            );
        }
    }
    Ok(())
}

/// #1723: one RFC 7464 record can hold more than one JSON value, and real jq
/// emits every one of them.
///
/// `succinctly jq --seq` used to drop such a record **in full**, exit 0 --
/// silent data loss on a record real jq reads fine, not the missing-warning
/// gap #1723 was filed as. The cause was `seq_record_parses` validating the
/// whole record as a single value, so `1 2` looked malformed.
///
/// Every expectation captured from jq 1.7.1.
#[test]
fn test_seq_record_with_multiple_values_emits_all_1723() -> Result<()> {
    for (input, expected) in [
        // Mixed types, whitespace-separated.
        ("\x1e1 \"x\" [2]\n", "1\n\"x\"\n[2]\n"),
        // A newline is just whitespace inside a record -- not a boundary.
        ("\x1e1\n2\n", "1\n2\n"),
        ("\x1enull null\n", "null\nnull\n"),
        ("\x1e\"a\" \"b\"\n", "\"a\"\n\"b\"\n"),
        ("\x1etrue false null\n", "true\nfalse\nnull\n"),
        ("\x1e[1] 2 {\"a\":3}\n", "[1]\n2\n{\"a\":3}\n"),
        ("\x1e{\"a\":1} {\"b\":2}\n", "{\"a\":1}\n{\"b\":2}\n"),
        ("\x1e{} []\n", "{}\n[]\n"),
        ("\x1e-1 -2\n", "-1\n-2\n"),
        ("\x1e1  2\n", "1\n2\n"),
        // Multi-value records interleave with ordinary single-value ones.
        ("\x1e1 2\n\x1e3\n", "1\n2\n3\n"),
        // The leading-zero retry (#1243) still applies, in either position.
        ("\x1e007e5 1\n", "7E+5\n1\n"),
        ("\x1e1 007e5\n", "1\n7E+5\n"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["--seq", "-c", "."], Some(input))?;
        let stripped: String = stdout.chars().filter(|&c| c != '\u{1e}').collect();
        assert_eq!(stripped, expected, "input {input:?} -- stderr={stderr}");
        assert_eq!(code, 0, "input {input:?}");
    }
    Ok(())
}

/// #1723: adding multi-value support must not resurrect a value real jq
/// abandons.
///
/// Two rules would have been broken by a naive "emit every value in the
/// record" change, and each is pinned here because the differential sweep
/// caught them as regressions in the first drafts:
///
/// 1. A record's *last* value is dropped when it is a bare number with no
///    terminating byte after it -- jq's incremental number scanner cannot
///    rule out more digits arriving. That rule was already encoded for the
///    stream's final record; it is really per-record, so `\x1e1 2\x1e3`
///    keeps `1` and `3` but drops the `2`, while a single newline after the
///    `2` disambiguates it and all three survive.
/// 2. Input with **no RS byte anywhere** is abandoned wholesale (#1525),
///    however well-formed its content is -- relaxing the trailing-record
///    skip for multi-value records started emitting it.
#[test]
fn test_seq_multivalue_still_drops_what_jq_abandons_1723() -> Result<()> {
    for (input, expected, why) in [
        (
            "\x1e1 2\x1e3\n",
            "1\n3\n",
            "bare number before RS is ambiguous",
        ),
        (
            "\x1e1 2\n\x1e3\n",
            "1\n2\n3\n",
            "a newline disambiguates it",
        ),
        ("\x1e1 2", "1\n", "bare number at EOF is ambiguous"),
        ("\x1e1 2 ", "1\n2\n", "trailing space disambiguates it"),
        (
            "1 2\n",
            "",
            "no RS byte anywhere: whole input abandoned (#1525)",
        ),
        (
            "\x1e1\n\x1e2",
            "1\n",
            "single-value trailing bare number, unchanged",
        ),
        ("\x1e1\n", "1\n", "plain single-value record, unchanged"),
        ("\x1e{\"a\":1\n", "", "malformed record still dropped whole"),
    ] {
        let (stdout, _stderr, code) = run_jq_full(&["--seq", "-c", "."], Some(input))?;
        let stripped: String = stdout.chars().filter(|&c| c != '\u{1e}').collect();
        assert_eq!(stripped, expected, "input {input:?} -- {why}");
        assert_eq!(code, 0, "input {input:?}");
    }
    Ok(())
}

/// #1723 code review: content before the *first* RS byte is not a record,
/// and real jq discards it however well-formed it is.
///
/// Multi-value support made a pre-existing single-value leak here emit
/// *every* value in that prefix, widening the divergence rather than
/// introducing it -- `"a" "b"\x1e3` printed all three. Both the widened and
/// the original leak are fixed: only `3` survives, as in jq.
#[test]
fn test_seq_discards_content_before_first_rs_byte_1723() -> Result<()> {
    for (input, expected, why) in [
        (
            "\"a\" \"b\"\x1e3\n",
            "3\n",
            "multi-value prefix, widened by #1723",
        ),
        (
            "\"a\"\x1e3\n",
            "3\n",
            "single-value prefix, leaked on main too",
        ),
        ("1 2\x1e3\n", "3\n", "numeric prefix"),
        (
            "1 2\n",
            "",
            "no RS at all: #1525 abandonment still owns this",
        ),
    ] {
        let (stdout, _stderr, code) = run_jq_full(&["--seq", "-c", "."], Some(input))?;
        let stripped: String = stdout.chars().filter(|&c| c != '\u{1e}').collect();
        assert_eq!(stripped, expected, "input {input:?} -- {why}");
        assert_eq!(code, 0, "input {input:?}");
    }
    Ok(())
}

/// #1723 code review: the error-location marker a `--seq` value reports.
///
/// Three separate offset defects, none of which any existing test could
/// catch because none assert the `(at file:line)` marker at all:
///
/// - `seq_trailing_record_is_dropped` tested the trailing record's *first
///   byte* for "ambiguous bare number". Before #1723 a record was always one
///   value, so first-byte and last-value were the same question; with
///   multi-value records they differ, and `\x1e1 "a"` reported `<unknown>`
///   where jq names the line.
/// - Non-last values paired ranges taken from the *trimmed* record with the
///   *untrimmed* record's start offset, so leading whitespace shifted the
///   reported line (`\x1e  "a"\n"b"\n`).
/// - Scanning a leading-zero-normalized copy produced ranges shorter than
///   the original, because normalization *deletes* zeros rather than
///   rewriting in place (`\x1e0007\n"b"\n`). Ranges now always index the
///   original text, with normalization applied per value.
#[test]
fn test_seq_value_error_location_marker_1723() -> Result<()> {
    let dir = std::env::temp_dir().join(format!("sjq-seq-1723-{}", std::process::id()));
    std::fs::create_dir_all(&dir)?;
    let file = dir.join("z.json");
    let path = file.to_str().expect("temp path is utf-8");

    for (input, expected_marker, why) in [
        ("\x1e1 \"a\"", "z.json:0", "last value is not a bare number"),
        (
            "\x1e\"a\" 2",
            "<unknown>",
            "last value IS an ambiguous bare number",
        ),
        (
            "\x1e  \"a\"\n\"b\"\n",
            "z.json:2",
            "leading whitespace must not shift the line",
        ),
        (
            "\x1e0007\n\"b\"\n",
            "z.json:2",
            "normalization must not shift the line",
        ),
        ("\x1e\"a\"", "z.json:0", "single value, unchanged"),
        (
            "\x1e1\n\x1e2",
            "<unknown>",
            "single trailing bare number, unchanged",
        ),
    ] {
        std::fs::write(&file, input)?;
        let (_out, stderr, _code) =
            run_jq_full(&["--seq", "-s", "-c", "error(\"x\")", path], None)?;
        let marker = stderr
            .lines()
            .find(|l| l.starts_with("jq: error"))
            .unwrap_or_default();
        assert!(
            marker.contains(expected_marker),
            "input {input:?} -- {why}: expected {expected_marker:?} in {marker:?}"
        );
    }
    let _ = std::fs::remove_dir_all(&dir);
    Ok(())
}

/// #1723: `--seq` must never emit a value real jq does not.
///
/// #1914 taught the record reader to split a record into several values,
/// which is right for a cleanly separated record but wrong the moment tokens
/// are *adjacent*: a scanner splits `1-2` into `1` and `-2`, while jq lexes
/// it as one malformed number and prints nothing. That shipped, and it made
/// `succinctly jq --seq` **fabricate output** on 205 of 1500 randomly
/// generated records.
///
/// A first attempt at this issue tried to imitate jq's resync instead
/// (emit the prefix, skip the bad token, continue) and fabricated *more*,
/// because jq's `--seq` reader is a streaming lexer/parser with error
/// recovery and a token scanner cannot imitate one. Requiring whitespace
/// after every token is what makes fabrication structurally impossible: the
/// adjacency a scanner mis-splits is exactly what is now rejected.
///
/// Each row here emits nothing, matching jq. Before this fix every one of
/// them emitted values.
#[test]
fn test_seq_adjacent_tokens_never_fabricate_1723() -> Result<()> {
    for (input, expected, why) in [
        ("\x1e1-2\n", "", "one malformed number, not `1` and `-2`"),
        ("\x1e1null\n", "", "not `1` and `null`"),
        ("\x1e12true\n", "", "not `12` and `true`"),
        ("\x1etrue1\n", "", "not `true` and `1`"),
        (
            "\x1e5-3 7\n",
            "7\n",
            "must not print `-3` out of the middle of a bad token",
        ),
        ("\x1e1.5true\n", "", "a fractional number is no different"),
        ("\x1e0007null\n", "", "nor is a leading-zero one"),
    ] {
        let (stdout, _stderr, code) = run_jq_full(&["--seq", "-c", "."], Some(input))?;
        let stripped: String = stdout.chars().filter(|&c| c != '\u{1e}').collect();
        assert_eq!(stripped, expected, "input {input:?} -- {why}");
        assert_eq!(code, 0, "input {input:?}");
    }
    Ok(())
}

/// #2653: a malformed suffix preserves values jq handed off before it.
#[test]
fn test_seq_partially_readable_record_emits_jq_prefix_2653() -> Result<()> {
    for (input, expected) in [
        ("\x1e1 {invalid\n", "1"),
        ("\x1e1,2\n", "2"),
        ("\x1e} 5\n", "5"),
        ("\x1e{\"a\":1} xyz\n", "{\"a\":1}"),
    ] {
        let (stdout, _stderr, code) = run_jq_full(&["--seq", "-c", "."], Some(input))?;
        let stripped: String = stdout.chars().filter(|&c| c != '\u{1e}').collect();
        assert_eq!(
            stripped,
            format!("{expected}\n"),
            "input {input:?}: jq emits {expected}"
        );
        assert_eq!(code, 0, "input {input:?}");
    }
    Ok(())
}

/// #1723: a record that *ends* unresolved leaves real jq with no EOF
/// position, even when it yielded values first.
///
/// `\x1e"a" 2` emits `"a"` and still reports `<unknown>`, because its
/// trailing `2` never resolved. Defining "dropped" as "yielded nothing"
/// instead got this backwards and broke #1542's own location test — pinned
/// here so the two questions cannot be conflated again.
#[test]
fn test_seq_trailing_unresolved_still_reports_unknown_1723() -> Result<()> {
    let dir = std::env::temp_dir().join(format!("sjq-seq-unres-{}", std::process::id()));
    std::fs::create_dir_all(&dir)?;
    let file = dir.join("z.json");
    let path = file.to_str().expect("temp path is utf-8");

    for (input, expected_marker, why) in [
        (
            "\x1e\"a\" 2",
            "<unknown>",
            "yields \"a\", but ends unresolved",
        ),
        ("\x1e1 \"a\"", "z.json:0", "ends resolved"),
        ("\x1e\"a\"", "z.json:0", "single resolved value"),
        ("\x1e1", "<unknown>", "single unresolved bare number"),
        ("\x1e{\"a\":1", "<unknown>", "unterminated container"),
        (
            "\x1e\"a",
            "<unknown>",
            "unterminated string, not just container",
        ),
        (
            "\x1e\"\\uZZZZ\"",
            "<unknown>",
            "scans as a complete string but fails strict validation",
        ),
        (
            "\x1e1a",
            "<unknown>",
            "pending number token butts against a non-delimiter byte",
        ),
        (
            "\x1etrue",
            "z.json:0",
            "bare literal alone at real EOF is still terminated, unlike a number",
        ),
    ] {
        std::fs::write(&file, input)?;
        let (_out, stderr, _code) =
            run_jq_full(&["--seq", "-s", "-c", "error(\"x\")", path], None)?;
        let marker = stderr
            .lines()
            .find(|l| l.starts_with("jq: error"))
            .unwrap_or_default();
        assert!(
            marker.contains(expected_marker),
            "input {input:?} -- {why}: expected {expected_marker:?} in {marker:?}"
        );
    }
    let _ = std::fs::remove_dir_all(&dir);
    Ok(())
}

/// #1928: a self-delimiting token needs no separator after it.
///
/// The first version of this fix required whitespace after *every* token,
/// which dropped records real jq reads fully — a review measured 332 such
/// regressions. A string, object or array carries its own closing
/// delimiter, so adjacency cannot mis-split it; only a number or bare
/// literal is "pending" and genuinely ambiguous.
#[test]
fn test_seq_self_delimiting_tokens_need_no_separator_1928() -> Result<()> {
    for (input, expected) in [
        ("\x1e{\"a\":1}{\"b\":2}\n", "{\"a\":1}\n{\"b\":2}\n"),
        ("\x1e\"a\"\"b\"\n", "\"a\"\n\"b\"\n"),
        ("\x1e[1][2]\n", "[1]\n[2]\n"),
        // A pending token is confirmed by the *start* of a self-delimiting
        // value just as well as by whitespace.
        ("\x1e1[1]\n", "1\n[1]\n"),
        ("\x1e1\"a\"\n", "1\n\"a\"\n"),
        ("\x1e1{\"b\":2}\n", "1\n{\"b\":2}\n"),
    ] {
        let (stdout, _stderr, code) = run_jq_full(&["--seq", "-c", "."], Some(input))?;
        let stripped: String = stdout.chars().filter(|&c| c != '\u{1e}').collect();
        assert_eq!(stripped, expected, "input {input:?}");
        assert_eq!(code, 0, "input {input:?}");
    }
    Ok(())
}

/// #1928: a bare `true`/`false`/`null` is truncated at an **RS byte** but
/// not at real **EOF** -- unlike a bare number, which is truncated at both.
///
/// | token | at an RS byte | at real EOF |
/// |-------|---------------|-------------|
/// | number (`1`) | abandoned | abandoned |
/// | literal (`true`) | abandoned | **kept** |
/// | string/array/object | kept | kept |
///
/// A number can always take more digits; at EOF jq has seen all the input
/// there will ever be, so a literal is complete. Both halves are pinned
/// because each direction was got wrong once: checking numbers alone left 92
/// shapes emitting a `true` jq drops, and then checking literals at every
/// boundary dropped `printf '\x1etrue'`, which jq prints.
#[test]
fn test_seq_pending_literal_at_boundary_is_truncated_1928() -> Result<()> {
    for (input, expected, why) in [
        // At real EOF a literal is complete -- the half a stricter rule broke.
        ("\x1etrue", "true\n", "bare literal at EOF is kept"),
        ("\x1enull", "null\n", "so is null"),
        ("\x1e\"a\" true", "\"a\"\ntrue\n", "and after another value"),
        ("\x1e{} null", "{}\nnull\n", "likewise"),
        // A number is abandoned at EOF, which is the contrast that makes the
        // rule per-token-kind rather than per-boundary.
        ("\x1e1", "", "a bare number at EOF is still abandoned"),
        (
            "\x1etrue\x1e3\n",
            "3\n",
            "bare literal before RS is abandoned",
        ),
        ("\x1enull\x1e3\n", "3\n", "so is null"),
        ("\x1e5\x1e3\n", "3\n", "as for a bare number, unchanged"),
        ("\x1etrue\n\x1e3\n", "true\n3\n", "a newline confirms it"),
        ("\x1e\"a\"\x1e3\n", "\"a\"\n3\n", "a string self-terminates"),
        ("\x1e[1]\x1e3\n", "[1]\n3\n", "so does an array"),
    ] {
        let (stdout, _stderr, code) = run_jq_full(&["--seq", "-c", "."], Some(input))?;
        let stripped: String = stdout.chars().filter(|&c| c != '\u{1e}').collect();
        assert_eq!(stripped, expected, "input {input:?} -- {why}");
        assert_eq!(code, 0, "input {input:?}");
    }
    Ok(())
}

// ---------------------------------------------------------------------------
// #1473: compile-time function resolution.
//
// Real jq resolves every function call before reading input: an undefined
// function -- or an undefined arity of an existing one -- is a compile error,
// unconditional, uncatchable, exit 3. succinctly resolved calls lazily during
// evaluation instead, so the error was skippable (an unreached branch),
// catchable (`try`/`?`), and carried the runtime exit code 5; two forward
// references real jq rejects computed a value instead.
//
// Every expectation below was captured from the pinned oracle (`/usr/bin/jq`,
// jq-1.7.1) rather than from succinctly's own output.
// ---------------------------------------------------------------------------

/// A jq builtin succinctly does not implement must still *compile* when it is
/// mentioned somewhere evaluation never reaches -- real jq compiles it, so
/// rejecting it would be a regression #1473's resolution pass introduced.
///
/// The roster in `src/jq/resolve.rs` is what makes this hold, and
/// `jq_builtin_roster_matches_the_pinned_capture` (that module's own tests)
/// checks the roster against `tests/data/jq-builtin-names.txt` entry by entry.
/// This test covers the other half -- that the roster is actually consulted --
/// on a representative sample rather than all 218 names: a whole-roster sweep
/// through the CLI also exercises the *parser*, which is a separate concern
/// from resolution (`modulemeta` used to diverge there -- #2035 -- until its
/// parser arity was fixed to match jq's actual `modulemeta/0`).
#[test]
fn test_unimplemented_jq_builtins_still_compile_when_unreached_1473() -> Result<()> {
    for call in [
        "cbrt",
        "hypot(.; .)",
        "fma(.; .; .)",
        "frexp",
        "JOIN(.; .; .; .)",
        "format(.)",
        "input_filename",
        "get_search_list",
        "strflocaltime(.)",
        "significand",
    ] {
        let filter = format!("if false then {call} else 1 end");
        let (stdout, stderr, code) = run_jq_full(&["-c", &filter], Some("null"))?;
        assert_eq!(code, 0, "{call}: stderr {stderr:?}");
        assert_eq!(stdout.trim_end(), "1", "{call}: stderr {stderr:?}");
    }
    Ok(())
}

/// A jq builtin succinctly does not implement stays a *runtime* error when the
/// call is actually reached -- the roster defers it, it does not silence it.
#[test]
fn test_unimplemented_jq_builtin_still_errors_when_reached_1473() -> Result<()> {
    let (_stdout, stderr, code) = run_jq_full(&["-c", "cbrt"], Some("8"))?;
    assert_eq!(code, 5, "stderr: {stderr:?}");
    assert!(
        stderr.contains("undefined function: cbrt/0"),
        "stderr: {stderr:?}"
    );
    Ok(())
}

/// `modulemeta` is arity 0 in real jq (it reads the module name from `.`, not
/// a paren'd argument) -- succinctly's parser previously demanded
/// `modulemeta(...)`, inverted from jq's actual grammar. The arity/parse
/// dimension below is confirmed against the pinned oracle (`/usr/bin/jq`,
/// jq-1.7.1) (#2035).
#[test]
fn test_modulemeta_is_arity_zero_2035() -> Result<()> {
    // Bare `modulemeta`, no parens, must parse -- matching `if false then
    // modulemeta else 1 end` => 1 in real jq (an unreached call still has to
    // compile).
    let (stdout, stderr, code) =
        run_jq_full(&["-nc", "if false then modulemeta else 1 end"], None)?;
    assert_eq!(code, 0, "stderr: {stderr:?}");
    assert_eq!(stdout.trim_end(), "1");

    Ok(())
}

/// Real jq's `modulemeta` is not a pure no-op: it always errors, since there
/// is never a real module to resolve in this repo's single-file CLI/library
/// context -- a type-check error for non-string `.`, otherwise "module not
/// found" citing the name. `builtin_modulemeta` (`src/jq/eval.rs`) used to
/// unconditionally return `null`, ignoring `.` entirely; both cases now
/// raise, matching the pinned oracle (`/usr/bin/jq`, jq-1.7.1) byte for byte
/// (#2111).
#[test]
fn test_modulemeta_always_errors_like_jq_2111() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["-c", "modulemeta"], Some("null"))?;
    assert_eq!(stdout, "");
    assert_eq!(
        stderr,
        "jq: error (at <stdin>:0): modulemeta input module name must be a string\n"
    );
    assert_eq!(code, 5);

    let (stdout, stderr, code) = run_jq_full(&["-c", "modulemeta"], Some(r#""foo""#))?;
    assert_eq!(stdout, "");
    assert_eq!(stderr, "jq: error (at <stdin>:0): module not found: foo\n");
    assert_eq!(code, 5);

    // `?` suppresses both -- ordinary errors, not decode failures (#1620).
    let (stdout, stderr, code) = run_jq_full(&["-c", "modulemeta?"], Some("null"))?;
    assert_eq!(stdout, "", "stderr: {stderr:?}");
    assert_eq!(code, 0, "stderr: {stderr:?}");

    // `-n` (null-input) is a genuinely separate dispatch path -- it bypasses
    // stdin/JsonIndex construction entirely rather than merely feeding `.` a
    // literal `null`. The old (pre-#2111) version of this test reached
    // `modulemeta` this way; keep that path covered too, not just stdin-fed
    // evaluation above. `-n` has no stdin source, so jq's own location tag
    // is `<unknown>`, not `<stdin>`.
    let (stdout, stderr, code) = run_jq_full(&["-nc", "modulemeta"], None)?;
    assert_eq!(stdout, "");
    assert_eq!(
        stderr,
        "jq: error (at <unknown>): modulemeta input module name must be a string\n"
    );
    assert_eq!(code, 5);

    Ok(())
}

/// #2085: an unresolved call's reported line comes from a real call-site
/// position, not from a text search for the name's spelling.
///
/// Before this, `report_unresolved_calls` located each line by scanning
/// `filter` for the offending identifier, which matched *any* occurrence --
/// so an object key, a `$`-variable, a `.field` or a string literal spelling
/// the same name earlier in the source was indistinguishable from the real
/// call and got cited instead. `jq::collect_call_sites` now supplies the byte
/// offset of each genuine call, and only the generic call-parsing path
/// records into it, so those decoys are absent by construction.
///
/// Every expectation below is a live jq 1.7.1 capture. All twelve rows failed
/// before the fix; a matrix of 25 unresolved-call shapes went from 13/25 to
/// 25/25 matching jq, with none regressing.
#[test]
fn test_unresolved_call_line_comes_from_the_call_not_a_name_match_2085() -> Result<()> {
    // (filter, expected line number)
    let cases: &[(&str, usize)] = &[
        // The issue's own repro: an object key on line 1, the real call on 2.
        ("{nosuch: 1}\n| nosuch", 2),
        // A quoted key spells it too, and is equally not a call.
        ("{\"nosuch\": 1}\n| nosuch", 2),
        // A string literal that merely contains the name.
        ("\"nosuch\"\n| nosuch", 2),
        // A `$`-bound variable of the same spelling.
        (". as $nosuch\n| nosuch", 2),
        // A field access of the same spelling.
        (".nosuch\n| nosuch", 2),
        // The decoy nested one level down, still not a call.
        ("{a: {nosuch: 1}}\n| nosuch", 2),
        // A decoy key alongside other keys.
        ("{nosuch: 1, other: 2}\n| nosuch", 2),
        // With arguments, so the call is `nosuch/1` rather than `nosuch/0`.
        ("{nosuch: 1}\n| nosuch(1)", 2),
    ];

    for (filter, want_line) in cases {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some("null"))?;
        assert_eq!(
            code, 3,
            "`{filter}` -- stdout: {stdout:?} stderr: {stderr:?}"
        );
        assert_eq!(
            stdout, "",
            "`{filter}` -- a compile error produces no output"
        );
        assert!(
            stderr.contains(&format!("is not defined at <top-level>, line {want_line}:")),
            "`{filter}` should cite line {want_line} -- stderr: {stderr:?}"
        );
    }

    Ok(())
}

/// #2085 companion: the three properties the positional lookup must not lose.
///
/// **Repeat**: a repeated undefined name walks its own successive call sites
/// in source order rather than repeating the first.
///
/// **Arity**: an `f/1` diagnostic must not take a perfectly *resolvable*
/// `f/2` call site. The table records calls, not failures, and carries no
/// scope information, so arity is what separates same-name sites.
///
/// **Fallback**: a call with no entry in the table at all — one inlined from
/// an `include`d module, which has no occurrence in the filter text — still
/// drops the line marker rather than inventing a position. This needs a real
/// module: the first version of this test used a single-line filter, where
/// the table path and the fallback path both answer "line 1", so it could not
/// tell them apart and missed a regression that re-reported an already-used
/// position (#2085 review, finding 1).
///
/// Every expectation is a live jq 1.7.1 capture.
#[test]
fn test_unresolved_call_positional_lookup_keeps_repeat_arity_and_fallback_2085() -> Result<()> {
    // Repeat: two calls to the same undefined name on different lines.
    let (stdout, stderr, code) = run_jq_full(&["-c", "nosuch\n| nosuch"], Some("null"))?;
    assert_eq!(code, 3, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "");
    assert!(
        stderr.contains("line 1:") && stderr.contains("line 2:"),
        "each call should cite its own line -- stderr: {stderr:?}"
    );

    // Arity: the resolvable `f/2` on line 2 must not be cited for the
    // failing `f/1` on line 3.
    let (stdout, stderr, code) =
        run_jq_full(&["-c", "def f(a;b): a;\nf(1;2)\n| f(1)"], Some("null"))?;
    assert_eq!(code, 3, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "");
    assert!(
        stderr.contains("f/1 is not defined at <top-level>, line 3:"),
        "stderr: {stderr:?}"
    );

    // Wrong-arity call of a real `def`, single line: still located.
    let (stdout, stderr, code) = run_jq_full(
        &["-c", "def f(x): x; if false then f(1;2;3) else 1 end"],
        Some("null"),
    )?;
    assert_eq!(code, 3, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "");
    assert!(
        stderr.contains("f/3 is not defined at <top-level>, line 1:"),
        "stderr: {stderr:?}"
    );

    // Fallback: the module's own `nosuch` has no occurrence in the filter, so
    // it must be reported with no line marker while the filter's own `nosuch`
    // on line 3 keeps its position. jq reports only its own; what matters
    // here is that the second error does not repeat line 3's marker.
    let dir = tempfile::TempDir::new()?;
    std::fs::write(dir.path().join("m.jq"), "def helper: nosuch;\n")?;
    let lib = dir.path().to_string_lossy().to_string();
    let (stdout, stderr, code) = run_jq_full(
        &["-c", "-L", &lib, "include \"m\";\nhelper\n| nosuch"],
        Some("null"),
    )?;
    assert_eq!(code, 3, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "");
    assert_eq!(
        stderr.matches("line 3:").count(),
        1,
        "the module's own error must not re-use the filter call's line -- stderr: {stderr:?}"
    );
    assert!(
        stderr.contains("nosuch/0 is not defined at <top-level>\n"),
        "the module call should be reported with no line marker -- stderr: {stderr:?}"
    );

    Ok(())
}

/// An unresolvable call in a branch that is never taken still fails, and fails
/// before any input is read. jq: `f/3 is not defined`, exit 3.
#[test]
fn test_unresolved_call_in_unreached_branch_is_a_compile_error_1473() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(
        &["-c", "def f(x): x; if false then f(1;2;3) else 1 end"],
        Some("null"),
    )?;
    assert_eq!(code, 3, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "", "a compile error produces no output");
    assert!(
        stderr.contains("f/3 is not defined at <top-level>, line 1:"),
        "stderr: {stderr:?}"
    );
    Ok(())
}

/// `try`/`catch` and `?` cannot swallow it: compilation fails before
/// evaluation, and thus before `try`, ever begins.
#[test]
fn test_unresolved_call_is_not_catchable_1473() -> Result<()> {
    for filter in [
        r#"def f(x): x; try f(1;2) catch "caught""#,
        "def f(x): x; f(1;2)?",
        r#"try nosuchfn catch "caught""#,
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some("null"))?;
        assert_eq!(code, 3, "{filter}: stdout {stdout:?} stderr {stderr:?}");
        assert_eq!(stdout, "", "{filter}: a compile error produces no output");
        assert!(
            stderr.contains("is not defined"),
            "{filter}: stderr {stderr:?}"
        );
    }
    Ok(())
}

/// A forward reference across *different* names -- the pre-existing half of
/// #1473's severe case, which computed `42` where jq rejects the program.
#[test]
fn test_forward_reference_across_names_is_a_compile_error_1473() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["-c", "def f: g; def g: 42; f"], Some("null"))?;
    assert_eq!(code, 3, "stdout: {stdout:?} stderr: {stderr:?}");
    assert!(
        stderr.contains("g/0 is not defined at <top-level>, line 1:"),
        "stderr: {stderr:?}"
    );
    Ok(())
}

/// A nested `def` is scoped to its enclosing body and does not leak out of it
/// -- previously an exit-5 runtime error, now jq's exit-3 compile error.
#[test]
fn test_nested_def_does_not_leak_into_outer_scope_1473() -> Result<()> {
    let (_stdout, stderr, code) = run_jq_full(&["-c", "def f: def g: 1; g; g"], Some("null"))?;
    assert_eq!(code, 3, "stderr: {stderr:?}");
    assert!(stderr.contains("g/0 is not defined"), "stderr: {stderr:?}");
    Ok(())
}

/// A `def` parameter binds its bare name as an arity-0 function -- including
/// the `$`-prefixed form, which jq desugars to `def f(a): a as $a | …`, leaving
/// `a` callable. Calling one with arguments is `g/1 is not defined`, not a call
/// to anything in the enclosing scope.
#[test]
fn test_def_parameter_binds_arity_zero_only_1473() -> Result<()> {
    for (filter, want) in [("def f(g): g; f(1)", "1"), ("def f($a): a; f(1)", "1")] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some("null"))?;
        assert_eq!(code, 0, "{filter}: stderr {stderr:?}");
        assert_eq!(stdout.trim_end(), want, "{filter}");
    }

    let (_stdout, stderr, code) = run_jq_full(&["-c", "def f(g): g(1); f(.)"], Some("null"))?;
    assert_eq!(code, 3, "stderr: {stderr:?}");
    assert!(stderr.contains("g/1 is not defined"), "stderr: {stderr:?}");
    Ok(())
}

/// The resolution pass must not reject anything real jq accepts. Each of these
/// exercises a scope rule the pass has to get right, and each was run against
/// the pinned oracle for both its value and its exit code.
#[test]
fn test_resolution_pass_accepts_every_legal_scope_shape_1473() -> Result<()> {
    for (filter, want) in [
        // A def is visible to later siblings, and to itself.
        ("def f: 1; def g: f; g", "1"),
        ("def f(n): if n == 0 then 0 else f(n-1) end; f(3)", "0"),
        // Arity overloading, in both directions (#1376).
        (
            "def f(x): x + 1; def f(x; y): x + y; [f(1), f(2;3)]",
            "[2,5]",
        ),
        ("def f(x): x+1; def f(x;y): (f(x)) + y; f(2;3)", "6"),
        // A later same-arity def shadows, but the earlier one stays bound
        // inside anything defined before the redefinition.
        ("def f: 1; def g: f; def f: 2; g", "1"),
        // An inner def shadows an outer one for its own extent only.
        ("def f: 1; [f, (def f: 2; f), f]", "[1,2,1]"),
        // A def inside a builtin argument, reached through `builtin_kids`.
        ("def f: 3; [1,2] | map(f)", "[3,3]"),
        // A parameter shadowing the function's own name.
        ("def f(f): f; f(7)", "7"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some("null"))?;
        assert_eq!(code, 0, "{filter}: stderr {stderr:?}");
        assert_eq!(stdout.trim_end(), want, "{filter}: stderr {stderr:?}");
    }
    Ok(())
}

/// A plain syntax error is jq's compile error too: exit 3, and no second,
/// stray `Error: compile error` line from `anyhow`'s own reporting (#1473).
#[test]
fn test_syntax_error_exits_with_the_compile_error_code_1473() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["-c", "1 +"], Some("null"))?;
    assert_eq!(code, 3, "stdout: {stdout:?} stderr: {stderr:?}");
    assert!(stderr.contains("compile error"), "stderr: {stderr:?}");
    assert!(
        !stderr.contains("Error: compile error"),
        "the stray anyhow line is back: {stderr:?}"
    );
    Ok(())
}

/// An unresolvable `include`/`import` is jq's compile error too -- the third
/// kind, alongside a syntax error and an undefined function, and the last one
/// still routing through `anyhow` for exit 1 and a stray `Error: module error`
/// line (#1473). jq 1.7.1 exits 3.
#[test]
fn test_module_error_exits_with_the_compile_error_code_1473() -> Result<()> {
    let (stdout, stderr, code) =
        run_jq_full(&["-n", r#"include "nonexistent_module_xyz"; ."#], None)?;
    assert_eq!(code, 3, "stdout: {stdout:?} stderr: {stderr:?}");
    assert!(
        stderr.contains("module") && stderr.contains("not found"),
        "stderr: {stderr:?}"
    );
    assert!(
        !stderr.contains("Error: module error"),
        "the stray anyhow line is back: {stderr:?}"
    );
    Ok(())
}

/// The reported line is the one the offending identifier is written on, not
/// always line 1 -- `report_unresolved_calls` locates it in the filter source.
#[test]
fn test_unresolved_call_reports_its_own_source_line_1473() -> Result<()> {
    let (_stdout, stderr, code) = run_jq_full(&["-c", "def f: 1;\nf\n| nosuch"], Some("null"))?;
    assert_eq!(code, 3, "stderr: {stderr:?}");
    assert!(
        stderr.contains("nosuch/0 is not defined at <top-level>, line 3:"),
        "stderr: {stderr:?}"
    );
    assert!(
        stderr.contains("\n| nosuch"),
        "the offending line should be echoed: {stderr:?}"
    );
    Ok(())
}

/// The identifier search is word-bounded: an undefined `f` must not report the
/// line of some longer identifier that merely contains an `f`.
#[test]
fn test_unresolved_call_line_search_is_word_bounded_1473() -> Result<()> {
    let (_stdout, stderr, code) = run_jq_full(
        &["-c", "def first_thing: 1;\nfirst_thing\n| f"],
        Some("null"),
    )?;
    assert_eq!(code, 3, "stderr: {stderr:?}");
    assert!(
        stderr.contains("f/0 is not defined at <top-level>, line 3:"),
        "stderr: {stderr:?}"
    );
    Ok(())
}

/// #1473: an unresolvable call reached through an `include`d module has no
/// occurrence in the filter source, so `locate_identifier_from` finds nothing
/// and the diagnostic drops the line marker and source echo rather than
/// inventing a position.
///
/// jq names the module file and line here
/// (`... is not defined at /path/mymod.jq, line 1:` plus the module's own
/// source line); succinctly reports `at <top-level>` with no location. The
/// name, arity and exit code match; only the location does not, for the same
/// reason the in-filter case can cite the wrong occurrence — `Expr::FuncCall`
/// carries no source position, and modules would additionally need the
/// originating *file* threaded through `ModuleLoader`. Recorded in
/// docs/compliance/jq/limitations.md.
#[test]
fn test_unresolved_call_from_included_module_omits_the_location_1473() -> Result<()> {
    let temp_dir = tempfile::tempdir()?;
    std::fs::write(
        temp_dir.path().join("mymod.jq"),
        "def helper: nosuchfn_in_module;",
    )?;

    let (output, code) = spawn_with_signal_retry(
        || {
            let mut cmd = Command::new(succinctly_bin());
            cmd.args(["jq", "-n", "-L"])
                .arg(temp_dir.path())
                .arg(r#"include "mymod"; helper"#);
            cmd
        },
        None,
    )?;

    let stderr = String::from_utf8(output.stderr)?;
    assert_eq!(code, 3, "stderr: {stderr}");
    assert!(
        stderr.contains("nosuchfn_in_module/0 is not defined at <top-level>"),
        "stderr: {stderr}"
    );
    assert!(
        !stderr.contains(", line "),
        "no line should be claimed for a call with no in-filter occurrence: {stderr}"
    );
    assert!(stderr.contains("jq: 1 compile error"), "stderr: {stderr}");
    Ok(())
}

/// #2037: jq reports *every* unresolvable call in one compile pass, not just
/// the first -- `jq: N compile errors`. Captured live against the pinned
/// oracle (`/usr/bin/jq` 1.7.1); this filter and its exact three-error output
/// (including each line's trailing padding) are copied byte-for-byte from
/// that capture.
#[test]
fn test_all_unresolved_calls_are_reported_not_just_the_first_2037() -> Result<()> {
    let (stdout, stderr, code) =
        run_jq_full(&["-n", "def f: 1; f, nosuch, nosuch(1;2), nosuch"], None)?;
    assert_eq!(code, 3, "stderr: {stderr:?}");
    assert_eq!(stdout, "", "a compile error produces no output");
    assert_eq!(
        stderr,
        "jq: error: nosuch/0 is not defined at <top-level>, line 1:\n\
         def f: 1; f, nosuch, nosuch(1;2), nosuch             \n\
         jq: error: nosuch/2 is not defined at <top-level>, line 1:\n\
         def f: 1; f, nosuch, nosuch(1;2), nosuch                     \n\
         jq: error: nosuch/0 is not defined at <top-level>, line 1:\n\
         def f: 1; f, nosuch, nosuch(1;2), nosuch                                  \n\
         jq: 3 compile errors\n"
    );
    Ok(())
}

/// #2037: a repeated undefined name no longer always cites the first
/// occurrence's line -- each successive report resumes the source search
/// right after the previous match, so the second and third `nosuch1` in
/// `nosuch1 | nosuch2 | nosuch1` are told apart even though
/// `locate_identifier_from` still has no real AST position to work from.
/// Captured live against the pinned oracle, which reports the same three
/// errors in the same order.
#[test]
fn test_repeated_unresolved_name_cites_its_own_occurrence_2037() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["-n", "nosuch1 | nosuch2 | nosuch1"], None)?;
    assert_eq!(code, 3, "stderr: {stderr:?}");
    assert_eq!(stdout, "", "a compile error produces no output");
    assert_eq!(
        stderr,
        "jq: error: nosuch1/0 is not defined at <top-level>, line 1:\n\
         nosuch1 | nosuch2 | nosuch1\n\
         jq: error: nosuch2/0 is not defined at <top-level>, line 1:\n\
         nosuch1 | nosuch2 | nosuch1          \n\
         jq: error: nosuch1/0 is not defined at <top-level>, line 1:\n\
         nosuch1 | nosuch2 | nosuch1                    \n\
         jq: 3 compile errors\n"
    );
    Ok(())
}

/// #2037's original repro (from the issue that motivated this fix): both
/// `nosuch` calls fail to resolve, and jq reports both, one per line, in
/// source order -- not just the first, with `jq: 1 compile error` claiming a
/// count that doesn't match what was actually printed.
#[test]
fn test_original_2037_repro_reports_both_lines() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["-n", "def f: 1;\nnosuch\n| nosuch"], None)?;
    assert_eq!(code, 3, "stderr: {stderr:?}");
    assert_eq!(stdout, "", "a compile error produces no output");
    assert!(
        stderr.contains("nosuch/0 is not defined at <top-level>, line 2:"),
        "stderr: {stderr:?}"
    );
    assert!(
        stderr.contains("nosuch/0 is not defined at <top-level>, line 3:"),
        "stderr: {stderr:?}"
    );
    assert!(
        stderr.contains("jq: 2 compile errors"),
        "stderr: {stderr:?}"
    );
    Ok(())
}

/// #2037: an unresolved call's *arguments* are only checked once the call
/// itself resolves. Real jq's compiler binds argument closures to the
/// callee's parameter slots, which requires the callee to already be found;
/// an unresolved callee means there is nothing to bind the arguments to, so
/// jq never compiles them and reports only the callee. Verified live: this
/// filter is `nosucha/2 is not defined`, one error, in jq 1.7.1 -- not three.
///
/// Collecting every unresolvable call (rather than stopping at the first, as
/// this same PR does) made this easy to get wrong in the other direction: a
/// naive "keep checking everything" still descends into an unresolved call's
/// own arguments and reports errors real jq's compiler never reaches at all.
#[test]
fn test_unresolved_callee_args_are_not_independently_checked_2037() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["-n", "nosucha(nosuchb; nosuchc)"], None)?;
    assert_eq!(code, 3, "stderr: {stderr:?}");
    assert_eq!(stdout, "", "a compile error produces no output");
    assert_eq!(
        stderr,
        "jq: error: nosucha/2 is not defined at <top-level>, line 1:\n\
         nosucha(nosuchb; nosuchc)\n\
         jq: 1 compile error\n"
    );
    Ok(())
}

/// #2037, the flip side of the test above: once the callee itself *does*
/// resolve, its arguments are checked exactly as before -- an unresolved call
/// inside a resolved call's argument is still reported. Verified live against
/// jq 1.7.1 (`nosuch/0 is not defined`, one error).
#[test]
fn test_resolved_callee_still_checks_its_own_arguments_2037() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["-n", "def f(x): x; f(nosuch)"], None)?;
    assert_eq!(code, 3, "stderr: {stderr:?}");
    assert_eq!(stdout, "", "a compile error produces no output");
    assert_eq!(
        stderr,
        "jq: error: nosuch/0 is not defined at <top-level>, line 1:\n\
         def f(x): x; f(nosuch)               \n\
         jq: 1 compile error\n"
    );
    Ok(())
}

/// #1687 on the jq side, and #2066's own follow-up fixing the array-valued
/// half. Plain `succinctly jq` collapses duplicate keys on purpose (#1385,
/// matching real jq), so the observable surface here is `--preserve-input`,
/// the extension whose stated job is keeping the input's own formatting.
///
/// Every one of these now preserves, and this pins the full set:
///
/// - `min`/`max`/`min_by`/`max_by` answer a bare `GenericResult::OneCursor`,
///   which `generic_result_to_jq_values` forwards as `JqValue::Cursor`
///   without decoding -- so these preserve, joining `first(.[])`, which
///   always has.
/// - `sort`/`unique`/`reverse` and the `_by` forms answer a `LazySeq`.
///   `generic_result_to_jq_values`'s `LazySeq` arm used to call
///   `materialize_atomic()`, producing an `IndexMap`-backed `OwnedValue`
///   that collapsed a duplicate key inside a moved element -- #2066 routed
///   it through `drain_atomic()` instead, mapping each element's own cursor
///   (or already-owned `map`-computed value) to a `JqValue` individually, the
///   same way `ManyCursor`'s arm already does. `map(.)` is here as the
///   control proving the shared cause (`LazySeq`'s own output path) rather
///   than anything specific to #1687's sort/unique/reverse additions.
#[test]
fn test_preserve_input_sort_family_cursor_results_keep_duplicate_keys_1687() -> Result<()> {
    let input = r#"[{"a":1,"a":2},{"b":3}]"#;

    // Control: the whole document, and the long-standing `first` path.
    let (stdout, _, code) = run_jq_full(&["-c", "--preserve-input", "."], Some(input))?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "[{\"a\":1,\"a\":2},{\"b\":3}]\n");

    let (stdout, _, code) = run_jq_full(&["-c", "--preserve-input", "first(.[])"], Some(input))?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "{\"a\":1,\"a\":2}\n");

    // OneCursor results.
    for filter in ["min", "max_by(.a)"] {
        let (stdout, _, code) = run_jq_full(&["-c", "--preserve-input", filter], Some(input))?;
        assert_eq!(code, 0, "{filter}");
        assert_eq!(stdout, "{\"a\":1,\"a\":2}\n", "{filter}");
    }

    // LazySeq results that keep element order.
    for filter in ["map(.)", "sort", "unique"] {
        let (stdout, _, code) = run_jq_full(&["-c", "--preserve-input", filter], Some(input))?;
        assert_eq!(code, 0, "{filter}");
        assert_eq!(stdout, "[{\"a\":1,\"a\":2},{\"b\":3}]\n", "{filter}");
    }

    // LazySeq results that reorder elements -- the duplicate key must
    // survive the move, not just be preserved when it stays in place.
    // `.a` on the duplicate-key object reads its last value (2); `{"b":3}`'s
    // absent `.a` sorts as null, before any number, so it moves first.
    for filter in ["sort_by(.a)", "unique_by(.a)", "reverse"] {
        let (stdout, _, code) = run_jq_full(&["-c", "--preserve-input", filter], Some(input))?;
        assert_eq!(code, 0, "{filter}");
        assert_eq!(stdout, "[{\"b\":3},{\"a\":1,\"a\":2}]\n", "{filter}");
    }

    Ok(())
}

/// #1687 must not disturb plain jq mode, where collapsing duplicate keys is
/// the *correct* behaviour (#1385) -- every row below re-verified live
/// against the pinned jq 1.7.1.
#[test]
fn test_sort_family_still_collapses_in_plain_jq_mode_1687() -> Result<()> {
    let input = r#"[{"a":1,"a":2},{"b":3}]"#;
    for (filter, want) in [
        ("sort", "[{\"a\":2},{\"b\":3}]\n"),
        ("reverse", "[{\"b\":3},{\"a\":2}]\n"),
        ("unique", "[{\"a\":2},{\"b\":3}]\n"),
        ("min", "{\"a\":2}\n"),
        ("max", "{\"b\":3}\n"),
    ] {
        let (stdout, _, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 0, "{filter}");
        assert_eq!(stdout, want, "{filter}");
    }
    Ok(())
}

/// #1687: the error and control paths through the new native arms, which the
/// happy-path tests above never reach — `sort_key_generic`'s `Err`, the
/// `sort_family_control` conversion, `fanout_arg_generic`'s `body`-escape and
/// argument-escape arms, and `reduce`'s input-control propagation.
///
/// Every row is real jq 1.7.1's own output and exit code, captured live: these
/// are all shapes with a jq oracle, so there is no reason to pin anything
/// weaker than parity.
#[test]
fn test_1687_native_arms_propagate_errors_like_jq() -> Result<()> {
    let input = "[10,20,30,40]";

    // An error raised while computing a sort key aborts the whole builtin with
    // no partial output — the atomicity `eval::builtin_min_by` and friends
    // already had, now also on the cursor-native path.
    for filter in [
        "sort_by(error(\"x\"))",
        "min_by(error(\"x\"))",
        "unique_by(error(\"x\"))",
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 5, "{filter}: stderr {stderr}");
        assert_eq!(stdout, "", "{filter}: no partial output");
        assert!(stderr.contains(": x"), "{filter}: stderr {stderr}");
    }

    // An error inside `limit`'s `n` generator, and inside its body, both reach
    // the caller through `fanout_arg_generic` rather than being swallowed.
    for filter in ["[limit((1,error(\"x\")); .[])]", "[limit(2; error(\"x\"))]"] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 5, "{filter}: stderr {stderr}");
        assert_eq!(stdout, "", "{filter}");
        assert!(stderr.contains(": x"), "{filter}: stderr {stderr}");
    }

    // `reduce` is single-shot, so a control anywhere in its input stream
    // discards the prefix and propagates alone — and `?` suppresses an
    // ordinary error there, matching `eval::eval_reduce`'s `suppress_or_raise`.
    let (stdout, stderr, code) = run_jq_full(
        &["-c", "reduce (1,error(\"x\")) as $x (0; .+1)"],
        Some(input),
    )?;
    assert_eq!(code, 5, "stderr {stderr}");
    assert_eq!(stdout, "");

    let (stdout, _, code) = run_jq_full(
        &["-c", "reduce (1,error(\"x\")) as $x (0; .+1)?"],
        Some(input),
    )?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "");

    // An empty array answers `null` for all four min/max spellings, before any
    // key is computed.
    for filter in ["min", "max", "min_by(.)", "max_by(.)"] {
        let (stdout, _, code) = run_jq_full(&["-c", filter], Some("[]"))?;
        assert_eq!(code, 0, "{filter}");
        assert_eq!(stdout, "null\n", "{filter}");
    }

    Ok(())
}

/// #1687: `limit`/`nth` must still hand a live `input`/`inputs` queue to
/// `eval.rs` untouched — the #1309 guard is the one deferral
/// `fanout_arg_generic` did *not* replace, because probing the queue here
/// would drain it as a side effect before the fallback ever ran.
///
/// This covers both bridges: `bridge_to_full_evaluator_flow` (reached from
/// `each_limit_generic`, i.e. `limit` under a demand-driven consumer) and
/// `Expr::NthExpr`'s own. Both rows are jq 1.7.1's own output.
#[test]
fn test_1687_limit_and_nth_still_bridge_a_live_input_queue() -> Result<()> {
    let inputs = "1\n2\n3\n4\n";

    // `first(...)` routes through `each_limit_generic`, the sink-side arm.
    let (stdout, code) = run_jq_stdin("first(limit(inputs; 10,20,30))", inputs, &[])?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "10\n");

    // Bare `limit`: `inputs` yields 2,3,4 against the first document, so the
    // body runs once per value of `n`.
    let (stdout, code) = run_jq_stdin("[limit(inputs; 10,20)]", inputs, &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "[10,20,10,20,10,20]\n");

    let (stdout, code) = run_jq_stdin("nth(inputs; 10,20,30)", inputs, &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "30\n");

    Ok(())
}

/// #1687 regression guard for #1755's rule. The `_by` spellings compute a key
/// per element and never need the element's own value, so #1687's first cut
/// skipped decoding it — which silently dropped `eval.rs`'s check that an
/// undecodable element must *raise* rather than sort in as `""`.
///
/// The gap only shows when the bad element never reaches the output, so
/// nothing else surfaces it. succinctly's semi-index accepts these documents
/// where real jq rejects them at parse time, so there is no jq oracle here;
/// the contract being pinned is #1755's own, and `main`'s behaviour.
#[test]
fn test_by_spellings_still_raise_on_an_undecodable_element_1687() -> Result<()> {
    // A lone surrogate, a bad \u escape, and an unknown escape: all three are
    // spans the semi-index accepts and the decoder rejects.
    for bad in [r"\ud800", r"\uZZZZ", r"\x"] {
        let input = format!(r#"[{{"a":2,"s":"{bad}"}},{{"a":1,"s":"ok"}}]"#);

        // `length` never emits the offending element, so only the element
        // decode-check can catch it.
        for filter in [
            "sort_by(.a) | length",
            "unique_by(.a) | length",
            "min_by(.a).a",
            "max_by(.a).a",
        ] {
            let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(&input))?;
            assert_eq!(
                code, 5,
                "{filter} on {bad}: stdout {stdout:?} stderr {stderr}"
            );
            assert_eq!(stdout, "", "{filter} on {bad}");
        }

        // The bare spellings decode the element as their comparison key, so
        // they were never affected — pinned as the control.
        let (stdout, _, code) = run_jq_full(&["-c", "sort | length"], Some(&input))?;
        assert_eq!(code, 5, "sort on {bad}");
        assert_eq!(stdout, "", "sort on {bad}");
    }
    Ok(())
}

/// #1687: the `limit` sink arm's input-queue bridge — the one deferral
/// `fanout_arg_each_generic` does *not* replace, because probing a live
/// `input`/`inputs` queue would drain it as a side effect before the fallback
/// ran.
///
/// Reaching it needs a shape that skips the *top-level* input-queue bridge in
/// `eval_with_cursor_using`, which `takes_input_queue_bridge` declines for a
/// query that also uses a cursor-metadata builtin (#1504). `limit(inputs; line)`
/// is such a shape; `first(limit(inputs; ...))` is not, because
/// `eval_first_or_last_generic`'s own guard fires first. That distinction is
/// why this test exists separately from
/// `test_1687_limit_and_nth_still_bridge_a_live_input_queue`.
///
/// `line` answers 0 rather than a real line number here: the bridge
/// materializes the input and re-indexes it, so position metadata is gone.
/// That is a pre-existing consequence of the guard — #1687 did not change its
/// condition, only removed a separate bare-`Comma` disjunct beside it — and it
/// sits awkwardly with #1504's own purpose, which was to keep `line` working
/// alongside `inputs`. Pinned as the current behaviour, not endorsed.
#[test]
fn test_limit_sink_arm_bridges_a_live_input_queue_1687() -> Result<()> {
    let inputs = "1\n2\n3\n4\n";

    let (stdout, code) = run_jq_stdin("limit(inputs; line)", inputs, &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(
        stdout, "0\n0\n0\n",
        "known gap: the bridge loses position metadata"
    );

    // Same arm, reached through a `Comma` sibling rather than as the whole
    // program, so the bridge's `drain_result_generic` half runs too.
    let (stdout, code) = run_jq_stdin("(limit(inputs; line), 1)", inputs, &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "0\n0\n0\n1\n");

    Ok(())
}

/// #1687: `sort_family_control`'s non-`Error` half. A `halt_error` inside a
/// sort key aborts the whole builtin with jq's own exit code and stderr —
/// byte-identical to jq 1.7.1, which writes `10\n` and exits 5 (compared with
/// `od -c`, since `halt_error`'s whole point is raw stderr).
///
/// The `Break` arm beside it is not reachable from any query this CLI can
/// parse: `break $out` needs an enclosing `label`, `Expr::Label` has no native
/// `eval_single` arm, so a label above `sort_by` routes the whole expression
/// through the wildcard bridge before this arm runs. Same "unreachable but
/// exhaustive" shape `Expr::Array`'s own `Break` arm documents (#1064).
#[test]
fn test_sort_family_propagates_halt_like_jq_1687() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["-c", "sort_by(halt_error)"], Some("[10,20,30]"))?;
    assert_eq!(code, 5, "stderr {stderr}");
    assert_eq!(stdout, "");
    assert_eq!(stderr, "10\n");
    Ok(())
}

/// #2057: a child that exits *without reading stdin* must not fail the test
/// with `Broken pipe`.
///
/// Every filter here fails to compile, so `succinctly jq` reports the error
/// and exits 3 having never touched stdin. Writing to that closed pipe is
/// then the normal outcome, not a symptom of load -- which is why the four
/// recorded #2057 failures were all compile-error tests, and why re-running
/// the job did not clear them.
///
/// In CI the race is only *biased*, not decided: the few-byte payloads those
/// tests use land in the pipe buffer and succeed whenever the parent reaches
/// its write first. This test removes the bias instead of relying on it. The
/// payload spans many `write` calls, so the child -- which exits in
/// milliseconds -- is certain to have exited before the last of them,
/// whichever side started first. That is the narrower case where payload
/// size is the discriminator at all; for an already-exited child `BrokenPipe`
/// does not depend on buffer capacity.
///
/// Without the `BrokenPipe` arm in `write_stdin_then_wait` this therefore
/// fails every run rather than occasionally, which is what makes it a usable
/// pin for a bug whose own signature in CI is intermittent.
#[test]
fn test_compile_error_with_unread_stdin_is_not_a_broken_pipe_2057() -> Result<()> {
    let payload = "0\n".repeat(2 * 1024 * 1024);
    for filter in ["nosuchfn", "def f(x): x; f(1;2)"] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(&payload))?;
        assert_eq!(code, 3, "{filter}: stderr {stderr:?}");
        assert_eq!(stdout, "", "{filter}: a compile error produces no output");
        assert!(
            stderr.contains("is not defined"),
            "{filter}: stderr {stderr:?}"
        );
    }
    Ok(())
}

/// #1409: an isolated sub-expression's outputs must continue the rest of
/// the pipe from *their own* path, not the ambient pre-isolation one.
///
/// Several arms of the deleted eager path-context evaluator evaluate a
/// sub-expression with an empty `rest` -- because the construct scopes
/// something `rest` must stay outside of -- and only afterwards continue the
/// real `rest`. `Field`/`Index`/`Iterate` build an updated path only when
/// they have a non-empty `rest` to recurse into, so isolation used to hand
/// the continuation bare values and a stale path: every wrapper below
/// reported `"a"` for all three elements instead of `0`, `1`, `2`.
///
/// The oracle is the un-wrapped pipeline, and `path()` agrees with real jq
/// 1.7.1 on each of these shapes (`jq 'path(.a | (try .[] catch empty))'`
/// => `["a",0]`, `["a",1]`, `["a",2]`), so wrapper and un-wrapped form
/// disagreeing was unambiguously the bug rather than an open question.
#[test]
fn test_isolated_subexpr_threads_per_output_path_1409() -> Result<()> {
    let input = r#"{"a":[1,2,3]}"#;

    // The un-wrapped pipeline every wrapper below has to agree with.
    let (baseline, _, code) = run_jq_full(&["-c", ".a | .[] | key"], Some(input))?;
    assert_eq!(code, 0);
    assert_eq!(baseline, "0\n1\n2\n");

    for filter in [
        ".a | (try .[] catch empty) | key",
        ".a | (try .[]) | key",
        ".a | (label $out | .[]) | key",
        ".a | (if true then .[] else empty end) | key",
        ".a | (def f: .[]; f) | key",
        ".a | limit(3; .[]) | key",
        // `As` reaches its own path-context arm only when `expr` or `body`
        // needs path context on its own; `select(key >= 0)` is what routes
        // this shape there.
        ".a | (. as $x | (.[] | select(key >= 0))) | key",
        ".a | (. as [$x] | (.[] | select(key >= 0))) | key",
        // The bare spellings were a routing gap until #2072: widening the
        // guard to consult `rest` reached them, but regressed
        // `.x as $v | $v | file_index`, because `substitute_bound_var`
        // re-materialised the bound value as a literal and erased the node
        // identity real yq keeps. A binding now carries that identity
        // (`BoundVar::origin`), so both spellings thread per-output paths
        // and `file_index` still answers. `yq '.a | (. as $x | .[]) | key'`
        // on `a: [1,2,3]` is `0 1 2` on yq v4.53.3, captured 2026-09-08.
        ".a | (. as $x | .[]) | key",
        ".a | (. as [$x] | .[]) | key",
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 0, "{filter}: {stderr}");
        assert_eq!(stdout, baseline, "{filter} disagrees with `.a | .[] | key`");
    }

    // The same threading, observed through `path` rather than `key`, so a
    // regression that produced the right *last* component but the wrong
    // prefix would still be caught.
    let (stdout, _, code) = run_jq_full(&["-c", ".a | (try .[] catch empty) | path"], Some(input))?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "[\"a\",0]\n[\"a\",1]\n[\"a\",2]\n");

    // A non-fan-out navigational body threads its single component too.
    let (stdout, _, code) = run_jq_full(
        &["-c", ".a | (try .b catch empty) | path"],
        Some(r#"{"a":{"b":{"c":1}}}"#),
    )?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "[\"a\",\"b\"]\n");

    Ok(())
}

/// #1409: the probe that carries each output's path sits *inside* the
/// isolated pipe, so it must not widen what the construct scopes.
///
/// This is the property that ruled out `Comma`'s own fix (#1509) for these
/// arms: rewriting `try f catch c | rest` as `try (f | rest) catch (c |
/// rest)` would let an error raised by `rest` be caught by the `try`'s own
/// handler, which real jq never does (`jq '.a | (try .[] catch "CAUGHT") |
/// (., error("boom"))'` prints the first element, then fails with `boom`).
#[test]
fn test_isolated_subexpr_probe_does_not_widen_catch_scope_1409() -> Result<()> {
    let input = r#"{"a":[1,2,3]}"#;

    // `error("boom")` is raised by `rest`, outside the `try` -- the handler
    // must not see it, so this fails rather than printing `"CAUGHT"`.
    let (stdout, stderr, code) = run_jq_full(
        &[
            "-c",
            r#".a | (try .[] catch "CAUGHT") | (key, error("boom"))"#,
        ],
        Some(input),
    )?;
    assert_eq!(code, 5, "rest's own error must escape the try: {stderr}");
    assert_eq!(stdout, "0\n");
    assert!(stderr.contains("boom"), "stderr: {stderr}");
    assert!(!stdout.contains("CAUGHT"), "stdout: {stdout}");

    // A `label`'s break scope is likewise unwidened: the `break` below
    // belongs to the *inner* label, and the outer one still sees nothing.
    let (stdout, _, code) = run_jq_full(&["-c", ".a | (label $in | .[]) | key"], Some(input))?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "0\n1\n2\n");

    Ok(())
}

/// #1409: a `catch` handler's outputs stay on the ambient path rather than
/// being probed.
///
/// The handler runs against the error *payload*, which is not a node of the
/// document, so probing it would name a path that does not exist: `try
/// error({"b":9}) catch .b` would claim `["a","b"]` even though nothing
/// lives there. Real jq refuses the question outright (`path(.a | (try
/// error({"b":9}) catch .b))` => `Invalid path expression`), so there is no
/// oracle demanding a deeper answer -- and inventing one is strictly worse
/// than the ambient path this evaluator already reported.
#[test]
fn test_catch_handler_outputs_keep_ambient_path_1409() -> Result<()> {
    let (stdout, _, code) = run_jq_full(
        &["-c", r#".a | (try error({"b":9}) catch .b) | path"#],
        Some(r#"{"a":{"b":1}}"#),
    )?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "[\"a\"]\n");

    // A prefix produced before the error keeps its own probed path, while
    // the handler's output falls back to the ambient one -- both encodings
    // coexisting in a single result.
    let (stdout, _, code) = run_jq_full(
        &[
            "-c",
            r#".a | (try (.[], error("x")) catch "C") | [path, .]"#,
        ],
        Some(r#"{"a":[1,2,3]}"#),
    )?;
    assert_eq!(code, 0);
    assert_eq!(
        stdout,
        "[[\"a\",0],1]\n[[\"a\",1],2]\n[[\"a\",2],3]\n[[\"a\"],\"C\"]\n"
    );

    Ok(())
}

/// #2061: a parenthesised pipe, comma or `?` used as a *pipe head* inside
/// `path()` -- `path(((.a|.b)|.c))` and friends.
///
/// `path_expr_is_cursor_navigable` accepts all three, but `path_step_generic`
/// had arms for none of them, so each one reached its `unreachable!` and
/// aborted the process with exit 101. That is a live, CLI-reachable panic,
/// which is why it is asserted here at the CLI level rather than as a unit
/// test: a panic in the library is a failed assertion, a panic in the binary
/// is a crash.
///
/// Every expectation is jq 1.7.1's own output, captured live.
#[test]
fn test_path_cursor_walk_accepts_composite_pipe_heads_2061() -> Result<()> {
    for (filter, input, want) in [
        // A parenthesised pipe as the head of an outer pipe.
        (
            "path(((.a|.b)|.c))",
            "{\"a\":{\"b\":{\"c\":1}}}",
            "[\"a\",\"b\",\"c\"]\n",
        ),
        ("path((.a|.b)|.c)", "null", "[\"a\",\"b\",\"c\"]\n"),
        (
            "[path((.a|.b)|.[])]",
            "{\"a\":{\"b\":[10,20]}}",
            "[[\"a\",\"b\",0],[\"a\",\"b\",1]]\n",
        ),
        // A parenthesised comma as the head: both branches continue.
        (
            "[path((.a,.b)|.c)]",
            "{\"a\":{\"c\":1},\"b\":{\"c\":2}}",
            "[[\"a\",\"c\"],[\"b\",\"c\"]]\n",
        ),
        (
            "[path((.a, .a) | .b)]",
            "{\"a\":{\"b\":{}}}",
            "[[\"a\",\"b\"],[\"a\",\"b\"]]\n",
        ),
        // A parenthesised `?` as the head.
        ("path((.a?)|.c)", "{\"a\":{\"c\":1}}", "[\"a\",\"c\"]\n"),
        // Nesting to three levels, and a comma whose branches disagree in
        // length -- both were reachable through the same missing arms.
        ("path(((.a)))", "{\"a\":1}", "[\"a\"]\n"),
        (
            "[path((.a|.b), (.a))]",
            "{\"a\":{\"b\":1}}",
            "[[\"a\",\"b\"],[\"a\"]]\n",
        ),
    ] {
        let (stdout, code) = run_jq_stdin(filter, input, &["-c"])?;
        assert_eq!(code, 0, "`{filter}` on `{input}`");
        assert_eq!(stdout, want, "`{filter}` on `{input}`");
    }
    Ok(())
}

/// #2061: `?` inside `path()` swallows the error but not the outputs the
/// branch had already produced before it.
///
/// The cursor walk discarded the whole branch, so `[1] | path((.[0],.a)?)`
/// emitted nothing where jq 1.7.1 emits `[0]`. The regression was invisible
/// against `path(.a?)`, whose error comes before anything is produced, and
/// the non-navigable fallback for the very same shape
/// (`path((.[0],.a[0:1])?)`, which defers to `builtin_path_on_owned`) had it
/// right all along -- so the two resolvers disagreed with each other.
#[test]
fn test_path_cursor_walk_optional_keeps_earlier_outputs_2061() -> Result<()> {
    // The regression case, and the same shape routed through the
    // materializing resolver by making one branch non-navigable. Both must
    // agree, and both must equal jq.
    for filter in ["path((.[0],.a)?)", "path((.[0],.a[0:1])?)"] {
        let (stdout, code) = run_jq_stdin(filter, "[1]", &["-c"])?;
        assert_eq!(code, 0, "`{filter}`");
        assert_eq!(stdout, "[0]\n", "`{filter}`");
    }

    // `?` covers only its own parens: the position it produced is still fed
    // to the following stage, whose own error is *not* suppressed.
    let (stdout, code) = run_jq_stdin("path((.[0],.a)? | .z)", "[1]", &["-c"])?;
    assert_eq!(code, 5);
    assert_eq!(stdout, "");

    // Unchanged: an error before any output still yields nothing at all.
    let (stdout, code) = run_jq_stdin("[path(.a?)]", "[1]", &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "[]\n");

    Ok(())
}

/// #2061: every arm of the cursor-native `path()` walk, exercised through the
/// CLI so it reaches `eval_generic.rs`'s `Builtin::Path` rather than
/// `eval.rs`'s library-only entry point.
///
/// Every expectation is jq 1.7.1's own output, re-verified live: this arm
/// exists to be faster, not to behave differently, so parity is the whole
/// specification.
#[test]
fn test_path_cursor_native_navigational_shapes_2061() -> Result<()> {
    for (filter, input, want) in [
        // Identity, field, nested field.
        ("path(.)", "{\"a\":1}", "[]\n"),
        ("path(.a)", "{\"a\":1}", "[\"a\"]\n"),
        ("path(.a.b)", "{\"a\":{\"b\":1}}", "[\"a\",\"b\"]\n"),
        // A path need not exist: jq yields it and keeps navigating through
        // the absent node as if it were null.
        ("path(.a)", "{}", "[\"a\"]\n"),
        ("path(.a.b)", "{}", "[\"a\",\"b\"]\n"),
        ("path(.a.b)", "null", "[\"a\",\"b\"]\n"),
        // Index, including the float spelling (#1088) and a negative index,
        // neither of which needs the array's length.
        ("path(.[0])", "[7,8]", "[0]\n"),
        ("path(.[0])", "[]", "[0]\n"),
        ("path(.[2.0])", "[1,2,3]", "[2.0]\n"),
        ("path(.[-1])", "[1,2,3]", "[-1]\n"),
        // Iterate over both container kinds.
        ("[path(.[])]", "{\"a\":1,\"b\":2}", "[[\"a\"],[\"b\"]]\n"),
        ("[path(.[])]", "[7,8]", "[[0],[1]]\n"),
        ("[path(.[])]", "{}", "[]\n"),
        // Comma, pipe through a fan-out, and `?`.
        ("[path(.a,.b)]", "{\"a\":1,\"b\":2}", "[[\"a\"],[\"b\"]]\n"),
        (
            "[path(.[]|.x)]",
            "[{\"x\":1},{\"x\":2}]",
            "[[0,\"x\"],[1,\"x\"]]\n",
        ),
        ("[path(.a?)]", "[1,2]", "[]\n"),
        ("[path((.a)?)]", "[1,2]", "[]\n"),
        // A non-navigable body still works -- it defers to the materializing
        // resolver rather than being rejected.
        ("[path(.[]|select(.>1))]", "[1,2,3]", "[[1],[2]]\n"),
        ("path(.[\"a\"])", "{\"a\":1}", "[\"a\"]\n"),
    ] {
        let (stdout, code) = run_jq_stdin(filter, input, &["-c"])?;
        assert_eq!(code, 0, "`{filter}` on `{input}`");
        assert_eq!(stdout, want, "`{filter}` on `{input}`");
    }
    Ok(())
}

/// #2061: the error arms of the same walk. Each message is jq 1.7.1's own,
/// and comes from the same `EvalError` constructor the materializing resolver
/// uses, so the two cannot drift.
#[test]
fn test_path_cursor_native_type_errors_2061() -> Result<()> {
    for (filter, input, want) in [
        ("path(.a)", "[1,2]", "Cannot index array with string \"a\""),
        ("path(.a)", "5", "Cannot index number with string \"a\""),
        ("path(.a)", "\"s\"", "Cannot index string with string \"a\""),
        ("path(.a)", "true", "Cannot index boolean with string \"a\""),
        (
            "path(.a.b)",
            "{\"a\":1}",
            "Cannot index number with string \"b\"",
        ),
        ("path(.[0])", "{}", "Cannot index object with number"),
        ("path(.[0])", "5", "Cannot index number with number"),
        ("path(.[])", "null", "Cannot iterate over null (null)"),
        ("path(.[])", "5", "Cannot iterate over number (5)"),
    ] {
        let (stdout, stderr, code) = run_jq_stdin_streams(filter, input, &["-c"])?;
        assert_eq!(code, 5, "`{filter}` on `{input}`: stdout {stdout:?}");
        assert!(
            stderr.contains(want),
            "`{filter}` on `{input}`: wanted {want:?}, got {stderr:?}"
        );
    }
    Ok(())
}

/// #2061: a partial result produced before a later sibling errors must still
/// be emitted -- jq's generator never un-emits an output it already produced.
///
/// Discarding it is the bug the evaluator-parity and golden suites caught in
/// this change's first cut, so it is pinned directly rather than left to them.
#[test]
fn test_path_cursor_native_keeps_output_before_a_later_error_2061() -> Result<()> {
    let (stdout, stderr, code) =
        run_jq_stdin_streams("path(.a.b, .c.d)", "{\"a\":{\"b\":1},\"c\":1}", &["-c"])?;
    assert_eq!(code, 5, "stderr {stderr}");
    assert_eq!(stdout, "[\"a\",\"b\"]\n");
    assert!(
        stderr.contains("Cannot index number with string \"d\""),
        "{stderr}"
    );
    Ok(())
}

/// #2061: the validity walk's lazy #1642 collision map, whose fallback branch
/// only runs once an undecodable *key* actually appears.
///
/// All four layouts matter and are checked separately, because the branch
/// re-walks the object's *preceding* keys to seed the map: a fallback key
/// first exercises the empty-prefix case, a fallback key after a clean one
/// exercises the re-walk itself, two fallback keys exercise the map holding
/// more than one, and a fallback key whose display form collides with a real
/// key exercises the guard actually raising. Byte-identical to the eager map
/// on all four, verified against `main`.
///
/// **The key must be undecodable, not merely lossy.** An earlier version of
/// this test used raw invalid UTF-8 (`"\xff\xfe"`) and reached none of this:
/// those bytes decode lossily, `string_decode_error()` answers `None`, and
/// `key_display_string_kind` therefore reports them as ordinary keys, so the
/// eager path never engages. Only the `\uXXXX` family produces a genuine
/// decode failure. An undecodable *value* does not reach it either -- that is
/// the walk's separate scalar arm. Confirmed by planting a probe in the
/// branch and checking which documents actually execute it, rather than
/// assuming from the test passing.
#[test]
fn test_path_validity_walk_lazy_collision_map_2061() -> Result<()> {
    // Fallback key first: the re-walk runs with an empty prefix.
    let (stdout, code) = run_jq_stdin("[path(.[])]", r#"{"\ud800":1,"a":2}"#, &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "[[\"\\\\ud800\"],[\"a\"]]\n");

    // Fallback key after a clean one: the re-walk has a prefix to seed from.
    let (stdout, code) = run_jq_stdin("[path(.[])]", r#"{"a":1,"\ud800":2}"#, &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "[[\"a\"],[\"\\\\ud800\"]]\n");

    // Two distinct fallback keys, and a clean key on either side of one.
    let (stdout, code) = run_jq_stdin("[path(.[])]", r#"{"\ud800":1,"\ud801":2}"#, &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "[[\"\\\\ud800\"],[\"\\\\ud801\"]]\n");

    let (stdout, code) = run_jq_stdin("[path(.[])]", r#"{"a":1,"\ud800":2,"b":3}"#, &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "[[\"a\"],[\"\\\\ud800\"],[\"b\"]]\n");

    // A navigation that never visits the undecodable key answers normally.
    // (Before #2168 this row passed for the opposite reason -- the walk
    // validated the whole document and this particular key, being merely
    // undecodable rather than *colliding*, was preserved rather than raised.
    // Now nothing outside the navigated path is inspected at all.)
    let (stdout, code) = run_jq_stdin("path(.a)", r#"{"\ud800":1,"a":2}"#, &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(stdout, "[\"a\"]\n");

    Ok(())
}

/// #2168: the #1642 colliding-display-key raise was part of the same
/// whole-document gate, so it too now fires only where the query touches the
/// keys involved -- `path(.a)` answers where it used to raise `is ambiguous`.
///
/// This reverses `test_path_validity_walk_still_raises_on_a_colliding_key_2061`.
/// The collision is a property of *rendering two keys into one display map*,
/// which a navigation to a third key never does; `keys_unsorted` on these same
/// documents has always answered rather than raised, so the consistency rule
/// #2168 settled makes `path`/`key` follow it.
///
/// The length agreement below is the point: whatever `keys_unsorted` is
/// willing to list, `[path(.[])]` now names, element for element. (Their
/// *spellings* still differ -- `keys_unsorted` echoes the raw source bytes,
/// `path` reports the fallback display form -- which is #1385/#1642's own
/// pre-existing divergence, pinned next door by
/// `test_path_validity_walk_lazy_collision_map_2061`, not something this
/// change moved.)
///
/// **Diverges from jq, deliberately:** real jq 1.7.1 rejects all three
/// documents at parse time, so `path(.a)` here used to match its outcome and
/// no longer does. `keys_unsorted` on the same documents has always answered,
/// which is the consistency being bought; see
/// `docs/compliance/jq/limitations.md`. Checked in all three positions
/// relative to the clean key, since the lazy map only seeds itself from the
/// prefix once a fallback key appears.
#[test]
fn test_path_answers_past_a_colliding_key_2168() -> Result<()> {
    for doc in [
        r#"{"\\ud800":1,"\ud800":2}"#,
        r#"{"\ud800":1,"\ud800":2}"#,
        r#"{"a":1,"\ud800":2,"\ud800":3}"#,
    ] {
        let (stdout, stderr, code) = run_jq_stdin_streams("path(.a)", doc, &["-c"])?;
        assert_eq!(code, 0, "{doc}: stdout {stdout:?} stderr {stderr:?}");
        assert_eq!(stdout, "[\"a\"]\n", "{doc}");

        let (paths, _, code) = run_jq_stdin_streams("[path(.[])] | length", doc, &["-c"])?;
        assert_eq!(code, 0, "{doc}");
        let (keys, _, code) = run_jq_stdin_streams("keys_unsorted | length", doc, &["-c"])?;
        assert_eq!(code, 0, "{doc}");
        assert_eq!(
            paths, keys,
            "{doc}: [path(.[])] must name exactly the members keys_unsorted lists"
        );
    }

    // The materializing routes are unchanged: rendering *is* the collision,
    // so `-S` (sort keys, which must hold both in one map) still raises.
    let (stdout, stderr, code) =
        run_jq_stdin_streams(".", r#"{"\ud800":1,"\ud800":2}"#, &["-S", "-c"])?;
    assert_eq!(code, 5, "stdout {stdout:?}");
    assert!(stderr.contains("is ambiguous"), "{stderr}");

    Ok(())
}

/// #2168 coverage: the validation gate's own **lazy collision map** still
/// seeds itself from the prefix, on the consumers that kept the gate.
///
/// `push_generic_document_validation_error` builds the #1642 display-key map
/// only from the point a decode-failure ("fallback") key first appears
/// (#2061), then re-walks the object's earlier keys to seed it. Until #2168,
/// `path()` was the query that reached that seeding re-walk; `path()` left
/// the gate with this issue (see
/// `test_path_answers_past_a_colliding_key_2168` next door, which is the
/// same three documents on the other side of the line), and the consumers
/// that kept it are what still reach it. #2692 shrank that set further --
/// `select` left too, on the argument that a truthiness test does not read
/// what it tests -- leaving the `sort_by`/`unique_by`/`min_by`/`max_by`
/// family as the gate's only remaining caller and so its only probe here.
///
/// The fallback key must sit at index >= 1 for the re-walk to run at all --
/// at index 0 there is no prefix to seed from, which is the shape the sibling
/// test's `-S` row already covers. Getting the seeding wrong turns one of
/// these into a silent success, which is what #2061 wrote the
/// three-position corpus for in the first place.
///
/// **Diverges from jq, deliberately** in the same direction and for the same
/// reason as every other row on these documents: real jq 1.7.1 rejects all
/// three at parse time, filter irrelevant.
#[test]
fn test_validation_gate_seeds_the_collision_map_prefix_2168() -> Result<()> {
    // A clean key first, then the colliding pair: the map is seeded from
    // index 0 only once the fallback at index 1 is met.
    for inner in [
        r#"{"a":1,"\ud800":2,"\ud800":3}"#,
        r#"{"a":1,"\\ud800":2,"\ud800":3}"#,
    ] {
        let doc = format!(r#"{{"c":{inner},"t":5}}"#);

        // `select` used to reach the gate here through its `OneCursor`
        // truthiness arm; since #2692 it does not reach the gate at all, and
        // answers instead -- pinned as such below.
        //
        // `sort_by` reaches it through the `_by` forms' own call, on an
        // element it only reorders and never materializes (#1755) -- a
        // second call site for one walk. The array wrapper has to be the
        // *document*, not a `[...]` construction: collecting into one would
        // materialize the element here and raise from there instead, which
        // would pin nothing about this gate.
        let array_doc = format!("[{inner}]");
        let (stdout, stderr, code) =
            run_jq_stdin_streams("sort_by(.a) | length", &array_doc, &["-c"])?;
        assert_eq!(code, 5, "sort_by on {array_doc}: stdout {stdout:?}");
        assert!(stderr.contains("is ambiguous"), "sort_by: {stderr}");

        // The control, and the point of the whole #2168 split: the same
        // document, the same colliding pair, on a query that only names
        // positions -- it answers. `select(.c) | .t` sits beside it since
        // #2692, testing a position rather than naming one, and answering
        // for the same reason: neither resolves the colliding keys.
        for filter in ["path(.t)", "select(.c) | .t"] {
            let (stdout, stderr, code) = run_jq_stdin_streams(filter, &doc, &["-c"])?;
            assert_eq!(code, 0, "{filter} on {doc}: stderr {stderr:?}");
            assert_eq!(
                stdout.trim(),
                if filter == "path(.t)" {
                    r#"["t"]"#
                } else {
                    "5"
                },
                "{filter}"
            );
        }
    }

    // No collision, same shape: a fallback key at index 1 whose display
    // spelling is unique seeds the map and finds nothing, so the gate must
    // stay quiet. Without this the rows above would pass for a gate that
    // raised on any fallback key at all.
    let doc = r#"{"c":{"a":1,"\ud800":2},"t":5}"#;
    let (stdout, stderr, code) = run_jq_stdin_streams("select(.c) | .t", doc, &["-c"])?;
    assert_eq!(code, 0, "stdout {stdout:?} stderr {stderr:?}");
    assert_eq!(stdout.trim(), "5");

    Ok(())
}

/// #2168: `path()` validates only the nodes it navigates through, so a
/// `\uXXXX`-family decode failure in a *sibling* it never reaches no longer
/// makes it raise -- the rule plain navigation already followed.
///
/// This reverses `test_path_still_raises_on_an_undecodable_sibling_2061`,
/// which pinned the opposite. #2061 kept a whole-document gate here because
/// the materialization it replaced had doubled as one; #2168 measured that
/// gate at 67-75% of such a query's runtime and this project decided the
/// consistency question it left open -- `.d` answered `5` on the same
/// document `path(.d)` rejected.
///
/// **Diverges from jq, deliberately.** Real jq 1.7.1 rejects every document
/// below at parse time (`Invalid \uXXXX\uXXXX surrogate pair escape`), so
/// the `path(.d)` rows here used to *match* jq's outcome and no longer do.
/// jq rejects `.d` on the same documents too, which succinctly has always
/// answered, so the choice was between diverging uniformly and diverging by
/// spelling. Recorded, with why ADR-0018's decision order does not license
/// it, in `docs/compliance/jq/limitations.md`.
#[test]
fn test_path_answers_past_an_undecodable_sibling_2168() -> Result<()> {
    for bad in [r"\ud800", r"\uZZZZ", r"\x", r"\u12"] {
        let input = format!("{{\"a\":\"{bad}\",\"d\":5}}");

        // The sibling is never navigated to: answer, don't raise.
        let (stdout, stderr, code) = run_jq_stdin_streams("path(.d)", &input, &["-c"])?;
        assert_eq!(code, 0, "{bad}: stdout {stdout:?} stderr {stderr:?}");
        assert_eq!(stdout, "[\"d\"]\n", "{bad}");

        // Landing *on* the undecodable node is still not a decode: `path`
        // reports the position, and never reads the value there -- exactly
        // as `.a` itself echoes the raw bytes at exit 0.
        let (stdout, stderr, code) = run_jq_stdin_streams("path(.a)", &input, &["-c"])?;
        assert_eq!(code, 0, "{bad}: stdout {stdout:?} stderr {stderr:?}");
        assert_eq!(stdout, "[\"a\"]\n", "{bad}");

        // Navigating *through* it does read it, and raises the same error
        // the bare navigation does -- the touched-node control.
        let (nav_out, nav_err, nav_code) = run_jq_stdin_streams(".a.b", &input, &["-c"])?;
        let (stdout, stderr, code) = run_jq_stdin_streams("path(.a.b)", &input, &["-c"])?;
        assert_eq!(code, 5, "{bad}: stdout {stdout:?} stderr {stderr:?}");
        assert_eq!(stdout, "", "{bad}");
        assert_eq!(
            (stdout, stderr, code),
            (nav_out, nav_err, nav_code),
            "{bad}: path(.a.b) must fail exactly as .a.b does"
        );

        // Iterating over the undecodable scalar reaches it too
        // (`path_step_generic`'s own `string_decode_error` arm, live since
        // this change), where iterating over the *object* only names its
        // children and stays clean.
        let (stdout, stderr, code) = run_jq_stdin_streams("path(.a[])", &input, &["-c"])?;
        assert_eq!(code, 5, "{bad}: stdout {stdout:?} stderr {stderr:?}");
        assert!(
            stderr.contains("invalid unicode escape sequence") || stderr.contains("invalid escape"),
            "{bad}: {stderr}"
        );
        let (stdout, stderr, code) = run_jq_stdin_streams("[path(.[])]", &input, &["-c"])?;
        assert_eq!(code, 0, "{bad}: stdout {stdout:?} stderr {stderr:?}");
        assert_eq!(stdout, "[[\"a\"],[\"d\"]]\n", "{bad}");
    }
    Ok(())
}

/// #2168 (caught in review, not by the issue itself): `?` must never swallow
/// a decode failure inside a `path(...)` expression, the same #1620 rule
/// plain navigation already follows.
///
/// `path_walk_generic`'s and `path_step_generic`'s `Expr::Optional` arms
/// each discard *every* error from their inner walk unconditionally
/// (`let _ = ...`). Before this issue's own pre-walk gate was removed, an
/// undecodable string always raised earlier, in the whole-document walk, so
/// neither arm's discard was ever reachable with a `decode_failure` in hand.
/// Once the gate came off, both arms went live with the wrong rule: swallow
/// everything, `decode_failure` included.
#[test]
fn test_path_optional_still_raises_a_decode_failure_2168() -> Result<()> {
    let doc = r#"{"a":"\ud800","d":5}"#;

    for (filter, plain_nav) in [
        // `Expr::Optional` reached directly from `path_walk_generic`'s own
        // entry point.
        ("path(.a[]?)", ".a[]?"),
        // `Expr::Optional` as a pipe head, reached from
        // `path_step_generic`'s sibling arm instead.
        ("path((.a[]?)|.x)", "(.a[]?)|.x"),
    ] {
        let (_, nav_err, nav_code) = run_jq_stdin_streams(plain_nav, doc, &["-c"])?;
        assert_eq!(nav_code, 5, "sanity: {plain_nav} itself must still raise");

        let (stdout, stderr, code) = run_jq_stdin_streams(filter, doc, &["-c"])?;
        assert_eq!(
            code, 5,
            "{filter}: `?` swallowed a decode failure -- stdout {stdout:?} stderr {stderr:?} \
             (plain nav {plain_nav} raised {nav_err:?})"
        );
        assert!(
            stderr.contains("invalid unicode escape sequence") || stderr.contains("invalid escape"),
            "{filter}: {stderr:?}"
        );
    }
    Ok(())
}

/// #2168's rule, stated once as a table: which builtins validate a node the
/// query never reads, and which do not.
///
/// The two halves of the decision belong next to each other, because the
/// argument for it is their relationship. #2168 drew the line at "a builtin
/// whose walk's domain *is* the value it tests or emits (`select`, the
/// `sort_by` family) keeps the whole-subtree gate; one that only names or
/// navigates to a position (`path`, `key`, `parent`) validates just what it
/// touches". #2692 moved it once more, in the same direction: `select`'s
/// condition only ever asks `is_falsy`, which decodes nothing, so testing a
/// value is not reading it either and `select` joined the answering column.
/// What is left is the simple rule -- **anything that materializes validates
/// everything it materializes, and nothing else validates anything.** The
/// `sort_by` family stays in the raising column under exactly that rule: it
/// materializes a comparison key.
///
/// **Every row diverges from jq**, which rejects this document at parse time
/// whatever the filter -- including the rows that raise, since succinctly
/// raises for a different reason and at a different stage. What changed with
/// #2168 is that the answering column grew: `path`/`key`/`getpath` moved into
/// it, giving up an agreement with jq's outcome that `.d` never had. The
/// contract pinned is succinctly's own, recorded with its cost in
/// `docs/compliance/jq/limitations.md`.
#[test]
fn test_lazy_validation_boundary_2168() -> Result<()> {
    let doc = r#"{"a":"\ud800","d":5}"#;

    // Answers: never reads `.a`.
    for (filter, want) in [
        (".d", "5"),
        ("keys", r#"["a","d"]"#),
        ("length", "2"),
        ("path(.d)", r#"["d"]"#),
        (".d | key", r#""d""#),
        (".d | path", r#"["d"]"#),
        ("path(.a)", r#"["a"]"#),
        (".a | key", r#""a""#),
        ("[path(.[])]", r#"[["a"],["d"]]"#),
        ("[.[] | key]", r#"["a","d"]"#),
        ("[paths]", r#"[["a"],["d"]]"#),
        ("select(.d) | .d", "5"),
        // #2692: `select`'s condition is answered by `is_falsy`, which
        // decodes nothing -- so testing the *whole document* (`select(.)`)
        // validates no more of it than `.d` does. This row asserted exit 5
        // until #2692.
        ("select(.) | .d", "5"),
        // The same rule for the other truthiness readers, none of which
        // decode what they test either.
        ("if . then .d else 0 end", "5"),
        ("(. // 1) | .d", "5"),
        ("[.[] | not]", "[false,false]"),
        ("(true and true) | 1", "1"),
    ] {
        let (stdout, stderr, code) = run_jq_stdin_streams(filter, doc, &["-c"])?;
        assert_eq!(code, 0, "{filter}: stdout {stdout:?} stderr {stderr:?}");
        assert_eq!(stdout.trim(), want, "{filter}");
    }

    // Raises: reads `.a`, or emits/tests a subtree containing it.
    for filter in [
        ".a | length",    // reads the value
        ".a | tostring",  // reads the value
        "path(.a[])",     // iterating the scalar reads it
        "to_entries",     // materializes every member
        ". as $x | $x",   // materializes the binding
        ".a |= 1",        // the write path materializes
        "sort_by(.d)",    // the sort family keeps its gate
        "[.[]] | length", // array construction materializes each element
    ] {
        let (stdout, stderr, code) = run_jq_stdin_streams(filter, doc, &["-c"])?;
        assert_eq!(code, 5, "{filter}: stdout {stdout:?} stderr {stderr:?}");
        assert!(
            stderr.contains("invalid unicode escape sequence"),
            "{filter}: {stderr:?}"
        );
    }

    // The boundary #2692 left behind, pinned from the other side: testing the
    // root is free, but *materializing* it right afterwards still raises. The
    // condition is identical in both rows above and below -- only what the
    // consumer does with the value it passed through differs, which is the
    // whole of the surviving rule.
    for filter in [
        "select(.) | to_entries",
        "select(.) | . as $x | $x",
        "select(.) | [.[]] | length",
    ] {
        let (stdout, stderr, code) = run_jq_stdin_streams(filter, doc, &["-c"])?;
        assert_eq!(code, 5, "{filter}: stdout {stdout:?} stderr {stderr:?}");
        assert!(
            stderr.contains("invalid unicode escape sequence"),
            "{filter}: {stderr:?}"
        );
    }

    Ok(())
}

/// #2061: the walk's remaining arms — navigating *through* an absent node, and
/// the multi-stage pipe forms.
///
/// These are the shapes the first round of tests missed: `Iterate` and the
/// index/field steps each have a distinct `PathNode::Absent` arm, reached only
/// when an earlier component did not exist in the document, and a pipe of more
/// than two stages takes a different branch from a two-stage one. Every row is
/// jq 1.7.1's own output.
#[test]
fn test_path_cursor_native_absent_nodes_and_pipes_2061() -> Result<()> {
    for (filter, input, want) in [
        // Navigating on through an absent node: jq keeps yielding the path.
        ("path(.a.b.c)", "{}", "[\"a\",\"b\",\"c\"]\n"),
        ("path(.a[0])", "{}", "[\"a\",0]\n"),
        // Identity and a parenthesised stage inside a pipe.
        ("path(.|.a)", "{}", "[\"a\"]\n"),
        ("path((.a)|.b)", "{}", "[\"a\",\"b\"]\n"),
        // Three stages: the `rest.len() > 1` branch, distinct from two.
        ("path(.a|.|.b)", "{}", "[\"a\",\"b\"]\n"),
        (
            "path(.a.b.c)",
            "{\"a\":{\"b\":{\"c\":1}}}",
            "[\"a\",\"b\",\"c\"]\n",
        ),
        // Iterate as a later pipe stage, over both container kinds.
        ("path(.[]|.[])", "{\"a\":{\"b\":1}}", "[\"a\",\"b\"]\n"),
        ("path(.[]|.[])", "{\"a\":[1,2]}", "[\"a\",0]\n[\"a\",1]\n"),
        ("path(.a[])", "{\"a\":[1,2]}", "[\"a\",0]\n[\"a\",1]\n"),
        ("path(.a[])", "{\"a\":{\"b\":1}}", "[\"a\",\"b\"]\n"),
        // An empty container iterates to nothing rather than erroring.
        ("[path(.[]|.[])]", "{}", "[]\n"),
    ] {
        let (stdout, code) = run_jq_stdin(filter, input, &["-c"])?;
        assert_eq!(code, 0, "`{filter}` on `{input}`");
        assert_eq!(stdout, want, "`{filter}` on `{input}`");
    }

    // Iterating an absent node raises, exactly as iterating an explicit null
    // does -- the `PathNode::Absent` arm of the `Iterate` step.
    for (filter, input) in [("path(.a[])", "{}"), ("path(.a|.[])", "{}")] {
        let (stdout, stderr, code) = run_jq_stdin_streams(filter, input, &["-c"])?;
        assert_eq!(code, 5, "`{filter}` on `{input}`: stdout {stdout:?}");
        assert!(
            stderr.contains("Cannot iterate over null"),
            "`{filter}` on `{input}`: {stderr}"
        );
    }

    // A type error reached *after* an absent step still names the right type.
    let (_, stderr, code) = run_jq_stdin_streams("path(.a.b.c)", "{\"a\":[1,2]}", &["-c"])?;
    assert_eq!(code, 5);
    assert!(
        stderr.contains("Cannot index array with string \"b\""),
        "{stderr}"
    );

    Ok(())
}

/// #1872: `drive_fold_source` runs a navigating fold source **once**, with
/// tracking on, and the fold's real values come from that same evaluation --
/// so a side effect embedded in the source fires exactly as often as it does
/// in jq. Before #1872 the source was evaluated twice (once to path-check it,
/// once for the values), which fired the first output's `stderr` twice.
///
/// Counted by occurrence, not by line: `stderr` writes no trailing newline.
/// Captured from jq 1.7.1.
#[test]
fn fold_source_side_effect_fires_once_per_output_1872() -> Result<()> {
    for (input, filter, want, why) in [
        (
            "[1]",
            ". as $x | path(reduce (.[] | stderr) as $i (0; $x))",
            "1",
            "single-output navigating source: one write, not two",
        ),
        (
            "[1,2,3]",
            ". as $x | path(reduce (.[] | stderr) as $i (0; $x))",
            "123",
            "one write per output, in order",
        ),
    ] {
        let (_stdout, stderr, _code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(stderr, want, "{why}");
    }
    Ok(())
}

/// #1872 sibling, `foreach` rather than `reduce`: real jq's own disposition
/// for this exact shape genuinely differs between the two -- `reduce` (above)
/// answers `[]` (its UPDATE, `$x`, stays trackable), but `foreach` raises
/// `Invalid path expression` on its *first* step instead (jq 1.7.1: `. as $x
/// | path(foreach (.[] | stderr) as $i (0; $x))` on `[1,2,3]` writes `1` to
/// stderr, once, then raises -- #2031's "source navigation clobbers the
/// shared path register" rule makes `$x` untrackable inside a `foreach` step
/// where it stays trackable inside `reduce`'s single terminal step).
///
/// succinctly matches that disposition (raises, no stdout) since #2234 fixed
/// `stderr`'s own path-trackability -- before that fix, this raised nowhere
/// at all and instead answered wrongly with `[]` three times, exit 0.
///
/// The write *count* matches since #2235: the source is pulled by demand
/// (`drive_fold_source`), the fold emits each output straight to `path()`'s
/// terminal check, and that check refuses the first step's emission before
/// the source is ever pulled again. Before #2235 `Keep::AtMost(usize::MAX)`
/// pulled the whole source upfront and all three writes fired first.
#[test]
fn fold_source_foreach_diverges_from_reduce_on_this_shape_1872() -> Result<()> {
    for filter in [
        ". as $x | path(foreach (.[] | stderr) as $i (0; $x))",
        ". as $x | path(foreach (.[] | debug) as $i (0; $x))",
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some("[1,2,3]"))?;
        assert_eq!(code, 5, "{filter}: stdout: {stdout:?} stderr: {stderr:?}");
        assert_eq!(stdout, "", "{filter}");
        let (writes, error) = stderr
            .split_once("jq: error")
            .unwrap_or_else(|| panic!("{filter}: no error on stderr: {stderr:?}"));
        assert!(
            writes == "1" || writes == "[\"DEBUG:\",1]\n",
            "{filter}: one source write, then the raise -- got {writes:?}"
        );
        assert!(
            error.contains("Invalid path expression with result [1,2,3]"),
            "{filter}: stderr: {stderr:?}"
        );
    }
    Ok(())
}

/// #2235: a path-mode fold pulls its source **by demand** -- one element,
/// one step, then the next element -- and its outputs reach `path()`'s
/// terminal check as they are emitted, so whatever stops the fold (a step
/// that raises, a terminal refusal, an outer bound, a `break`) stops the
/// source with nothing past it evaluated. `reduce` runs its prefix steps
/// before a trailing source escape is raised, and an erroring source is no
/// longer re-evaluated untracked (the old fallback double-fired side effects
/// and discarded the per-step register, turning jq's refusal into an
/// answer). Every row is captured from jq 1.7.1: `(input, filter, stdout,
/// stderr, exit)`; stderr is compared whole, so a `stderr`/`debug` write
/// count is pinned exactly.
#[test]
fn fold_source_is_pulled_by_demand_2235() -> Result<()> {
    let e = |msg: &str| format!("jq: error (at <stdin>:0): {msg}\n");
    let invalid = |v: &str| e(&format!("Invalid path expression with result {v}"));
    for (input, filter, want_out, want_err, want_code) in [
        // EXTRACT raises on the first element.
        (
            "[1,2,3]",
            "path(foreach (.[] | stderr) as $i (.; .; error(\"u\")))",
            String::new(),
            format!("1{}", e("u")),
            5,
        ),
        // A `reduce` step raises on the first element.
        (
            "[1,2,3]",
            "path(reduce (.[]|stderr|.+0) as $i (.; if $i==1 then error(\"u\") else . end))",
            String::new(),
            format!("1{}", e("u")),
            5,
        ),
        // `reduce` runs its prefix steps before the source's own escape --
        // an error, a halt (which also writes its own input), a break.
        (
            r#"{"a":1}"#,
            "path(reduce (1,2,error(\"s\")) as $i (.; stderr))",
            String::new(),
            format!("{{\"a\":1}}{{\"a\":1}}{}", e("s")),
            5,
        ),
        (
            r#"{"a":1}"#,
            "path(reduce (1,2,halt_error(3)) as $i (.; stderr))",
            String::new(),
            "{\"a\":1}{\"a\":1}{\"a\":1}\n".to_string(),
            3,
        ),
        (
            r#"{"a":1}"#,
            "[label $out | path(reduce (1,2,break $out) as $i (.; stderr))]",
            "[]\n".to_string(),
            "{\"a\":1}{\"a\":1}".to_string(),
            0,
        ),
        // A step's `break` stops the pull.
        (
            "[1,2,3]",
            "[label $out | path(reduce (.[]|stderr) as $i (.; if $i==2 then break $out else . end))]",
            "[]\n".to_string(),
            "12".to_string(),
            0,
        ),
        // The old fallback's shapes: an ordinary error after a source output
        // (`foreach` refuses step 1's emission first; `reduce` raises `s`
        // after one write, not two), a `break` reached through the source,
        // and an error with nothing delivered before it.
        (
            "[1,2,3]",
            "path(foreach (.[] | stderr | ., error(\"s\")) as $i (.; .))",
            String::new(),
            format!("1{}", invalid("[1,2,3]")),
            5,
        ),
        (
            "[1,2]",
            "path(reduce (.[]|stderr|(.,error(\"s\"))) as $i (.; .))",
            String::new(),
            format!("1{}", e("s")),
            5,
        ),
        (
            "[1,2]",
            "[label $out | path(foreach (.[], break $out) as $i (.; .))]",
            String::new(),
            invalid("[1,2]"),
            5,
        ),
        (
            "[1,2]",
            "[label $out | path(foreach ((.[]|stderr), break $out) as $i (.; .))]",
            String::new(),
            format!("1{}", invalid("[1,2]")),
            5,
        ),
        (
            "[1,2]",
            "path(foreach ((.[]|stderr|empty), error(\"s\")) as $i (.; .))",
            String::new(),
            format!("12{}", e("s")),
            5,
        ),
        // A halt later in the source is never reached once step 1 refuses.
        (
            "[1,2,3]",
            "path(foreach (.[] | stderr | if . == 2 then halt_error else . end) as $i (.; .; .))",
            String::new(),
            format!("1{}", invalid("[1,2,3]")),
            5,
        ),
        // A bound inside the source, and one outside the whole `path()`.
        (
            "[1,2,3]",
            "path(foreach (limit(2; .[]|stderr)) as $i (.; .))",
            String::new(),
            format!("1{}", invalid("[1,2,3]")),
            5,
        ),
        (
            "[1,2,3,4]",
            "[limit(2; path(foreach (.[]|stderr|.+0) as $i (0; .)))]",
            String::new(),
            format!("1{}", invalid("0")),
            5,
        ),
        // Several INIT forks: the first fork's refusal stops everything; a
        // later fork re-drives the source (with its side effects) only once
        // the earlier one completed.
        (
            "[1,2,3]",
            "path(foreach (.[]|stderr) as $i ((.,.); .))",
            String::new(),
            format!("1{}", invalid("[1,2,3]")),
            5,
        ),
        (
            "[1,2]",
            "[path(foreach (.[]|stderr|.+0) as $i ((null,null); .))?]",
            "[]\n".to_string(),
            "1".to_string(),
            0,
        ),
        (
            "[1,2]",
            "[path(reduce (.[]|stderr|.+0) as $i ((0,1); .))?]",
            "[]\n".to_string(),
            "12".to_string(),
            0,
        ),
        // A `?//` in the source retries the step on the reset state after a
        // step error, but never after a halt. A terminal refusal of the
        // first alternative's output is retried too: into the second's
        // accepted `.`, or -- when the retried step re-enters from the
        // refused step's own output -- into a second refusal naming it.
        (
            "1",
            "path(foreach (1 as $x ?// $y | 1) as $v (.; stderr | error(\"u\")))",
            String::new(),
            format!("1null{}", e("u")),
            5,
        ),
        (
            "1",
            "path(foreach (1 as $x ?// $y | 1) as $v (.; stderr | halt_error))",
            String::new(),
            "11\n".to_string(),
            5,
        ),
        (
            r#"{"a":1}"#,
            "path(foreach (1 as $x ?// $y | if $x == 1 then 1 else 2 end) as $v (.; .; if $v == 1 then 1 else . end))",
            "[]\n".to_string(),
            String::new(),
            0,
        ),
        (
            r#"{"a":1}"#,
            "path(foreach (1 as $x ?// $y | if $x == 1 then 1 else 2 end) as $v (.; if $v == 2 then . else $v end))",
            String::new(),
            invalid("1"),
            5,
        ),
        // ... and from a multi-output UPDATE's *first* output when that is
        // the one refused: every output becomes the state before it is
        // emitted, not only the last.
        (
            r#"{"a":1}"#,
            "path(foreach (1 as $x ?// $y | if $x == 1 then 1 else 2 end) as $v (.; if $v == 2 then . else (1, 2) end))",
            String::new(),
            invalid("1"),
            5,
        ),
        // Sources reached through `?` and `try`/`catch` stream too.
        (
            "[1,2,3]",
            ". as $x | path(foreach ((.[] | stderr)?) as $i (0; $x))",
            String::new(),
            format!("1{}", invalid("[1,2,3]")),
            5,
        ),
        (
            r#"[{"a":1},{"a":2}]"#,
            "path(foreach (.[] | stderr | (.a)?) as $i (.; .; error(\"u\")))",
            String::new(),
            format!("{{\"a\":1}}{}", e("u")),
            5,
        ),
        // `//` in the source: its escape prefix is truthy-filtered (one step,
        // not two), and its left side is pulled by demand.
        (
            "[true,false]",
            "path(reduce (((.[] | . and true), error(\"x\")) // 9) as $i (.; stderr))",
            String::new(),
            format!("[true,false]{}", e("x")),
            5,
        ),
        (
            "[1,2,3]",
            "path(reduce ((.[]|stderr|.+0) // 9) as $i (.; if $i==2 then error(\"u\") else . end))",
            String::new(),
            format!("12{}", e("u")),
            5,
        ),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, want_code, "{filter}: stdout: {stdout:?} stderr: {stderr:?}");
        assert_eq!(stdout, want_out, "{filter}");
        assert_eq!(stderr, want_err, "{filter}");
    }

    // `recurse(f)` delivers each node before resolving its `f`, so a bound
    // never pays for `f` on a node it did not ask for: `limit(1)` runs
    // `debug` zero times, `limit(2)` once and then refuses the computed
    // child. Captured from jq 1.7.1.
    for (filter, want_out, want_err, want_code) in [
        (
            "path(limit(1; recurse(if (.|debug) < 3 then .+1 else empty end)))",
            "[]\n",
            String::new(),
            0,
        ),
        (
            "path(limit(2; recurse(if (.|debug) < 3 then .+1 else empty end)))",
            "[]\n",
            format!("[\"DEBUG:\",0]\n{}", invalid("1")),
            5,
        ),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some("0"))?;
        assert_eq!(
            code, want_code,
            "{filter}: stdout: {stdout:?} stderr: {stderr:?}"
        );
        assert_eq!(stdout, want_out, "{filter}");
        assert_eq!(stderr, want_err, "{filter}");
    }

    // `inputs` stays on the lazy value-mode producer: one document per
    // demand, the rest still readable afterwards.
    let (stdout, stderr, code) = run_jq_full(
        &[
            "-nc",
            "[try path(foreach inputs as $i (.; error(\"u\"))) catch .], input",
        ],
        Some("1 2 3"),
    )?;
    assert_eq!(code, 0, "stderr: {stderr:?}");
    assert_eq!(stdout, "[\"u\"]\n2\n");
    Ok(())
}

/// #1872: `Keep::AtMost` makes a fold source's leaves keep every output, so
/// the count-bounded resolutions must narrow that bound rather than forward
/// it -- otherwise `first(range(2000000000))` inside a navigating source
/// materializes two billion values instead of stopping at one.
///
/// A subprocess rather than an in-process `query!`, so a regression here
/// exhausts the child's memory rather than the test harness's. Both
/// expectations are captured from jq 1.7.1: `first(...)` contributes exactly
/// one source element, `limit(3; ...)` exactly three.
#[test]
fn fold_source_bounded_generator_stays_bounded_1872() -> Result<()> {
    for (filter, want_stdout, why) in [
        (
            "path(foreach (first(range(2000000000)), keys[]) as $k (.; .))",
            "[]\n",
            "first(...) yields one source element",
        ),
        (
            "path(foreach (limit(3; range(2000000000)), keys[]) as $k (.; .))",
            "[]\n[]\n[]\n",
            "limit(3; ...) yields exactly three, not one and not two billion",
        ),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(r#"{"a":1}"#))?;
        assert_eq!(stdout, want_stdout, "{why}");
        assert!(
            stderr.contains("near attempt to iterate through"),
            "{why} -- {stderr}"
        );
        assert_eq!(code, 5, "{why}");
    }
    Ok(())
}

/// #1872: `drive_fold_source` takes a navigating source's values from the
/// resolver's own branches, which makes a *short* branch prefix a wrong
/// answer rather than merely a wrong error message. Several arms below that
/// call launder an `Err` into a truncated `Ok` -- `Expr::Optional`'s blanket
/// arm, `Expr::Label` on a matching break, a satisfied bound -- so their
/// values are a fold's values. Each case's value count is captured from jq
/// 1.7.1.
#[test]
fn fold_source_laundered_short_prefix_value_counts_1872() -> Result<()> {
    for (input, filter, want, why) in [
        (
            "[10,20,30]",
            "[foreach ((.[(0,error(\"b\")):(2,3)])?) as $k (0; .+1)]",
            "[1,2]\n",
            "Expr::Optional swallows the escape and keeps its own prefix",
        ),
        (
            r#"{"a":{"b":1},"c":[1,2]}"#,
            "path(label $out | ((.c[0:1], break $out), .a))",
            "[\"c\",{\"start\":0,\"end\":1}]\n",
            "Expr::Label keeps the prefix produced before a matching break",
        ),
        (
            r#"{"a":1}"#,
            "[foreach (limit(2; 1,2,3), 9) as $k (0; .+$k)]",
            "[1,3,12]\n",
            "a bounded consumer truncates to its bound, not to one",
        ),
    ] {
        let (stdout, _stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(stdout, want, "{why}");
        assert_eq!(code, 0, "{why}");
    }
    Ok(())
}

/// #1872/#2031: a fold source that produces a *trackable* branch seeds that
/// step's register from the element's own path, so jq's own fold clobbers
/// its path register and refuses to emit at all. These pin the refusal:
/// stdout stays empty and the exit code stays 5, exactly as in jq — only the
/// *message* differs, which is #2031's divergence and not this one's.
///
/// This is the shape randomised differential fuzzing against jq 1.7.1
/// caught: an earlier attempt that streamed the resolved values without the
/// per-step register let eleven of four thousand generated folds stream a
/// prefix jq never streams. No golden can pin it, since a golden compares
/// stderr byte-for-byte on a failing case and the message diverges.
#[test]
fn fold_source_trackable_branch_falls_back_to_two_pass_1872() -> Result<()> {
    for (input, filter, why) in [
        (
            r#"{"a":1}"#,
            "path(foreach (.[], keys[]) as $k (.; .))",
            "`.[]` navigates successfully, so its branches are trackable",
        ),
        (
            r#"{"a":{"b":2},"b":3}"#,
            "path(foreach (limit(3; .[], keys[]), .a[]) as $k (.; .))",
            "a trackable branch under a bound counts the same",
        ),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(stdout, "", "{why} -- jq streams nothing here either");
        assert_eq!(code, 5, "{why}");
        // The message is #2031's divergence: jq blames its own clobbered
        // register ("Invalid path expression with result ..."), succinctly
        // blames the navigation. Both exit 5 with no output, which is what
        // this test exists to keep true.
        assert!(
            stderr.contains("Invalid path expression"),
            "{why} -- {stderr}"
        );
    }
    Ok(())
}

/// #2124: a `?`-guarded comma branch that fails to navigate is pruned when
/// it is the *only* branch, but `=`/`|=` used to keep it (and raise its
/// navigation error) once it had a surviving sibling -- `path()`/`del()`
/// were already correct for this shape via unrelated fixes (#2049/#2108),
/// but `=`/`|=`'s own resolution path (`resolve_seq`'s no-computed-key fast
/// path, `value_after_components`) shared none of that. Root cause: a
/// component reaching that fast path is proven single-valued by
/// construction, so the only way it produces zero outputs is a
/// `?`-suppressed failure -- that used to fabricate a `null` result instead
/// of pruning the whole branch. All rows verified against jq 1.7.1.
#[test]
fn test_optional_comma_sibling_prunes_for_assignment_2124() -> Result<()> {
    for (filter, why) in [
        ("(.b, .c.a?) = 9", "plain assignment"),
        ("(.b, .c.a?) |= 9", "update assignment"),
        ("(.c.a?, .b) = 9", "argument order must not matter"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(r#"{"c":1}"#))?;
        assert_eq!(code, 0, "{why} -- stdout: {stdout:?} stderr: {stderr:?}");
        assert_eq!(stdout, "{\"c\":1,\"b\":9}\n", "{why}");
    }
    Ok(())
}

/// #2124 sibling: the same pruning fix across non-object scalar shapes for
/// `.c`, confirming it isn't accidentally keyed to a specific value type.
/// Verified live against jq 1.7.1.
#[test]
fn test_optional_comma_sibling_prune_holds_across_scalar_shapes_for_assignment_2124() -> Result<()>
{
    for doc in [r#"{"c":"s"}"#, r#"{"c":true}"#, r#"{"c":[]}"#] {
        let (stdout, stderr, code) = run_jq_full(&["-c", "(.b, .c.a?) = 9"], Some(doc))?;
        assert_eq!(
            code, 0,
            "doc={doc} -- stdout: {stdout:?} stderr: {stderr:?}"
        );
        let expected = format!("{}\n", doc.trim_end_matches('}').to_owned() + ",\"b\":9}");
        assert_eq!(stdout, expected, "doc={doc}");
    }
    Ok(())
}

/// #2124's fix has two call sites, not one: `resolve_seq`'s fully-static
/// fast path (every test above) and `apply_static_tail_one`'s per-branch tail
/// application, reached only once a *real* dynamic/computed element
/// precedes the `?`-guarded step in the same pipe. `.[(0,1)].a?` fans out
/// over the computed index first (dynamic), then applies `.a? = 9` as each
/// branch's own static tail -- branch `0` (a scalar) must prune without
/// disturbing branch `1` (an object, which resolves and writes normally).
/// Verified against jq 1.7.1: the whole filter is a no-op here because both
/// branches' writes are themselves no-ops (branch 0 prunes, branch 1's `.a`
/// already holds `9`).
#[test]
fn test_optional_tail_after_dynamic_fanout_prunes_only_its_own_branch_2124() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["-c", ".[(0,1)].a? = 9"], Some(r#"[1, {"a":9}]"#))?;
    assert_eq!(code, 0, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "[1,{\"a\":9}]\n");
    Ok(())
}

/// #2124 regression guard: `path()` and `del()` were already correct for
/// this shape before this fix (via #2049/#2108, unrelated code paths) --
/// this pins that the shared `resolve_seq` fix doesn't disturb them.
#[test]
fn test_optional_comma_sibling_prune_still_correct_for_path_and_del_2124() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["-c", "[path(.b, .c.a?)]"], Some(r#"{"c":1}"#))?;
    assert_eq!(code, 0, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "[[\"b\"]]\n");

    let (stdout, stderr, code) = run_jq_full(&["-c", "del(.b, .c.a?)"], Some(r#"{"c":1}"#))?;
    assert_eq!(code, 0, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "{\"c\":1}\n");
    Ok(())
}

/// #2089: `range`'s `MAX_RANGE` accumulation cap used to truncate silently
/// (a success, exit 0, wrong data) instead of raising -- the one guard in
/// `eval.rs` that chose that failure mode, unlike its
/// `until`/`while`/`reduce`/`foreach` siblings. All rows verified against
/// jq 1.7.1, which has no such cap at all (bounded only by memory).
#[test]
fn test_range_max_exceeded_raises_instead_of_truncating_2089() -> Result<()> {
    for (filter, why) in [
        ("[range(100001)] | length", "the issue's own minimal repro"),
        (
            "reduce range(150000) as $x (0; . + $x)",
            "an aggregation is exactly where a silent truncation is most \
             dangerous -- a plausible-looking wrong number, not a crash",
        ),
        ("[range(0;200000)] | length", "the two-argument form"),
        (
            "[range(0;200000;1)] | length",
            "the three-argument integer form",
        ),
        (
            "[range(0;-200000;-1)] | length",
            "a descending integer range",
        ),
        ("[range(0;200000;0.5)] | length", "a float step"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-nc", filter], None)?;
        assert_eq!(code, 5, "{why} -- stdout: {stdout:?} stderr: {stderr:?}");
        assert_eq!(stdout, "", "{why}");
        assert!(
            stderr.contains("range: maximum iterations exceeded"),
            "{why} -- stderr: {stderr:?}"
        );
    }
    Ok(())
}

/// #2089 boundary: landing exactly on the cap must not raise -- only
/// genuinely exceeding it should. Verified against jq 1.7.1 (`100000`).
#[test]
fn test_range_at_max_exactly_does_not_raise_2089() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["-nc", "[range(100000)] | length"], None)?;
    assert_eq!(code, 0, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "100000\n");
    Ok(())
}

/// #2089 sibling: the fix must not regress the demand-driven fast path a
/// consumer that stops well short of the cap already relied on --
/// `each_range`'s `emit` only raises when the sink is still asking for more
/// once a capped batch is exhausted, never when the sink stops early on its
/// own. Verified against jq 1.7.1: both return instantly, no error, no hang.
#[test]
fn test_range_early_stop_consumer_unaffected_by_cap_2089() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["-nc", "first(range(1000000000))"], None)?;
    assert_eq!(code, 0, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "0\n");

    let (stdout, stderr, code) = run_jq_full(&["-nc", "[limit(3; range(200000))]"], None)?;
    assert_eq!(code, 0, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "[0,1,2]\n");
    Ok(())
}

/// #2089 sibling: a demand-driven consumer that *does* ask past the cap
/// (unlike the early-stop cases above) must still raise -- this was already
/// silently wrong before #2089 (returning a truncated 100000-element/-index
/// answer at exit 0), just not the shape the issue's own repro table
/// happened to list. Verified against jq 1.7.1: `200000`/`150000`, no cap.
#[test]
fn test_range_demand_driven_consumer_past_cap_still_raises_2089() -> Result<()> {
    let (stdout, stderr, code) =
        run_jq_full(&["-nc", "[limit(200000; range(1000000))] | length"], None)?;
    assert_eq!(code, 5, "stdout: {stdout:?} stderr: {stderr:?}");
    assert!(stderr.contains("range: maximum iterations exceeded"));

    let (stdout, stderr, code) = run_jq_full(&["-nc", "nth(150000; range(1000000))"], None)?;
    assert_eq!(code, 5, "stdout: {stdout:?} stderr: {stderr:?}");
    assert!(stderr.contains("range: maximum iterations exceeded"));
    Ok(())
}

/// #2032: `E[K]` compiles as `K as $k | E | .[$k]`, so `E` is re-evaluated
/// once per output of the key generator `K`, not once total -- a side
/// effect in `E` must fire once per key. `succinctly` used to cache `E`'s
/// result and loop the keys over it, firing the side effect once overall
/// instead. Counted by occurrence, not by line (`stderr` writes no trailing
/// newline). All rows verified against jq 1.7.1.
///
/// This is `eval_generic::eval_index_expr`'s own fix -- the function an
/// ordinary CLI `.[$keys]` read actually reaches (confirmed empirically:
/// `eval::eval_index_expr`'s identical sibling fix, verified separately via
/// `jq -n '[(input)[("a","b")]]'`, is reached only through certain fallback
/// shapes, not this file's own stdin-fed queries).
#[test]
fn test_index_expr_target_reevaluated_once_per_key_2032() -> Result<()> {
    for (input, filter, want_stderr, why) in [
        (
            "[1,2]",
            "[(.[] | stderr)[(\"a\",\"b\")]?]",
            "1212",
            "the issue's own repro: two keys, both fail to index (suppressed \
             by `?`), target still re-runs once per key",
        ),
        (
            r#"[{"a":1,"b":2},{"a":3,"b":4}]"#,
            "[(.[] | stderr)[(\"a\",\"b\")]]",
            r#"{"a":1,"b":2}{"a":3,"b":4}{"a":1,"b":2}{"a":3,"b":4}"#,
            "an indexable multi-output target: values AND side effects both \
             re-run per key",
        ),
        (
            r#"{"a":{"x":1},"b":{"x":2}}"#,
            "[(. | stderr)[(\"a\",\"b\")]]",
            r#"{"a":{"x":1},"b":{"x":2}}{"a":{"x":1},"b":{"x":2}}"#,
            "a single-output target re-runs once per key too, not just \
             multi-output ones",
        ),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 0, "{why} -- stdout: {stdout:?} stderr: {stderr:?}");
        assert_eq!(stderr, want_stderr, "{why}");
    }
    Ok(())
}

/// #2032 sibling: a key whose target evaluation is genuinely empty must not
/// short-circuit the *remaining* keys -- each key's target is now
/// independent, unlike the old once-for-all-keys evaluation, where an empty
/// target for any one key made every key look empty. `inputs` (an impure,
/// stateful generator) is what makes the target's result vary per
/// re-evaluation here: for key `0` it drains the one remaining stdin line
/// (`[10,20]`) and yields it, so `.[0]` produces `10`; re-evaluating
/// `inputs` for key `1` finds the stream already exhausted and yields
/// nothing at all (not an error -- a target that legitimately produces zero
/// values for that key), so key `1` contributes nothing to the output.
/// Verified against jq 1.7.1 (`jq -n 'inputs[(0,1)]'` also emits only `10`).
#[test]
fn test_index_expr_one_empty_key_does_not_short_circuit_others_2032() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["-c", "-n", "inputs[(0,1)]"], Some("[10,20]\n"))?;
    assert_eq!(code, 0, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "10\n");
    Ok(())
}

/// #2032 sibling: a second impure-target regression alongside the `stderr`
/// cases above, this time via `input` (a stateful generator that consumes
/// from the CLI's document stream) rather than a side-channel write --
/// `.[$keys]`'s target must be *re-read* from the stream once per key, not
/// read once and reused. `run_jq_full` execs the real CLI subprocess in
/// `succinctly jq` mode, which always dispatches through
/// `eval_generic::eval_index_expr` -- `jq_runner.rs` never calls
/// `eval::eval_index_expr` at all. #2153: `eval::eval_index_expr` is *not*
/// CLI-unreachable in general, though -- `succinctly yq` reaches it via
/// `yq_runner.rs`'s `evaluate_input` (`jq::eval::<Vec<u64>,
/// YqSemantics>(expr, cursor)`, at least 8 call sites, triggered by e.g.
/// `-n`/`-R`/`--slurp`). That path can't extend regression coverage to
/// *this* stateful-target mechanism specifically, though: `input`/`inputs`
/// are rejected at parse time in yq mode (`parser.rs`'s
/// `reject_in_yq_mode("input")`, live-verified: `succinctly yq -n
/// '[(input)[("a","b")]]'` -> "input is not supported in yq mode"), so the
/// yq-mode path only proves `eval::eval_index_expr` is CLI-reachable on
/// *pure* targets -- the same category `eval.rs`'s own in-process
/// `#[cfg(test)]` unit tests already cover (e.g.
/// `test_computed_index_ordinary_cross_product_unaffected_1634`), not a
/// second, independent source of coverage for the stateful re-evaluation
/// bug this test itself pins. That bug's only coverage remains this test
/// (via `eval_generic::eval_index_expr`, live over `succinctly jq`) plus
/// `eval.rs`'s own in-process unit tests -- unchanged from before this
/// comment was corrected.
/// Verified against jq 1.7.1: both emit `[1,4]` (key `"a"` re-reads `input`
/// to get `{"a":1,"b":2}` -> `.a` = 1; key `"b"` re-reads `input` again to
/// get `{"a":3,"b":4}` -> `.b` = 4).
#[test]
fn test_index_expr_eval_rs_dispatch_target_reevaluated_per_key_2032() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(
        &["-c", "-n", "[(input)[(\"a\",\"b\")]]"],
        Some("{\"a\":1,\"b\":2}\n{\"a\":3,\"b\":4}\n"),
    )?;
    assert_eq!(code, 0, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "[1,4]\n");
    Ok(())
}

/// #2032 review: `eval_generic.rs`'s per-key `KeyTargets::Native` arm
/// reserves capacity once, up front, on whichever of `cursors`/`owned` is
/// live *at that moment* -- but `index_one_generic` can still return
/// `GenericResult::Owned` for an ordinary target in the middle of that same
/// `ts` list (a missing object field or out-of-bounds index, both decode to
/// an owned `Null`), flipping liveness from `cursors` to `owned` partway
/// through, past the point the upfront reservation could see it. Each
/// element of `.[]` here is one key's whole `ts` list for the `[("a")]`
/// index that follows: `{"a":1}` -> `GenericResult::OneCursor` (native),
/// `{}` -> `GenericResult::Owned(Null)` (missing field) -- the second
/// element is exactly the flip. Without a guard on every push made *after*
/// such a flip (not just the upfront batch), this reopens a narrow form of
/// the #1017/#1612/#1634/#1669 abort-on-allocation-failure class in
/// production traffic, not just a synthetic fallback path. Verified against
/// jq 1.7.1: both emit `1` then `null`.
#[test]
fn test_index_expr_native_to_owned_flip_mid_key_reserves_2032() -> Result<()> {
    let (stdout, stderr, code) = run_jq_full(&["-c", ".[][(\"a\")]"], Some(r#"[{"a":1},{}]"#))?;
    assert_eq!(code, 0, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "1\nnull\n");
    Ok(())
}

/// #2143: `E[S:T]` compiles as `S as $s | T as $t | E | .[$s:$t]` -- `E` is
/// re-evaluated once per `(s, t)` pair the bound generators produce, not
/// once total. `succinctly` used to cache `E`'s result and loop the
/// `(s, t)` pairs over it, firing a side effect in `E` once overall instead
/// of once per pair. Counted by occurrence, not by line (`stderr` writes no
/// trailing newline). Verified against jq 1.7.1.
///
/// This is `eval_generic::eval_slice_expr`'s own fix -- the function an
/// ordinary CLI `.[$s:$t]` read actually reaches (confirmed empirically,
/// same as #2032's sibling: `eval::eval_slice_expr`'s identical fix is
/// reached only through certain fallback shapes, not this file's own
/// stdin-fed queries).
#[test]
fn test_slice_expr_target_reevaluated_once_per_pair_2143() -> Result<()> {
    for (input, filter, want_stderr, why) in [
        (
            "[[10,20],[30,40]]",
            "[(.[] | stderr)[(0,1):(1,2)]]",
            "[10,20][30,40][10,20][30,40][10,20][30,40][10,20][30,40]",
            "the issue's own repro: two starts x two ends = four pairs, \
             target re-runs once per pair",
        ),
        (
            "[10,20,30]",
            "[(. | stderr)[0:(1,2,3)]]",
            "[10,20,30][10,20,30][10,20,30]",
            "a single start bound still re-runs the target once per end \
             value, not just once overall",
        ),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(code, 0, "{why} -- stdout: {stdout:?} stderr: {stderr:?}");
        assert_eq!(stderr, want_stderr, "{why}");
    }
    Ok(())
}

/// #2143 sibling: a pair whose target evaluation is genuinely empty must
/// not short-circuit the *remaining* pairs -- each pair's target is now
/// independent, unlike the old once-overall evaluation, where an empty
/// target for any one pair made every pair look empty. `inputs` (an impure,
/// stateful generator) is what makes the target vary per re-evaluation
/// here: for pair `(0,1)` it drains the one remaining stdin line
/// (`[10,20]`) and yields it, so `.[0:1]` produces `[10]`; re-evaluating
/// `inputs` for pair `(1,2)` finds the stream already exhausted and yields
/// nothing at all (not an error -- a target that legitimately produces zero
/// values for that pair), so that pair contributes nothing to the output.
/// Verified against jq 1.7.1 (`jq -n 'inputs[(0,1):(1,2)]'` also emits only
/// `[10]`).
#[test]
fn test_slice_expr_one_empty_pair_does_not_short_circuit_others_2143() -> Result<()> {
    let (stdout, stderr, code) =
        run_jq_full(&["-c", "-n", "inputs[(0,1):(1,2)]"], Some("[10,20]\n"))?;
    assert_eq!(code, 0, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "[10]\n");
    Ok(())
}

/// #2226: `eval_generic::eval_index_expr`'s target-evaluation `Partial` arm
/// used to discard `E`'s own already-produced prefix and keep only the
/// escaping control. `([1,2],[3,4],error("x"))[(0,1)]` makes both the key
/// (`(0,1)`, a bare computed generator with no `as`-binding, so this
/// dispatches through `eval_generic.rs` rather than `eval.rs`'s sibling)
/// *and* the target multi-output: `E`'s first two branches each index
/// cleanly at key `0` (`1`, then `3`) before the third branch errors.
/// Verified against jq 1.7.1: `echo null | jq -c
/// '([1,2],[3,4],error("x"))[(0,1)]'` prints `1` then `3` before raising.
#[test]
fn test_index_expr_cli_dispatch_target_own_partial_prefix_preserved_2226() -> Result<()> {
    let (stdout, stderr, code) =
        run_jq_full(&["-c", "([1,2],[3,4],error(\"x\"))[(0,1)]"], Some("null"))?;
    assert_eq!(code, 5, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "1\n3\n");
    assert!(stderr.contains('x'), "stderr: {stderr:?}");
    Ok(())
}

/// #2226 review (patch coverage): `eval_generic::eval_index_expr`'s target
/// `Partial` arm's `Ok(None)` sub-case -- an earlier-produced value that
/// legitimately isn't indexable, suppressed by `optional` rather than
/// erroring (`true` here; `?` only gates *this* per-value type mismatch,
/// not `target`'s own trailing `error("x")`). Verified against jq 1.7.1:
/// `(true, [7], error("x"))[(0+0)]?` prints `7` then still raises `x`.
#[test]
fn test_index_expr_cli_dispatch_target_own_partial_prefix_ok_none_suppressed_by_optional_2226(
) -> Result<()> {
    let (stdout, stderr, code) =
        run_jq_full(&["-c", "(true, [7], error(\"x\"))[(0+0)]?"], Some("null"))?;
    assert_eq!(code, 5, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "7\n");
    assert!(stderr.contains('x'), "stderr: {stderr:?}");
    Ok(())
}

/// #2226 review (patch coverage): `eval_generic::eval_index_expr`'s target
/// `Partial` arm's `Err` sub-case -- an earlier-produced value that isn't
/// indexable, with no `?` to suppress it, so the per-value index failure
/// fires (and outranks `target`'s own trailing `error("x")`, which is never
/// reached). Verified against jq 1.7.1: `(true, [7], error("x"))[(0+0)]`
/// raises "Cannot index boolean with number", not `x`.
#[test]
fn test_index_expr_cli_dispatch_target_own_partial_prefix_err_outranks_control_2226() -> Result<()>
{
    let (stdout, stderr, code) =
        run_jq_full(&["-c", "(true, [7], error(\"x\"))[(0+0)]"], Some("null"))?;
    assert_eq!(code, 5, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout, "");
    assert!(
        stderr.contains("Cannot index boolean with number"),
        "stderr: {stderr:?}"
    );
    Ok(())
}

/// #2226 sibling: the same target-own-prefix fix for
/// `eval_generic::eval_slice_expr` -- the issue's own canonical repro.
/// `(0,1):(1,2)` are bare computed bounds (no `as`-binding), so this
/// dispatches through `eval_generic.rs` rather than `eval.rs`'s sibling
/// (see `test_slice_expr_eval_rs_dispatch_target_reevaluated_per_pair_2143`
