/// #2807 (review): empty parens stay a syntax error, even for the one arm
/// whose recovery is a rewind rather than a hand-over.
///
/// `retry_shadow_candidate_as_generic_call` guards its own reparse with
/// `peek_after_keyword_at_is_empty_parens` precisely so `def f: 1; f()`
/// cannot be re-read as a legitimate arity-0 call; `strenv`'s rewind bypasses
/// that function, so it repeats the check. Without it
/// `def strenv: 1; strenv()` answered `1`, where jq 1.7.1 (and the pre-#2807
/// parser) both reject it. `strenv(1)`/`strenv(1;2)` -- the shapes the rewind
/// exists for -- must still reach the resolver.
#[test]
fn test_strenv_rewind_keeps_empty_parens_a_syntax_error_2807() -> Result<()> {
    for filter in [
        "def strenv: 1; strenv()",
        "def strenv: 1; strenv( )",
        "strenv()",
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some("null"))?;
        assert_ne!(code, 0, "{filter}: stdout: {stdout:?} stderr: {stderr:?}");
        assert_eq!(stdout, "", "{filter}");
    }
    let (stdout, stderr, code) = run_jq_full(&["-c", "def strenv(a): a; strenv(1)"], Some("null"))?;
    assert_eq!(code, 0, "stdout: {stdout:?} stderr: {stderr:?}");
    assert_eq!(stdout.trim_end(), "1");
    Ok(())
}

/// #2807 (review): the residual this fix does **not** close -- `limit`, `nth`
/// and `skip` parse their first argument with the comma-restricted
/// `parse_pipe_no_comma_with_booleans`, so a comma there leaves the
/// already-parsed prefix out of step with the real argument text and nothing
/// can be handed over. Those calls still reach
/// `retry_shadow_candidate_as_generic_call` and still spend the budget, so 65
/// of them are still rejected where jq 1.7.1 answers `130`.
///
/// Characterization, not an endorsement: this is a residual of #2807's class,
/// not a regression -- the pre-#2807 parser rejected these at every count, and
/// 64 still pass here. Tracked as #2863; when that lands these rows flip to
/// jq's answers.
#[test]
fn test_comma_restricted_first_arg_still_spends_the_retry_budget_2807() -> Result<()> {
    for kw in ["nth", "limit", "skip"] {
        let within = format!(
            "def {kw}(a;b): a; [{}] | length",
            vec![format!("{kw}(1,2;3)"); 64].join(",")
        );
        let (stdout, stderr, code) = run_jq_full(&["-c", &within], Some("null"))?;
        assert_eq!(code, 0, "{kw} x64: stdout: {stdout:?} stderr: {stderr:?}");
        assert_eq!(stdout.trim_end(), "128", "{kw} x64");

        let past = format!(
            "def {kw}(a;b): a; [{}] | length",
            vec![format!("{kw}(1,2;3)"); 65].join(",")
        );
        let (stdout, stderr, code) = run_jq_full(&["-c", &past], Some("null"))?;
        assert_eq!(code, 3, "{kw} x65: stdout: {stdout:?} stderr: {stderr:?}");
        // `nth`/`skip` report the hand-over helper's own separator
        // complaint, `limit` its dedicated parser's -- both are the raw
        // `original_err` the exhausted budget lets through, which is the
        // property under test, not the wording.
        assert!(
            stderr.contains("parse error"),
            "{kw} x65: stderr: {stderr:?}"
        );
    }
    Ok(())
}

/// #2807: an *unshadowed* wrong-arity call to one of the converted builtins
/// now reaches jq's own name/arity resolver instead of stopping at the
/// parser's argument-boundary check -- #2573's MULTI-ARG remainder, the same
/// direction #2110/#2237/#2686 already took for the zero-arity,
/// single-argument and special-form families.
///
/// Every expectation captured from `/usr/bin/jq` 1.7.1. The `strenv` rows
/// cover the one arm whose argument is a bare identifier rather than an
/// expression, so it rewinds rather than handing parsed arguments over; the
/// `test`/`split` no-parens rows cover the before-any-argument checkpoint.
#[test]
fn test_wrong_arity_multi_arg_builtins_resolve_by_name_and_arity_2807() -> Result<()> {
    for (filter, expected) in [
        ("test(1;2;3)", "test/3 is not defined"),
        ("match(1;2;3)", "match/3 is not defined"),
        ("capture(1;2;3)", "capture/3 is not defined"),
        ("sub(1;2;3;4)", "sub/4 is not defined"),
        ("gsub(1;2;3;4)", "gsub/4 is not defined"),
        ("scan(1;2;3)", "scan/3 is not defined"),
        ("splits(1;2;3)", "splits/3 is not defined"),
        ("split(1;2;3)", "split/3 is not defined"),
        ("IN(1;2;3)", "IN/3 is not defined"),
        ("INDEX(1;2;3)", "INDEX/3 is not defined"),
        ("setpath(1)", "setpath/1 is not defined"),
        ("pow(1)", "pow/1 is not defined"),
        ("atan2(1)", "atan2/1 is not defined"),
        ("skip(1)", "skip/1 is not defined"),
        ("nth(1;2;3)", "nth/3 is not defined"),
        ("at_position(1)", "at_position/1 is not defined"),
        ("strenv(1;2)", "strenv/2 is not defined"),
        ("strenv(1)", "strenv/1 is not defined"),
        ("all(1;2;3)", "all/3 is not defined"),
        ("any(1;2;3)", "any/3 is not defined"),
        ("flatten(1;2)", "flatten/2 is not defined"),
        ("path(1;2)", "path/2 is not defined"),
        ("paths(1;2)", "paths/2 is not defined"),
        ("recurse(1;2;3)", "recurse/3 is not defined"),
        ("combinations(1;2)", "combinations/2 is not defined"),
        ("debug(1;2)", "debug/2 is not defined"),
        ("halt_error(1;2)", "halt_error/2 is not defined"),
        ("parent(1;2)", "parent/2 is not defined"),
        ("test", "test/0 is not defined"),
        ("split", "split/0 is not defined"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some("null"))?;
        assert_eq!(code, 3, "{filter}: stdout: {stdout:?} stderr: {stderr:?}");
        assert!(stderr.contains(expected), "{filter}: stderr: {stderr:?}");
    }
    Ok(())
}

/// #2807: a shadowed wrong-arity call nested to depth 30 must stay flat.
///
/// The budget bounded the `O(2^depth)` reparse rather than removing it, so
/// before this fix these rejected the program once the budget ran out
/// instead of taking exponential time; with the arms resolving their calls
/// in place there is no reparse to bound and every row answers jq's own `1`.
/// Same generous margin and reasoning as
/// `test_wrong_arity_deep_nesting_does_not_blow_up_2686`'s table.
#[test]
fn test_shadowed_multi_arg_deep_nesting_stays_flat_2807() -> Result<()> {
    for (kw, params, tail) in [
        ("test", "a;b;c", ";2;3"),
        ("match", "a;b;c", ";2;3"),
        ("setpath", "a;b;c", ";2;3"),
        ("any", "a;b;c", ";2;3"),
        ("sub", "a;b;c;d", ";2;3;4"),
        ("nth", "a;b;c", ";2;3"),
        ("recurse", "a;b;c", ";2;3"),
    ] {
        let depth = 30;
        let mut nested = String::from("1");
        for _ in 0..depth {
            nested = format!("{kw}({nested}{tail})");
        }
        let filter = format!("def {kw}({params}): a; {nested}");
        let start = std::time::Instant::now();
        let (stdout, stderr, code) = run_jq_full(&["-c", &filter], Some("null"))?;
        let elapsed = start.elapsed();
        assert_eq!(
            code, 0,
            "`{kw}` at {depth} levels: stdout: {stdout:?} stderr: {stderr:?}"
        );
        assert_eq!(stdout.trim_end(), "1", "`{kw}` at {depth} levels");
        assert!(
            elapsed < std::time::Duration::from_secs(15),
            "`{kw}` at {depth} levels took {elapsed:?} -- exponential parse blowup regressed"
        );
    }
    Ok(())
}

/// #2686: the no-re-parse path must resolve a wrong-arity call to exactly
/// what the rewinding path did — same message, same shadow resolution, same
/// postfix handling.
///
/// Verified in bulk while making the change: 855 programs across all eight
/// special forms × both modes (1710 pairs) — every argument count from 0 to
/// 5, malformed separators, `def`-shadowed spellings, postfix chains,
/// namespaced calls and nesting — produced byte-identical stdout, stderr and
/// exit code against a binary built from the merge base. These rows are the
/// load-bearing ones from that sweep, kept so the parity is pinned rather
/// than only having been measured once.
#[test]
fn test_wrong_arity_resolution_is_unchanged_2686() -> Result<()> {
    for (filter, want_code, want_fragment) in [
        // The resolver's own name/arity diagnostic, not a raw parse error.
        ("until(1;2;3)", 3, "until/3 is not defined"),
        ("limit(1;2;3)", 3, "limit/3 is not defined"),
        ("limit(1)", 3, "limit/1 is not defined"),
        ("first(1;2)", 3, "first/2 is not defined"),
        ("last(1;2)", 3, "last/2 is not defined"),
        ("while(1;2;3)", 3, "while/3 is not defined"),
        ("repeat(1;2)", 3, "repeat/2 is not defined"),
        ("range(1;2;3;4)", 3, "range/4 is not defined"),
        ("error(1;2)", 3, "error/2 is not defined"),
        // #2237's postfix tail: a suffix after the wrong-arity call must
        // still reach the resolver rather than becoming a syntax error.
        ("range(1;2;3;4).foo", 3, "range/4 is not defined"),
        ("until(1;2;3)[0]", 3, "until/3 is not defined"),
        // A malformed separator inside the *continued* argument list -- the
        // part this fix now parses itself rather than re-parsing -- keeps
        // `parse_func_call_or_error`'s own wording and position.
        (
            "until(1;2;3 4)",
            3,
            "expected ';' or ')' in function arguments",
        ),
        (
            "first(1;2 3)",
            3,
            "expected ';' or ')' in function arguments",
        ),
        (
            "range(1;2;3;4 5)",
            3,
            "expected ';' or ')' in function arguments",
        ),
        (
            "until(1;2;3]",
            3,
            "expected ';' or ')' in function arguments",
        ),
    ] {
        let (_stdout, stderr, code) = run_jq_full(&["-nc", filter], None)?;
        assert_eq!(code, want_code, "`{filter}`: stderr {stderr:?}");
        assert!(
            stderr.contains(want_fragment),
            "`{filter}`: stderr {stderr:?} lacks {want_fragment:?}"
        );
    }

    // A `def` of the same name and arity still shadows -- the whole reason
    // the wrong-arity path resolves as a generic call instead of raising.
    for (filter, want) in [
        ("def until(a;b;c): 42; until(1;2;3)", "42"),
        ("def first(a;b): [a,b]; first(1;2)", "[1,2]"),
        ("def range(a;b;c;d): 9; range(1;2;3;4)", "9"),
        ("def limit(a): a; limit(7)", "7"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-nc", filter], None)?;
        assert_eq!(code, 0, "`{filter}`: stderr {stderr:?}");
        assert_eq!(stdout.trim_end(), want, "`{filter}`");
    }

    // Correct-arity calls are untouched.
    for (filter, want) in [
        ("[limit(2; 1,2,3)]", "[1,2]"),
        ("[range(1;5;2)]", "[1,3]"),
        ("[range(3)]", "[0,1,2]"),
        ("1 | until(. > 3; . + 1)", "4"),
        ("[first(1,2)]", "[1]"),
        ("[last(1,2)]", "[2]"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-nc", filter], None)?;
        assert_eq!(code, 0, "`{filter}`: stderr {stderr:?}");
        assert_eq!(stdout.trim_end(), want, "`{filter}`");
    }

    Ok(())
}

/// #2669: every route to `and`/`or` now agrees on a malformed document,
/// which is #2692's rule applied to the one route that still had the old
/// behaviour.
///
/// #2692 removed `push_generic_document_validation_error` from `and`/`or`'s
/// behalf, deciding that *testing* a value does not read it. The lazy arms
/// took that immediately, but the collecting entry points kept the eager
/// operand strategy, whose `push_generic_truthiness` still ran the walk per
/// item — so on `{"a":1,}` the identical expression answered differently
/// depending only on which consumer wrapped it. Measured on `main` before
/// this change:
///
/// | filter | main | now |
/// |---|---|---|
/// | `(.,.) and true` (bare) | `true` `true` | `true` `true` |
/// | `first((.,.) and true)` | `true` | `true` |
/// | `[limit(2; (.,.) and true)]` | `[true,true]` | `[true,true]` |
/// | `[(.,.) and true]` | **exit 5** | `[true,true]` |
///
/// Three of the four already accepted; #2669 moved the fourth to join them
/// rather than the reverse, because that is the direction #2692 chose. Real
/// jq rejects **all four** — it cannot parse the document at all — so this is
/// the pre-existing #2692 divergence being applied consistently, not a new
/// one, and it is the reason the switch is not purely a stderr-ordering
/// change. The open question of whether truthiness-only reads should
/// validate at all is #2701; this test pins only that the routes agree.
#[test]
fn test_boolean_routes_agree_on_a_malformed_document_2669() -> Result<()> {
    for doc in [r#"{"a":1,}"#, "{,}", "[1,]", r#"{"a":1,,"b":2}"#] {
        // Every spelling of the same expression, one per route.
        for (filter, want) in [
            ("(.,.) and true", "true\ntrue"),
            ("first((.,.) and true)", "true"),
            ("[limit(2; (.,.) and true)]", "[true,true]"),
            ("[(.,.) and true]", "[true,true]"),
            ("[(.,.) and true] | length", "2"),
            ("[(.,.) or false]", "[true,true]"),
        ] {
            let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(doc))?;
            assert_eq!(
                code, 0,
                "doc={doc} `{filter}`: every route must agree (#2692's rule): {stderr:?}"
            );
            assert_eq!(stdout.trim_end(), want, "doc={doc} `{filter}`");
        }
    }

    // The guard on the other side: a route that genuinely *reads* the
    // document still raises on the same input, so this is not a blanket
    // "and/or suppresses validation everywhere" change.
    for (filter, doc) in [(".a and true", r#"{"a":1,}"#), ("[.a] and true", "{,}")] {
        let (_stdout, stderr, code) = run_jq_full(&["-c", filter], Some(doc))?;
        assert_ne!(
            code, 0,
            "`{filter}` on {doc}: reading a member must still raise"
        );
        assert!(
            stderr.contains("Invalid JSON text"),
            "`{filter}` on {doc}: stderr {stderr:?}"
        );
    }

    Ok(())
}

/// #2132: an evaluator-imposed resource cap is **uncatchable** -- never
/// suppressed by `?`, never handed to `catch` -- under all three spellings,
/// for every guard.
///
/// These caps (`MAX_RANGE`, `WHILE_UNTIL_MAX_STEPS`, `REDUCE_FOREACH_MAX_STEPS`,
/// `repeat`'s `MAX_ITERATIONS`, `MAX_EVAL_FRAMES`) are succinctly's own, with
/// no jq counterpart: `[range(100001)?] | length` is `100001` in jq 1.7.1,
/// which has no cap at all. A `?`/`try` written against jq semantics cannot
/// have meant "accept a truncated result", so letting the catch swallow the
/// cap reopened the silent-wrong-data class #2089 closed for the
/// un-suppressed spelling. Measured before this fix:
/// `[range(100001)?] | length` answered `100000` at exit 0,
/// `[try range(100001) catch "caught"] | length` answered `100001` (prefix
/// plus the handler's value), and `def f: f; try f catch "caught"` answered
/// `"caught"`.
///
/// Under ADR-0018's decision order this is rule 4(b) -- matching the
/// reference's catch semantics for an error it cannot raise would corrupt
/// data -- and it is `ErrorKind::ResourceLimit` riding the same uncatchable
/// machinery as a decode failure (#1840), not a `Control::Halt`: the CLI
/// still prints it and exit-codes it as an ordinary error (5), and it still
/// flows through `Partial` so the prefix streamed before the cap reaches
/// stdout, exactly as #2089 established.
#[test]
fn test_resource_limit_caps_are_uncatchable_2132() -> Result<()> {
    for (label, expr, want_err) in [
        (
            "MAX_RANGE",
            "range(100001)",
            "range: maximum iterations exceeded",
        ),
        (
            "WHILE_UNTIL_MAX_STEPS/while",
            "while(true; .+1)",
            "while: maximum iterations exceeded",
        ),
        (
            "WHILE_UNTIL_MAX_STEPS/until",
            "until(false; .+1)",
            "until: maximum iterations exceeded",
        ),
        // Genuine fan-out past the shared reduce/foreach budget -- the same
        // shape `test_reduce_budget_exceeded_errors` uses: two INIT forks
        // over a 50,001-element source is 100,002 UPDATE evaluations.
        (
            "REDUCE_FOREACH_MAX_STEPS/reduce",
            "reduce range(50001) as $x ((0,1); .+$x)",
            "reduce: maximum iterations exceeded",
        ),
        (
            "REDUCE_FOREACH_MAX_STEPS/foreach",
            "foreach range(50001) as $x ((0,1); .+$x; empty)",
            "foreach: maximum iterations exceeded",
        ),
        (
            "repeat MAX_ITERATIONS",
            "repeat(.)",
            "repeat: maximum iterations exceeded",
        ),
        (
            "MAX_EVAL_FRAMES",
            "def f: f; f",
            "f/0 exceeded maximum recursion depth",
        ),
        (
            "MAX_EVAL_FRAMES, generator",
            "def f: 1, f; f",
            "f/0 exceeded maximum recursion depth",
        ),
    ] {
        for spelling in [
            format!("[{expr}?] | length"),
            format!("[try ({expr})] | length"),
            format!("[try ({expr}) catch \"caught\"] | length"),
        ] {
            let (stdout, stderr, code) = run_jq_full(&["-c", &spelling], Some("null"))?;
            assert_eq!(
                code, 5,
                "[{label}] `{spelling}`: the cap must not be caught -- stdout {stdout:?} stderr {stderr:?}"
            );
            assert!(
                stderr.contains(want_err),
                "[{label}] `{spelling}`: stderr {stderr:?} lacks {want_err:?}"
            );
            assert!(
                !stdout.contains("caught"),
                "[{label}] `{spelling}`: the handler ran: {stdout:?}"
            );
        }
    }

    Ok(())
}

/// #2132: the prefix a generator streamed before hitting its cap is still
/// printed -- the cap is an error that ends the stream, not one that
/// retroactively discards it. Bare (not inside a `[...]` collector) so the
/// prefix is observable on stdout, with the cap's error on stderr after it.
#[test]
fn test_resource_limit_prefix_still_streams_before_the_cap_2132() -> Result<()> {
    for (spelling, want_last_line, want_err) in [
        (
            "range(100001)?",
            "99999",
            "range: maximum iterations exceeded",
        ),
        (
            "try range(100001)",
            "99999",
            "range: maximum iterations exceeded",
        ),
        (
            "try range(100001) catch \"caught\"",
            "99999",
            "range: maximum iterations exceeded",
        ),
        // `reduce` emits its first fork's result before the second exhausts
        // the shared budget.
        (
            "try (reduce range(50001) as $x ((0,1); .+$x)) catch \"caught\"",
            "1250025000",
            "reduce: maximum iterations exceeded",
        ),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", spelling], Some("null"))?;
        assert_eq!(code, 5, "`{spelling}`: stderr {stderr:?}");
        assert_eq!(
            stdout.trim_end().lines().last().unwrap_or(""),
            want_last_line,
            "`{spelling}`: the prefix must still stream: {}",
            stdout.len()
        );
        assert!(stderr.contains(want_err), "`{spelling}`: stderr {stderr:?}");
        assert!(!stdout.contains("caught"), "`{spelling}`: {stdout:?}");
    }

    Ok(())
}

/// #2132: what the fix must **not** change, each row captured live from jq
/// 1.7.1.
///
/// - An ordinary error under `?`/`try` keeps the prefix and catches the
///   terminal error -- jq's own semantics, which succinctly already matched.
///   The issue's broad reading ("discard what already came out") would have
///   been a divergence, not a fix.
/// - An early-stopping consumer never reaches the cap, so `?` has nothing
///   to see: `[limit(5; range(100001))?]` is unaffected.
/// - A user's own `error(..)` whose *message* happens to match a cap's is
///   still catchable -- the tag decides, not the text, which is #1660's
///   lesson and the reason `ErrorKind` exists.
#[test]
fn test_resource_limit_tag_leaves_ordinary_errors_catchable_2132() -> Result<()> {
    for (filter, want) in [
        (r#"[(1,2,error("x"),3)?]"#, "[1,2]"),
        (r#"[try (1,2,error("x"),3) catch "c"]"#, r#"[1,2,"c"]"#),
        ("[limit(5; range(100001))?]", "[0,1,2,3,4]"),
        ("[limit(3; repeat(.)?)]", "[null,null,null]"),
        ("first(repeat(1)?)", "1"),
        (
            r#"try error("range: maximum iterations exceeded") catch "user""#,
            r#""user""#,
        ),
        (
            r#"try error("f/0 exceeded maximum recursion depth") catch "user""#,
            r#""user""#,
        ),
        (
            r#"[error("repeat: maximum iterations exceeded")?] | length"#,
            "0",
        ),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some("null"))?;
        assert_eq!(code, 0, "`{filter}`: stderr {stderr:?}");
        assert_eq!(stdout.trim_end(), want, "`{filter}`");
    }

    Ok(())
}

/// #2132, second half (review finding): the `?//` destructuring-alternative
/// retry is a catch boundary too, and it was still consulting
/// `is_decode_failure()` alone -- #1620/#1660's own exclusion -- rather than
/// the shared value-position predicate. So a cap raised *inside* a `?//`
/// body read as "this alternative failed, try the next", and the truncated
/// body passed as the next alternative's clean answer: measured before the
/// fix, `[. as $x ?// $y | if $x != null then range(100002) else 1 end] |
/// length` answered `100001` at exit 0 (jq 1.7.1: `100002`).
///
/// Every `?//` site now uses `is_uncatchable_at_value_position()`, the same
/// predicate the six `?`/`try` dispatch points already did: eager
/// (`try_pattern_alternatives`), streaming (`each_pattern_alternatives` and
/// its generic twin), and the `reduce`/`foreach` source form
/// (`is_retryable_control`). `suppresses`, the ambient-`?` rule every fold
/// construct shares, was the last one spelling a member out by hand and is
/// on the same predicate now.
#[test]
fn test_resource_limit_is_not_a_destructuring_retry_2132() -> Result<()> {
    for (label, doc, filter, want_err) in [
        (
            "eager ?//, range",
            "1",
            "[. as $x ?// $y | if $x != null then range(100002) else 1 end] | length",
            "range: maximum iterations exceeded",
        ),
        (
            "eager ?//, recursion",
            "1",
            "[. as $x ?// $y | if $x != null then (def f: f; f) else 1 end]",
            "f/0 exceeded maximum recursion depth",
        ),
        (
            "streaming ?// under limit",
            "[[1]]",
            "[limit(300000; .[] as [$y] ?// $z | if $y != null then range(100002) else $z end)] | length",
            "range: maximum iterations exceeded",
        ),
        (
            "reduce source ?//",
            "null",
            "[reduce (1,2) as $x ?// $y (0; if $x != null then range(100002) else 1 end)]",
            "range: maximum iterations exceeded",
        ),
        (
            "foreach source ?//",
            "null",
            "[foreach (1,2) as $x ?// $y (0; if $x != null then range(100002) else 1 end; .)] | length",
            "foreach: maximum iterations exceeded",
        ),
        (
            "ambient ? over a fold (suppresses)",
            "null",
            "[(reduce range(50001) as $x ((0,1); .+$x))?] | length",
            "reduce: maximum iterations exceeded",
        ),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(doc))?;
        assert_eq!(code, 5, "[{label}] `{filter}`: stdout {stdout:?} stderr {stderr:?}");
        assert!(stderr.contains(want_err), "[{label}] stderr {stderr:?}");
    }

    // Ordinary errors inside a `?//` body still fall through to the next
    // alternative -- jq's own rule, each row captured from jq 1.7.1.
    for (doc, filter, want) in [
        (
            "[1]",
            r#". as [$a] ?// $b | if $a != null then error("x") else "second" end"#,
            r#""second""#,
        ),
        ("[1]", "[1] as [$a] ?// $b | $b", "null"),
        ("[[1,2]]", ".[] as [$a] ?// [$b] | [$a,$b]", "[1,null]"),
    ] {
        let (stdout, stderr, code) = run_jq_full(&["-c", filter], Some(doc))?;
        assert_eq!(code, 0, "`{filter}`: stderr {stderr:?}");
        assert_eq!(stdout.trim_end(), want, "`{filter}`");
    }

    Ok(())
}

/// #2710: which spelling an undecodable key echoes is decided by **whether
/// the value is materialized**, and nothing else — so the boundary is worth
/// pinning in CI rather than only in the sweep.
///
/// `docs/compliance/jq/limitations.md` has stated the rule since #2103: raw
/// source bytes wherever the value is never materialized,
/// `key_display_string`'s fallback (the source `\` doubled) wherever it is.
/// #2710 found `scripts/jq-m2-streaming-sweep.expected` recording the
/// *doubled* spelling for `. as $x | $x` while the binary emitted the raw
/// one, and asked which side was right.
///
/// **The binary is.** A plain `$x` reference forwards the cursor rather than
/// materializing, so the raw spelling is what the rule already prescribes —
/// the rule needs no narrowing, and the drift was the golden going stale
/// against a route that became a passthrough. Measured across the boundary,
/// input `{"a\q":1,"b":2}`:
///
/// | raw (never materialized) | doubled (materialized) |
/// |---|---|
/// | `.`, `. \| .`, `first(.)` | `[.] \| .[0]`, `[.] as [$x] \| $x` |
/// | `. as $x \| $x`, `. as {a:$v} \| .` | `. as $x \| [$x] \| .[0]` |
/// | `if . then . else . end` | `. as $x \| $x + {}`, `tojson` |
/// | `getpath([])`, `(., .) \| first(.)` | `to_entries`, `keys`, `with_entries(.)` |
///
/// Every raw row forwards a cursor; every doubled row builds an
/// `OwnedValue`. There is no filter on either side that contradicts the
/// rule, which is what makes "the rule stands, the golden was stale" the
/// answer rather than "the wording needs narrowing".
///
/// jq 1.7.1 has no opinion to appeal to: it rejects both documents at parse
/// time (`Invalid \uXXXX\uXXXX surrogate pair`, `Invalid escape`), so this
/// is succinctly's own documented rule, not a fidelity question.
///
/// The sweep is a verification tool, not a CI gate — which is how the drift
/// went unnoticed until #2692 regenerated the golden over it. These rows are
/// the CI-gated half, so the next such drift fails a build rather than
/// waiting for someone to run the sweep and read a 154-row `--update`.
#[test]
fn test_undecodable_key_spelling_follows_materialization_2710() -> Result<()> {
    for doc in [r#"{"a\q":1,"b":2}"#, r#"{"\ud800":1,"b":2}"#] {
        // The raw spelling is the document's own bytes back. Asserted per
        // output line, not on the whole stdout: a multi-output row like
        // `(., .) | first(.)` legitimately emits it twice, and the claim
        // here is about the spelling, not the cardinality.
        for filter in [
            ".",
            ". | .",
            ". as $x | $x",
            ". as $x | $x | .",
            ". as {a:$v} | .",
            "if . then . else . end",
            "getpath([])",
            "first(.)",
            "(., .) | first(.)",
        ] {
            let (out, err, code) = run_jq_full(&["-c", filter], Some(doc))?;
            assert_eq!(code, 0, "`{filter}` on {doc}: stderr {err:?}");
            let lines: Vec<&str> = out.lines().collect();
            assert!(!lines.is_empty(), "`{filter}` produced nothing");
            for line in lines {
                assert_eq!(
                    line, doc,
                    "`{filter}` forwards a cursor, so it must echo the raw source bytes"
                );
            }
        }

        // ... and a materializing route doubles the source `\`.
        let doubled = doc.replace('\\', "\\\\");
        for filter in [
            "[.] | .[0]",
            "[.] as [$x] | $x",
            ". as $x | [$x] | .[0]",
            ". as $x | $x + {}",
            "with_entries(.)",
        ] {
            let (out, err, code) = run_jq_full(&["-c", filter], Some(doc))?;
            assert_eq!(code, 0, "`{filter}` on {doc}: stderr {err:?}");
            let lines: Vec<&str> = out.lines().collect();
            assert!(!lines.is_empty(), "`{filter}` produced nothing");
            for line in lines {
                assert_eq!(
                    line, doubled,
                    "`{filter}` materializes, so it must use key_display_string's fallback"
                );
            }
        }
    }

    Ok(())
}

/// #2698: `range`'s bounds are evaluated from the cursor, not from a
/// materialized copy of the document.
///
/// The win is memory (2022 MB -> 105 MB on a 77 MB input, for a root whose
/// `length` is 9), which a CLI test cannot assert cheaply. What it *can*
/// assert is the half that would silently break if the native arm got the
/// semantics wrong: `range` is a fan-out generator whose bounds are
/// themselves generators, and the arm it replaced was chosen (#2180 WP2b)
/// precisely for that behaviour. Every row is captured from jq 1.7.1.
#[test]
fn range_bounds_keep_their_fanout_semantics_2698() -> Result<()> {
    // (filter, input, expected stdout)
    let rows = [
        // The row #2180 WP2b's own comment records -- a `?//` alternative in
        // the `from` position. The eager fallback answered `[1]` here.
        ("[first(range((1 as $x ?// $y | 1); 3))]", "1", "[1,1]"),
        // Each bound position fans out, and the nesting order is
        // from-major, then to, then step.
        ("[range((1,2);4)]", "null", "[1,2,3,2,3]"),
        ("[range(1;(3,5))]", "null", "[1,2,1,2,3,4]"),
        ("[range(1;5;(1,2))]", "null", "[1,2,3,4,1,3]"),
        // A bound that reads the document -- the shape this change is about.
        ("[range(length)]", "[7,8,9]", "[0,1,2]"),
        ("[first(range(length;3))]", "[7,8,9]", "[]"),
        ("last(range(length))", "[7,8,9]", "2"),
        ("[range(0;length)]", "[7,8,9]", "[0,1,2]"),
        ("reduce range(length) as $x (0; .+$x)", "[7,8,9]", "3"),
        ("[limit(2; range(length))]", "[7,8,9,10,11]", "[0,1]"),
        // Float and descending paths through the same arm.
        ("[range(0;1;0.3)]", "null", "[0,0.3,0.6,0.8999999999999999]"),
        ("[range(5;0;-1)]", "null", "[5,4,3,2,1]"),
        // Degenerate bounds still produce nothing rather than erroring.
        ("[range(0;0)]", "null", "[]"),
        ("[range(3;1)]", "null", "[]"),
        ("[range(0;3;0)]", "null", "[]"),
    ];
    for (filter, input, want) in rows {
        let (out, err, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(
            (out.trim(), code),
            (want, 0),
            "#2698: `{filter}` on {input} -- stderr: {err:?}"
        );
    }
    Ok(())
}

/// #2698: a non-numeric bound raises, in each of the three positions -- the
/// `step` position is the one no other test reached (it is the innermost
/// closure of `each_range_generic`, so a bad `from` or `to` never gets
/// there).
///
/// The `from`/`to` message matches jq 1.7.1 ("Range bounds must be
/// numeric"). The `step` one does not: jq adds the step first and reports
/// `number (0) and string ("a") cannot be added`, while succinctly's
/// `range_num` rejects all three positions with the same bounds message.
/// That divergence predates this change -- the old bridge route answered
/// identically -- so this row pins succinctly's existing behaviour rather
/// than jq's, and is not a claim of fidelity.
#[test]
fn range_rejects_a_non_numeric_bound_in_every_position_2698() -> Result<()> {
    for filter in ["[range(\"a\";3)]", "[range(0;\"b\")]", "[range(0;3;\"c\")]"] {
        let (_, err, code) = run_jq_full(&["-c", filter], Some("null"))?;
        assert_ne!(code, 0, "#2698: `{filter}` must raise");
        assert!(
            err.contains("Range bounds must be numeric"),
            "#2698: `{filter}` -- stderr: {err:?}"
        );
    }
    Ok(())
}

/// #2698: a `range` bound validates only what it reads -- the #2103/#2173
/// divergence, one construct over, recorded in `limitations.md`.
///
/// The fault is a bad escape inside a *leaf value*, which `length` and `.b`
/// never decode. That choice is the whole test: a structural fault at the
/// root (`{123:1}`) is read by `length` itself and raises on every route,
/// which is exactly what the first version of this PR checked and then
/// wrongly reported as "malformed documents unchanged". Real jq 1.7.1
/// rejects this document at parse time for every filter.
#[test]
fn range_bounds_validate_only_what_they_read_2698() -> Result<()> {
    let doc = r#"{"a": "bad\x", "b": 5}"#;

    // Reads the key count / a good sibling, never the bad scalar: answers.
    for (filter, want) in [
        ("[range(length)]", "[0,1]"),
        ("first(range(length))", "0"),
        ("[range(.b)]", "[0,1,2,3,4]"),
        ("reduce range(length) as $x (0;.+$x)", "1"),
        ("last(range(0;.b))", "4"),
    ] {
        let (out, err, code) = run_jq_full(&["-c", filter], Some(doc))?;
        assert_eq!(
            (out.trim(), code),
            (want, 0),
            "#2698: `{filter}` -- stderr: {err:?}"
        );
    }

    // The other half, which keeps this from being a hole: a bound that DOES
    // read the malformed scalar still raises, exactly as `.a | length` does.
    // (Not bare `.a`: in jq mode that streams the raw bytes through as
    // `"bad\x"` without decoding them -- the M2 passthrough, pre-existing
    // and identical on both binaries -- so it is not a "reads the scalar"
    // control here the way it is in yq mode's #2626 twin.)
    for filter in [
        ".a | length",
        "[.a]",
        "[range(.a|length)]",
        "first(range(.a|length))",
    ] {
        let (_, err, code) = run_jq_full(&["-c", filter], Some(doc))?;
        assert_ne!(
            code, 0,
            "#2698: `{filter}` must still raise -- stderr: {err:?}"
        );
        assert!(
            err.contains("invalid escape"),
            "#2698: `{filter}` -- stderr: {err:?}"
        );
    }
    Ok(())
}

/// #2698 keeps #2089's `MAX_RANGE` rule: truncation raises only once a
/// consumer has taken the whole capped batch and still wants more.
///
/// This is the rule most at risk from moving where the bounds are evaluated,
/// because it depends on what the *sink* does, not on the bounds -- and the
/// native arm now owns both sides of that conversation. Real jq has no cap
/// and would try to build 10^18 elements here, so there is no oracle row:
/// these pin succinctly's own documented divergence.
#[test]
fn range_max_iterations_rule_survives_the_native_arm_2698() -> Result<()> {
    // A demand-driven consumer stops inside the capped batch and never sees
    // the truncation.
    let (out, _, code) = run_jq_full(&["-c", "first(range(1e18))"], Some("null"))?;
    assert_eq!((out.trim(), code), ("0", 0));
    let (out, _, code) = run_jq_full(&["-c", "[limit(3; range(1e18))]"], Some("null"))?;
    assert_eq!((out.trim(), code), ("[0,1,2]", 0));

    // An unbounded one takes everything and must raise rather than silently
    // return a 100000-element prefix.
    for filter in ["[range(1e18)]", "reduce range(1e18) as $x (0;.+$x)"] {
        let (_, err, code) = run_jq_full(&["-c", filter], Some("null"))?;
        assert_ne!(
            code, 0,
            "#2698: `{filter}` must raise, not truncate silently"
        );
        assert!(
            err.contains("maximum iterations exceeded"),
            "#2698: `{filter}` -- stderr: {err:?}"
        );
    }
    Ok(())
}

/// #2666: `map(f) | .[]` is atomic outside a truncating consumer, exactly as
/// in jq -- a failing element discards every element `map` already
/// produced, because real jq builds the whole array before `.[]` can
/// observe it. Before this, every spelling that reached
/// `each_lazy_seq_iterate_sink` through the generic evaluator leaked the
/// prefix `2` to stdout before raising.
///
/// The table is the whole of #2666's §0, in three blocks, and every row is
/// one assertion on `(stdout, exit code)`. The **must-preserve** block carries
/// the *divergent* literal on purpose: `first`/`limit(1)`/`.[0]`/`nth(0)`
/// over a `LazySeq` pull one element and stop (#725, #1565), and that is
/// the deliberate, recorded trade this fix keeps -- so the boundary is
/// pinned in both directions, not just the direction that moved. Real jq
/// 1.7.1 exits 5 with no output on every one of those.
///
/// Two rows the plan listed as must-preserve now match jq instead --
/// `first(try (map(.+1)|.[]) catch "c")` and `first((map(.+1)|.[]) // 0)`
/// -- because the atomic default applies inside `try`/`//` before any
/// `forward` opt-in. That is fidelity gained for free, so they sit in the
/// first block.
#[test]
fn test_map_iterate_atomicity_outside_truncators_2666() -> Result<()> {
    let input = r#"[1,"x",3]"#;

    // Block 1 -- matches jq: no output, and the exit code jq gives.
    let match_jq: &[(&str, &str, i32)] = &[
        ("map(.+1) | .[]", "", 5),
        ("map(.+1)[]", "", 5),
        (". as $a | $a | map(.+1) | .[]", "", 5),
        ("map(.+1) | .[] | select(.>1)", "", 5),
        ("map(.+1) | .[] | tostring", "", 5),
        ("map(.+1) | map(.+1) | .[]", "", 5),
        // The comma's own left branch still emits; only the leak is gone.
        ("99, (map(.+1) | .[])", "99", 5),
        ("foreach (map(.+1)|.[]) as $x (0; .+$x)", "", 5),
        // The escape happens before anything is emitted, so `try` sees an
        // error and no output -- jq's own answer.
        (r#"try (map(.+1)|.[]) catch "caught""#, r#""caught""#, 0),
        ("(map(.+1)|.[])?", "", 0),
        ("(map(.+1) | .[]) as $x | $x", "", 5),
        ("def f: map(.+1) | .[]; f", "", 5),
        ("if true then (map(.+1)|.[]) else 0 end", "", 5),
        ("(map(.+1)|.[]) // 0", "", 5),
        // `limit(n)` with n >= the array's length pulls the whole window, so
        // the failing third element is inside it -- the row a boolean flag
        // could never get right.
        ("limit(2; map(.+1) | .[])", "", 5),
        ("limit(3; map(.+1) | .[])", "", 5),
        // Gained for free (see the doc comment).
        (r#"first(try (map(.+1)|.[]) catch "c")"#, r#""c""#, 0),
        ("first((map(.+1)|.[]) // 0)", "", 5),
        // Already atomic before this change; must not regress.
        ("[map(.+1)|.[]]", "", 5),
        ("map(.+1)|last", "", 5),
        ("map(.+1)|length", "", 5),
        ("reduce (map(.+1)|.[]) as $x (0;.+$x)", "", 5),
        ("isempty(map(.+1)|.[])", "", 5),
        ("any(map(.+1)|.[]; .>1)", "", 5),
        ("first(map(.+1) | .[] | select(.>2))", "", 5),
        ("first(map(.+1) | .[] , 9)", "", 5),
        ("{a: .} | .a | map(.+1) | .[]", "", 5),
        ("{a: .} | .a | first(map(.+1) | .[])", "", 5),
    ];
    for (filter, want_out, want_code) in match_jq {
        let (out, err, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(
            (out.trim(), code),
            (*want_out, *want_code),
            "#2666: `{filter}` must match jq 1.7.1 -- stderr: {err:?}"
        );
    }

    // Block 2 -- the deliberate divergence, pinned as such: one element is
    // pulled and the consumer stops before the failing one is ever reached.
    // jq: exit 5, no output, on every row.
    let preserved: &[(&str, &str)] = &[
        ("first(map(.+1) | .[])", "2"),
        ("limit(1; map(.+1) | .[])", "2"),
        ("map(.+1) | .[0]", "2"),
        ("nth(0; map(.+1)|.[])", "2"),
    ];
    for (filter, want_out) in preserved {
        let (out, err, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(
            (out.trim(), code),
            (*want_out, 0),
            "#2666: `{filter}` is the #725/#1565 trade and must keep yielding -- stderr: {err:?}"
        );
    }
    Ok(())
}

/// #2666's table again, through the owned route (`-n --argjson`), for the
/// rows that changed: the owned evaluator was already atomic here, and the
/// point of the fix is that the two routes now agree.
#[test]
fn test_map_iterate_atomicity_owned_and_generic_agree_2666() -> Result<()> {
    for filter in [
        "$d | map(.+1) | .[]",
        "$d | (map(.+1)|.[])?",
        r#"$d | try (map(.+1)|.[]) catch "caught""#,
        "$d | limit(3; map(.+1) | .[])",
    ] {
        let (owned_out, _, owned_code) =
            run_jq_full(&["-nc", "--argjson", "d", r#"[1,"x",3]"#, filter], None)?;
        let generic_filter = filter.replacen("$d | ", "", 1);
        let (generic_out, _, generic_code) =
            run_jq_full(&["-c", &generic_filter], Some(r#"[1,"x",3]"#))?;
        assert_eq!(
            (owned_out.trim(), owned_code),
            (generic_out.trim(), generic_code),
            "#2666: owned vs generic route disagree on `{generic_filter}`"
        );
    }
    Ok(())
}

/// #2666: the two `bounded` sites the §0 table never reached, and the two
/// off-by-ones no §0 row could see -- found by #2815's review, which
/// mutation-tested each site and each `n` and watched the whole suite stay
/// green.
///
/// `limit_with_n_generic` and `nth_with_n_generic` are the *result-returning*
/// twins of the sink-driven consumers, reached only when the truncating
/// builtin's output is consumed by something that collects (`map(..)`, `+`),
/// not by the top-level driver. Their `n` is only observable through a `rest`
/// that *expands* an element into several outputs: `nth(1; .. | (.,.))` on
/// `[1,"x"]` needs two outputs, both of which come from the first element,
/// so a window of `n` (one element) yields `2` while jq's atomic `map` errors
/// -- and a window of `n + 1` reaches the failing element and errors like jq.
///
/// The `first(nth(1; ..))` row pins the composition rule: `nth` needs
/// `skip + 1` *inputs* whatever the outer bound accepts as *outputs*, so it
/// must not take `min(skip + 1, outer)`. The first version of this PR did,
/// and answered `2` there.
#[test]
fn test_bounded_result_returning_twins_and_their_n_2666() -> Result<()> {
    // (input, filter, stdout, exit) -- all captured against jq 1.7.1, which
    // is atomic on every row (exit 5, no output); the rows that yield are
    // the #725/#1565 divergence reached through the result-returning twins.
    let rows: &[(&str, &str, &str, i32)] = &[
        // limit_with_n_generic -- would error like jq with its bound removed.
        (r#"[[1,"x"]]"#, "map(limit(1; map(.+1) | .[]))", "[2]", 0),
        (r#"[1,"x"]"#, "[limit(1; map(.+1)|.[])] + [1]", "[2,1]", 0),
        // nth_with_n_generic -- same.
        (r#"[[1,"x"]]"#, "map(nth(0; map(.+1) | .[]))", "[2]", 0),
        // nth's `n + 1`: an expanding rest is the only way to see it. Top-level
        // `nth` takes the sink-driven `take_at_index_generic`; it is the
        // `map(..)`-wrapped spelling that reaches `nth_with_n_generic`, so
        // both are here.
        (r#"[1,"x"]"#, "nth(1; map(.+1)|.[] | (.,.))", "", 5),
        (r#"[[1,"x"]]"#, "map(nth(1; map(.+1)|.[] | (.,.)))", "", 5),
        // take_at_index's `skip + 1`, NOT min'd with the outer `first`.
        (r#"[1,"x"]"#, "first(nth(1; map(.+1) | .[] | (.,.)))", "", 5),
        // limit DOES compose with an outer bound: first(limit(3; ..)) pulls 1.
        (r#"[1,"x",3]"#, "first(limit(3; map(.+1)|.[]))", "2", 0),
        (r#"[1,"x",3]"#, "[limit(3; map(.+1)|.[])]", "", 5),
    ];
    for (input, filter, want_out, want_code) in rows {
        let (out, err, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(
            (out.trim(), code),
            (*want_out, *want_code),
            "#2666: `{filter}` on {input} -- stderr: {err:?}"
        );
    }
    Ok(())
}

/// #2666: `(a | b) | c` and `a | b | c` are the same jq program and must
/// answer alike -- and run alike. The parenthesised spelling routes its
/// inner pipe through `eval_each_pipe_generic`'s driver closure, which is a
/// forwarder; #2815's first version left that closure on the `Unbounded`
/// default, so `first((map(.+1) | .[]) | .+1)` drained 2M elements (13x
/// slower than the flat spelling) and answered differently on a failing
/// element. The driver now carries the outer budget via `forward`. Pinned
/// here by the answer; the timing lives in the PR's A/B table.
#[test]
fn test_parenthesised_pipe_agrees_with_flat_pipe_under_first_2666() -> Result<()> {
    let input = r#"[1,"x",3]"#;
    let flat = run_jq_full(&["-c", "first(map(.+1) | .[] | .+1)"], Some(input))?;
    let parens = run_jq_full(&["-c", "first((map(.+1) | .[]) | .+1)"], Some(input))?;
    assert_eq!(
        (flat.0.trim(), flat.2),
        (parens.0.trim(), parens.2),
        "#2666: the two spellings of one program disagree -- flat: {flat:?}, parens: {parens:?}"
    );
    // And they agree on the deliberately-divergent literal, not on an error:
    assert_eq!((flat.0.trim(), flat.2), ("3", 0));
    Ok(())
}

/// #2666: a `break` or `halt` raised by a `map` body is delivered from
/// inside the validation window through `escape_via_sink` -- the same path a
/// mid-sequence escape took before the window existed -- with nothing
/// emitted. jq agrees on every row: `map` is atomic, so a `break` on the
/// second element discards the first, and the enclosing `label` then yields
/// nothing.
#[test]
fn test_break_and_halt_inside_the_map_window_2666() -> Result<()> {
    let input = "[1,2,3]";
    for (filter, want_out, want_code) in [
        (
            "label $o | map(if . == 2 then break $o else . end) | .[]",
            "",
            0,
        ),
        (
            "[label $o | map(if . == 2 then break $o else . end) | .[]]",
            "[]",
            0,
        ),
        (
            "label $o | map(if . == 2 then halt_error else . end) | .[]",
            "",
            5,
        ),
    ] {
        let (out, err, code) = run_jq_full(&["-c", filter], Some(input))?;
        assert_eq!(
            (out.trim(), code),
            (want_out, want_code),
            "#2666: `{filter}` -- stderr: {err:?}"
        );
    }
    Ok(())
}

/// `nth_with_n_generic`'s skipped-element force, reached through the
/// result-returning twin (`map(nth(..))`): an element `nth` skips is still
/// decoded, so a `map(10/.)` that divides by zero on a skipped `[0]` raises
/// rather than being silently stepped over. The doc comment on that force
/// gives this exact shape; it had no test on this route. Matches jq 1.7.1.
#[test]
fn test_nth_result_twin_forces_skipped_elements_2666() -> Result<()> {
    let (out, err, code) = run_jq_full(
        &["-c", "map(nth(2; .[] | map(10/.)))"],
        Some("[[[1],[0],[2]]]"),
    )?;
    assert_eq!(code, 5, "stdout: {out:?} stderr: {err:?}");
    assert!(out.trim().is_empty(), "nothing may be emitted, got {out:?}");
    assert!(err.contains("cannot be divided"), "stderr: {err:?}");
    Ok(())
}

/// #2782: the owned identity route's `//` arm forced `optional = true` onto
/// its left operand -- its own comment said "errors in it suppressed, as `//`
/// does", which jq's `//` does not do: `jq -n '5 | (.a // 1)'` is `Cannot
/// index number with "a"`, exit 5, and `(1, error("x")) // 2` prints `1`
/// then exits 5 with the right side never run (both captured live from
/// 1.7.1). So a pipe that reached that arm -- one with a path-context read
/// after the `//`, here the extension builtins `key`/`parent` -- swallowed an
/// error the same pipe without the read raised. The arm runs each side as
/// stages of the pipe now, with `optional` passed through as `eval_single`'s
/// and `eval.rs`'s `//` arms already do, so the two spellings agree: the
/// oracle-checkable spelling (no read) pins the rule, the read spelling pins
/// the route.
#[test]
fn test_alternative_left_error_is_not_swallowed_on_the_identity_route_2782() -> Result<()> {
    let doc = r#"{"a":{"b":1,"c":2}}"#;
    // `.a | tostring` is a string, so `.x` on it is an error in jq -- with and
    // without the trailing read.
    for filter in [
        ".a | tostring | (.x // 1)",
        ".a | tostring | (.x // 1) | key",
    ] {
        let (out, err, code) = run_jq_full(&["-c", filter], Some(doc))?;
        assert_eq!(
            code, 5,
            "#2782: `{filter}` -- stdout: {out:?} stderr: {err:?}"
        );
        assert!(
            out.trim().is_empty(),
            "#2782: `{filter}` -- stdout: {out:?}"
        );
        assert!(
            err.contains(r#"Cannot index string with string "x""#),
            "#2782: `{filter}` -- stderr: {err:?}"
        );
    }
    // A truthy output before the error survives; the right side never runs.
    for (filter, want) in [
        (".a | ((.b, error(\"x\")) // 2)", "1"),
        (".a | ((.b, error(\"x\")) // 2) | key", "\"b\""),
    ] {
        let (out, err, code) = run_jq_full(&["-c", filter], Some(doc))?;
        assert_eq!(
            code, 5,
            "#2782: `{filter}` -- stdout: {out:?} stderr: {err:?}"
        );
        assert_eq!(out.trim(), want, "#2782: `{filter}` -- stderr: {err:?}");
        assert!(err.contains('x'), "#2782: `{filter}` -- stderr: {err:?}");
    }
    // Each output of a multi-output left side stands at its own node, in jq
    // mode as in yq mode (`(.a, .b) // 9 | key` was `"a"`, `"a"` before).
    let (out, err, code) = run_jq_full(&["-c", ".a | ((.b, .c) // 9) | key"], Some(doc))?;
    assert_eq!(
        (out.trim(), code),
        ("\"b\"\n\"c\"", 0),
        "#2782 -- stderr: {err:?}"
    );
    // And the operator stays lazy under a bounded consumer: `first` pulls one
    // output and the `error` behind it is never evaluated.
    let (out, err, code) = run_jq_full(
        &["-c", ".a | first((.b, error(\"never\")) // 9) | key"],
        Some(doc),
    )?;
    assert_eq!((out.trim(), code), ("\"b\"", 0), "#2782 -- stderr: {err:?}");
    Ok(())
}

/// #2730: `reverse` is jq-defined, not built in --
/// `def reverse: [.[length - 1 - range(0;length)]]` -- so a non-array's fate
/// is decided by its `length`, not its type. Anything whose length is `0`
/// never indexes and answers `[]`; a boolean fails inside `length`; the rest
/// reach `.[n]` and fail there. The issue found one cell (`{}`); the sweep
/// found seven, plus a string that was being *reversed* on the owned route
/// (`-n`), which no pinned jq does. Every cell captured against jq 1.7.1
/// (1.8.2 agrees), on both routes: the cursor route via stdin and the owned
/// route via `-n`.
#[test]
fn test_reverse_follows_jqs_own_definition_2730() -> Result<()> {
    // (input, expected stdout, expected exit, stderr fragment)
    let rows: &[(&str, &str, i32, &str)] = &[
        ("{}", "[]", 0, ""),
        ("null", "[]", 0, ""),
        ("0", "[]", 0, ""),
        ("-0", "[]", 0, ""),
        // Float zeros: `length` of a number is its `fabs`, so these are the
        // `Float(0.0)` half of `reverse_length_is_empty` as *documents* --
        // stdin `-0` parses to `Int(0)`, and only the owned route's unary
        // minus reaches the float arm through that row.
        ("0.0", "[]", 0, ""),
        ("-0.0", "[]", 0, ""),
        ("1e-400", "[]", 0, ""),
        (r#""""#, "[]", 0, ""),
        ("[]", "[]", 0, ""),
        ("[1,2]", "[2,1]", 0, ""),
        ("[[1],[2]]", "[[2],[1]]", 0, ""),
        (r#"{"a":1}"#, "", 5, "Cannot index object with number"),
        ("5", "", 5, "Cannot index number with number"),
        ("-3", "", 5, "Cannot index number with number"),
        ("0.5", "", 5, "Cannot index number with number"),
        // The row that used to answer "ba" on the owned route.
        (r#""ab""#, "", 5, "Cannot index string with number"),
        ("false", "", 5, "boolean (false) has no length"),
        ("true", "", 5, "boolean (true) has no length"),
    ];
    for (input, want_out, want_code, want_err) in rows {
        // cursor route
        let (out, err, code) = run_jq_full(&["-c", "reverse"], Some(input))?;
        assert_eq!(
            (out.trim(), code),
            (*want_out, *want_code),
            "#2730 cursor route: `{input} | reverse` -- stderr: {err:?}"
        );
        assert!(
            err.contains(want_err),
            "#2730 cursor route: `{input}` -- stderr: {err:?}"
        );
        // owned route -- parenthesised so a negative literal is an expression,
        // not a flag, and so `-0` is unary minus on 0 (length 0) as in jq.
        let (out, err, code) = run_jq_full(&["-nc", &format!("({input}) | reverse")], None)?;
        assert_eq!(
            (out.trim(), code),
            (*want_out, *want_code),
            "#2730 owned route: `-n '{input} | reverse'` -- stderr: {err:?}"
        );
        assert!(
            err.contains(want_err),
            "#2730 owned route: `{input}` -- stderr: {err:?}"
        );
    }
    // `?` suppresses the index error and the `length` error alike, as in jq.
    for input in [r#"{"a":1}"#, "true", r#""ab""#] {
        let (out, _, code) = run_jq_full(&["-c", "reverse?"], Some(input))?;
        assert_eq!((out.trim(), code), ("", 0), "#2730: `{input} | reverse?`");
    }
    // An undecodable string root now fails in `length` (a decode failure,
    // which `?` never suppresses) instead of at the type check, where the
    // old arm raised a plain index error that `?` *did* swallow -- exit 0 on
    // a document jq refuses to parse at all (`parse error: Invalid escape`,
    // exit 5). Both routes through `length` (`length?`, the hand-desugared
    // def) already behaved this way; `reverse` now agrees with them.
    for filter in ["reverse", "reverse?", "try reverse catch ."] {
        let (out, err, code) = run_jq_full(&["-c", filter], Some(r#""bad\x""#))?;
        assert_eq!(
            (out.trim(), code),
            ("", 5),
            "#2730: `{filter}` on an undecodable string -- stderr: {err:?}"
        );
        assert!(err.contains("invalid escape"), "stderr: {err:?}");
    }
    Ok(())
}

/// #2771: `owned_identity_step` (`src/jq/eval_generic.rs`) had no arm for
/// `Expr::Literal`, reachable only through `owned_identity_operand`'s
/// `Pipe`/`Paren`-wrapped case (its own top-level short-circuit already
/// handles the bare spelling) -- so a literal reached *through* a pipe
/// inside a ruled arithmetic/comparison operand, followed by a
/// `key`/`path`/`parent`/`file_index` metadata read downstream, aborted the
/// process with exit 101. A panic in the library is a failed assertion, a
/// panic in the binary is a crash, which is why this is asserted at the CLI
/// level, matching `test_path_cursor_walk_accepts_composite_pipe_heads_2061`.
///
/// Every expectation is what succinctly already produces for the bare
/// `(1 + 2)`-shaped analogue (a literal has no position of its own, so it
/// answers exactly like any other detached value would).
#[test]
fn test_literal_inside_pipe_operand_does_not_abort_2771() -> Result<()> {
    let input = r#"{"a":{"b":1}}"#;
    for (filter, want) in [
        (".a | ((.b | 1) + 2) | path", "[]\n"),
        (".a | ((.b | 1) + 2) | key", ""),
        (".a | ((.b | 1) + 2) | parent", ""),
        (".a | ((.b | 1) + 2) | file_index", "0\n"),
        (
            ".a | ((.b | 1) + 2) | [path, key, parent, file_index]",
            "[[],0]\n",
        ),
        (".a | ((1 | .) + 2) | key", ""),
        (".a | ((.b | 1) == 1) | path", "[]\n"),
        (".a | (-(.b | 1)) | path", "[]\n"),
        (
            r#".a | (("x" | .[0:1]) + "y") | path"#,
            "[{\"start\":0,\"end\":1}]\n",
        ),
        (
            r#".a | (("abc" | .)[0:1] + "x") | path"#,
            "[{\"start\":0,\"end\":1}]\n",
        ),
    ] {
        let (out, code) = run_jq_stdin(filter, input, &["-c"])?;
        assert_eq!(code, 0, "`{filter}`: out={out:?}");
        assert_eq!(out, want, "`{filter}`");
    }
    Ok(())
}

/// #2771 review: three shapes that must stay exactly as they were, so the
/// fix above is proven to add coverage rather than widen it. All three
/// confirmed live against jq 1.7.1.
#[test]
fn test_literal_inside_pipe_operand_must_not_change_shapes_2771() -> Result<()> {
    let input = r#"{"a":{"b":1}}"#;

    // `path(...)` wraps the same expression -- still a genuine "Invalid
    // path expression" compile-time-shaped runtime error, unaffected by
    // the identity-tracking fix (this route never reached the crash site).
    let (out, err, code) = run_jq_full(&["-c", "path(.a | ((.b | 1) + 2))"], Some(input))?;
    assert_eq!(code, 5, "out={out:?} err={err:?}");
    assert!(
        err.contains("Invalid path expression with result 3"),
        "err={err:?}"
    );

    // The bare arithmetic, with no downstream metadata read, is untouched.
    let (out, code) = run_jq_stdin(".a | ((.b | 1) + 2)", input, &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(out, "3\n");

    // An empty operand value stream never reaches the identity route at
    // all, so this stays empty/exit 0 as it did before.
    let (out, code) = run_jq_stdin(".a | ((1 | .b?) + 2) | path", input, &["-c"])?;
    assert_eq!(code, 0);
    assert_eq!(out, "");
    Ok(())
}
